var e={"dish:Sausage roll":{wiki:{title:`Sausage roll`,url:`https://en.wikipedia.org/wiki/Sausage_roll`,extract:`A sausage roll is a savoury dish, popular in current and former Commonwealth nations, consisting of sausage meat wrapped in puff pastry. Although variations are known throughout Europe and in other regions, the sausage roll is most closely associated with British cuisine. The British bakery chain Greggs sells around 2.5 million sausage rolls per week, or around 140 million per year.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4e/Sausage_roll_-_One_Market%2C_One_Garden_Brighton_%28cropped%29.jpg/960px-Sausage_roll_-_One_Market%2C_One_Garden_Brighton_%28cropped%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Sausage_roll_-_One_Market,_One_Garden_Brighton_(cropped).jpg`,artist:`Andy Li`,license:`CC0`}},"dish:Flat white":{wiki:{title:`Flat white`,url:`https://en.wikipedia.org/wiki/Flat_white`,extract:`A flat white is a drink consisting of espresso coffee and steamed milk. It generally has a higher proportion of espresso to milk than a latte, and does not have the thick layer of foam of a cappuccino. The origin of the flat white is unclear; café owners in both Australia and New Zealand claim its invention. The name, however, was in use in England in the 1960s for an espresso-based coffee.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/Flat_white_coffee_with_pretty_feather_pattern.jpg/960px-Flat_white_coffee_with_pretty_feather_pattern.jpg`,page:`https://commons.wikimedia.org/wiki/File:Flat_white_coffee_with_pretty_feather_pattern.jpg`,artist:`GeorgeMichaelFarewell`,license:`CC BY-SA 4.0`}},"dish:Katsudon":{wiki:{title:`Katsudon`,url:`https://en.wikipedia.org/wiki/Katsudon`,extract:`Katsudon is a popular Japanese food, a bowl of rice topped with a fried tonkatsu pork cutlet, egg, vegetables, and condiments. The dish's name is a portmanteau of the Japanese words tonkatsu and donburi.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/Katsudon_001.jpg/960px-Katsudon_001.jpg`,page:`https://commons.wikimedia.org/wiki/File:Katsudon_001.jpg`,artist:`Ocdp`,license:`CC0`}},"dish:Mapo tofu":{wiki:{title:`Mapo tofu`,url:`https://en.wikipedia.org/wiki/Mapo_tofu`,extract:`Mapo tofu is a popular Chinese dish from Sichuan province. It consists of tofu set in a spicy sauce, typically a thin, oily, and bright red suspension, based on douban, and douchi, along with minced meat, traditionally beef. Variations exist with other ingredients such as water chestnuts, onions, other vegetables, or wood ear fungus. It is likely to have originated at a Chengdu restaurant in the 1860s–1870s.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/8/88/Chen_Mapo_Tofu.jpg/960px-Chen_Mapo_Tofu.jpg`,page:`https://commons.wikimedia.org/wiki/File:Chen_Mapo_Tofu.jpg`,artist:`ZhengZhou`,license:`CC BY-SA 4.0`}},"dish:Schnitzel":{wiki:{title:`Schnitzel`,url:`https://en.wikipedia.org/wiki/Schnitzel`,extract:`Schnitzel is a thin slice of meat. The meat is usually thinned by pounding with a meat tenderizer. Most commonly, the meat is breaded before frying. Breaded schnitzel is popular in many countries and is made using veal, pork, chicken, mutton, beef, or turkey. Schnitzel originated as Wiener schnitzel and is very similar to other breaded meat dishes.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/22/Breitenlesau_Krug_Br%C3%A4u_Schnitzel.JPG/960px-Breitenlesau_Krug_Br%C3%A4u_Schnitzel.JPG`,page:`https://commons.wikimedia.org/wiki/File:Breitenlesau_Krug_Br%C3%A4u_Schnitzel.JPG`,artist:`Benreis`,license:`CC BY-SA 3.0`}},"dish:Schweinshaxe":{wiki:{title:`Schweinshaxe`,url:`https://en.wikipedia.org/wiki/Schweinshaxe`,extract:`Schweinshaxe (German pronunciation: [ˈʃvaɪnshaksə] ; literally 'swine's hock'), in German cuisine, is a roasted ham hock (or pork knuckle). The ham hock is the end of the pig's leg, just above the ankle and below the meaty ham portion. It is especially popular in Bavaria as Schweinshaxn (pronounced [ˈʃvaɪnshaksn̩]) or Sauhax(n).`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/5/54/00ane_Haxen.jpg`,page:`https://commons.wikimedia.org/wiki/File:00ane_Haxen.jpg`,artist:`Erich Ferdinand`,license:`CC BY 2.0`}},"brisbane/Moreton Bay bugs":{wiki:{title:`Thenus`,url:`https://en.wikipedia.org/wiki/Thenus`,extract:`Thenus orientalis is a species of slipper lobster from the Indian and Pacific oceans.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/3/31/Flathausahumar.png`,page:`https://commons.wikimedia.org/wiki/File:Flathausahumar.png`,artist:`Helgabjorg`,license:`CC BY-SA 4.0`}},"brisbane/Barramundi":{wiki:{title:`Barramundi`,url:`https://en.wikipedia.org/wiki/Barramundi`,extract:`The barramundi, Asian sea bass, Asian sea lates, giant sea lates, or giant sea perch is a species of catadromous fish in the family Latidae of the order Carangiformes. The species is widely distributed in the Indo-West Pacific, spanning the waters of the Middle East, South Asia, Southeast Asia, East Asia, and Oceania.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/50/Lates_calcarifer%2C_2014-09-19a.jpg/960px-Lates_calcarifer%2C_2014-09-19a.jpg`,page:`https://commons.wikimedia.org/wiki/File:Lates_calcarifer,_2014-09-19a.jpg`,artist:`Mitch Ames`,license:`CC BY-SA 4.0`}},"brisbane/Queensland steak":{wiki:{title:`Steak`,url:`https://en.wikipedia.org/wiki/Steak`,extract:`A steak is a cut of meat sliced across muscle fibers, sometimes including a bone. It is normally grilled or fried, and can be diced or cooked in sauce. In some cases, like in the dish steak tartare, the meat is eaten raw.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f4/Steak_with_shitaki_mushrooms.jpg/960px-Steak_with_shitaki_mushrooms.jpg`,page:`https://commons.wikimedia.org/wiki/File:Steak_with_shitaki_mushrooms.jpg`,artist:`Jon Sullivan`,license:`Public domain`}},"brisbane/Fish and chips":{wiki:{title:`Fish and chips`,url:`https://en.wikipedia.org/wiki/Fish_and_chips`,extract:`Fish and chips is a hot dish consisting of battered and fried fish served with chips. Often considered the national dish of the United Kingdom, fish and chips originated in England in the 19th century. Today, the dish is a common takeaway food in numerous other countries, particularly English-speaking and Commonwealth nations.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/Fish_and_chips_blackpool.jpg/960px-Fish_and_chips_blackpool.jpg`,page:`https://commons.wikimedia.org/wiki/File:Fish_and_chips_blackpool.jpg`,artist:`Matthias Meckel`,license:`CC BY-SA 4.0`}},"brisbane/Lamington":{wiki:{title:`Lamington`,url:`https://en.wikipedia.org/wiki/Lamington`,extract:`A lamington is an Australian cake made from squares of butter cake or sponge cake coated in an outer layer of chocolate sauce and rolled in desiccated coconut. The thin mixture is absorbed into the outside of the sponge cake and left to set, giving the cake a distinctive texture. A common variation has a layer of cream or strawberry jam between two lamington halves.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/Mocha_Flake_amingtons.jpg/960px-Mocha_Flake_amingtons.jpg`,page:`https://commons.wikimedia.org/wiki/File:Mocha_Flake_amingtons.jpg`,artist:`Zeitgeistlondon`,license:`CC BY-SA 3.0`}},"brisbane/Mango":{wiki:{title:`Mango`,url:`https://en.wikipedia.org/wiki/Mango`,extract:`A mango is an edible stone fruit produced by the tropical tree Mangifera indica. It originated in the northeastern part of the South Asia, in what is now Bangladesh, northeastern India and Myanmar. M. indica has been cultivated in South and Southeast Asia since ancient times, resulting in two modern mango cultivar lineages: the "Indian" and the "Southeast Asian" types.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/Mangos_-_single_and_halved.jpg/960px-Mangos_-_single_and_halved.jpg`,page:`https://commons.wikimedia.org/wiki/File:Mangos_-_single_and_halved.jpg`,artist:`Ivar Leidus`,license:`CC BY-SA 4.0`}},"dish:Saccostrea glomerata":{wiki:{title:`Saccostrea glomerata`,url:`https://en.wikipedia.org/wiki/Saccostrea_glomerata`,extract:`Saccostrea glomerata is an oyster species belonging to the family Ostreidae.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/Sydney_rock_oysters.jpg/960px-Sydney_rock_oysters.jpg`,page:`https://commons.wikimedia.org/wiki/File:Sydney_rock_oysters.jpg`,artist:`No machine-readable author provided. Stevage assumed (based on copyright claims).`,license:`CC BY 2.5`}},"dish:Fish and chips":{wiki:{title:`Fish and chips`,url:`https://en.wikipedia.org/wiki/Fish_and_chips`,extract:`Fish and chips is a hot dish consisting of battered and fried fish served with chips. Often considered the national dish of the United Kingdom, fish and chips originated in England in the 19th century. Today, the dish is a common takeaway food in numerous other countries, particularly English-speaking and Commonwealth nations.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/Fish_and_chips_blackpool.jpg/960px-Fish_and_chips_blackpool.jpg`,page:`https://commons.wikimedia.org/wiki/File:Fish_and_chips_blackpool.jpg`,artist:`Matthias Meckel`,license:`CC BY-SA 4.0`}},"dish:Sashimi":{wiki:{title:`Sashimi`,url:`https://en.wikipedia.org/wiki/Sashimi`,extract:`Sashimi is a Japanese delicacy that consists of fresh raw fish or other raw meat that is sliced into thin pieces, and is often eaten with soy sauce.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/241109_Shigaraki_ware_Koga_Shiga_pref_Japan01s3.jpg/960px-241109_Shigaraki_ware_Koga_Shiga_pref_Japan01s3.jpg`,page:`https://commons.wikimedia.org/wiki/File:241109_Shigaraki_ware_Koga_Shiga_pref_Japan01s3.jpg`,artist:`663highland`,license:`CC BY-SA 4.0`}},"dish:Meat pie (Australia and New Zealand)":{wiki:{title:`Meat pie (Australia and New Zealand)`,url:`https://en.wikipedia.org/wiki/Meat_pie_(Australia_and_New_Zealand)`,extract:`In Australia and New Zealand, a meat pie is a handheld meat pie containing diced or minced meat and gravy, sometimes with other ingredients, in a piecrust. It is often consumed as a takeaway food snack.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/b/b2/Meat_pie.jpg`,page:`https://commons.wikimedia.org/wiki/File:Meat_pie.jpg`,artist:`fir0002 flagstaffotos [at] gmail.com Canon 20D + Canon 17-40mm f/4 L`,license:`GFDL 1.2`}},"dish:Hot dog":{wiki:{title:`Hot dog`,url:`https://en.wikipedia.org/wiki/Hot_dog`,extract:`A hot dog is a grilled, steamed, or boiled sausage served in the slit of a partially sliced bun. The term hot dog can also refer to the sausage itself. The sausage used is a wiener or a frankfurter. The names of these sausages commonly refer to their assembled dish. Hot dog preparation and condiments vary worldwide. Common condiments include mustard, ketchup, relish, onions in tomato sauce, and cheese sauce.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b1/Hot_dog_with_mustard.png/960px-Hot_dog_with_mustard.png`,page:`https://commons.wikimedia.org/wiki/File:Hot_dog_with_mustard.png`,artist:`Czar , original photographed by Renee Comet`,license:`Public domain`}},"dish:Sourdough":{wiki:{title:`Sourdough`,url:`https://en.wikipedia.org/wiki/Sourdough`,extract:`Sourdough is a leavening agent containing naturally occurring yeast and lactobacillus bacteria. The term is used to describe bread baked with sourdough, while the sourdough itself is referred to as a starter. In addition to leavening the bread, the fermentation process produces lactic acid, which gives the bread its distinctive sour taste and improves its keeping qualities.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/Home_made_sour_dough_bread.jpg/960px-Home_made_sour_dough_bread.jpg`,page:`https://commons.wikimedia.org/wiki/File:Home_made_sour_dough_bread.jpg`,artist:`Tomascastelazo`,license:`CC BY-SA 4.0`}},"dish:Avocado toast":{wiki:{title:`Avocado toast`,url:`https://en.wikipedia.org/wiki/Avocado_toast`,extract:`Avocado toast is an open sandwich consisting of toasted bread topped with mashed avocado, plus any of a variety of spices and flavorful ingredients; the most popular include salt and black pepper, lemon juice, or other citrus flavors, olive oil, hummus, vinegar, red pepper, feta, duqqa, and tomato.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/Avocado_toast_at_Voyager_Espresso_%2833134505776%29.jpg/960px-Avocado_toast_at_Voyager_Espresso_%2833134505776%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Avocado_toast_at_Voyager_Espresso_(33134505776).jpg`,artist:`Bex Walton from London, England`,license:`CC BY 2.0`}},"dish:Roti canai":{wiki:{title:`Roti canai`,url:`https://en.wikipedia.org/wiki/Roti_canai`,extract:`Roti canai, or roti prata, also known as roti chanai and roti cane, is an unleavened flatbread of Indian origin found in the cuisines of Southeast Asia, especially those of Brunei, Indonesia, Malaysia, Singapore, and Thailand.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/YosriRotiCanai.jpg/960px-YosriRotiCanai.jpg`,page:`https://commons.wikimedia.org/wiki/File:YosriRotiCanai.jpg`,artist:`Yosri at ms.wikipedia`,license:`GFDL`}},"dish:Nasi lemak":{wiki:{title:`Nasi lemak`,url:`https://en.wikipedia.org/wiki/Nasi_lemak`,extract:`Nasi lemak is a dish originating in Malay cuisine that consists of rice cooked in coconut milk and pandan leaf. It is commonly found in Malaysia, where it is considered the national dish. As it is common throughout the Malay world, it is also a native dish in neighbouring areas with significant ethnic Malay populations, such as Singapore and Southern Thailand.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/Nasi_Lemak_dengan_Chili_Nasi_Lemak_dan_Sotong_Pedas%2C_di_Penang_Summer_Restaurant.jpg/960px-Nasi_Lemak_dengan_Chili_Nasi_Lemak_dan_Sotong_Pedas%2C_di_Penang_Summer_Restaurant.jpg`,page:`https://commons.wikimedia.org/wiki/File:Nasi_Lemak_dengan_Chili_Nasi_Lemak_dan_Sotong_Pedas,_di_Penang_Summer_Restaurant.jpg`,artist:`Meandkancil2020`,license:`CC BY-SA 4.0`}},"dish:Pad see ew":{wiki:{title:`Pad see ew`,url:`https://en.wikipedia.org/wiki/Pad_see_ew`,extract:`Pad see ew is a stir-fried noodle dish that is commonly eaten in Thailand. It can be found easily among street food vendors and is also common in Thai restaurants around the world. The origins of the dish can be traced to China, from where the noodle stir-frying technique was brought.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Pad_see_ew.jpg/960px-Pad_see_ew.jpg`,page:`https://commons.wikimedia.org/wiki/File:Pad_see_ew.jpg`,artist:`stu_spivack`,license:`CC BY-SA 2.0`}},"dish:Boat noodles":{wiki:{title:`Boat noodles`,url:`https://en.wikipedia.org/wiki/Boat_noodles`,extract:`Boat noodles is a Thai-style noodle dish with a strong flavor. It contains both pork and beef, as well as dark soy sauce, pickled bean curd, and some other spices, and it is normally served with meatballs and pig's liver. The soup is seasoned with pig or cow blood mixed with salt and spices. The colour is similar to that of beef noodle soup, but the soup is considerably thicker due to the added blood.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7c/Boat_noodles.jpg/960px-Boat_noodles.jpg`,page:`https://commons.wikimedia.org/wiki/File:Boat_noodles.jpg`,artist:`Flickr user Alpha`,license:`CC BY-SA 2.0`}},"dish:Mango sticky rice":{wiki:{title:`Mango sticky rice`,url:`https://en.wikipedia.org/wiki/Mango_sticky_rice`,extract:`Mango sticky rice is a traditional Southeast Asian and South Asian dessert made with glutinous rice, fresh mango and coconut milk.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Mango_sticy_rice_%283859549574%29.jpg/960px-Mango_sticy_rice_%283859549574%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Mango_sticy_rice_(3859549574).jpg`,artist:`Dennis Wong from Hong Kong, Hong Kong`,license:`CC BY 2.0`}},"sydney/Sydney rock oysters":{wiki:{title:`Saccostrea glomerata`,url:`https://en.wikipedia.org/wiki/Saccostrea_glomerata`,extract:`Saccostrea glomerata is an oyster species belonging to the family Ostreidae.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/Sydney_rock_oysters.jpg/960px-Sydney_rock_oysters.jpg`,page:`https://commons.wikimedia.org/wiki/File:Sydney_rock_oysters.jpg`,artist:`No machine-readable author provided. Stevage assumed (based on copyright claims).`,license:`CC BY 2.5`}},"sydney/Fish and chips by the beach":{wiki:{title:`Fish and chips`,url:`https://en.wikipedia.org/wiki/Fish_and_chips`,extract:`Fish and chips is a hot dish consisting of battered and fried fish served with chips. Often considered the national dish of the United Kingdom, fish and chips originated in England in the 19th century. Today, the dish is a common takeaway food in numerous other countries, particularly English-speaking and Commonwealth nations.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/Fish_and_chips_blackpool.jpg/960px-Fish_and_chips_blackpool.jpg`,page:`https://commons.wikimedia.org/wiki/File:Fish_and_chips_blackpool.jpg`,artist:`Matthias Meckel`,license:`CC BY-SA 4.0`}},"sydney/Smashed avo and a flat white":{wiki:{title:`Avocado toast`,url:`https://en.wikipedia.org/wiki/Avocado_toast`,extract:`Avocado toast is an open sandwich consisting of toasted bread topped with mashed avocado, plus any of a variety of spices and flavorful ingredients; the most popular include salt and black pepper, lemon juice, or other citrus flavors, olive oil, hummus, vinegar, red pepper, feta, duqqa, and tomato.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/Avocado_toast_at_Voyager_Espresso_%2833134505776%29.jpg/960px-Avocado_toast_at_Voyager_Espresso_%2833134505776%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Avocado_toast_at_Voyager_Espresso_(33134505776).jpg`,artist:`Bex Walton from London, England`,license:`CC BY 2.0`}},"sydney/Meat pie":{wiki:{title:`Meat pie`,url:`https://en.wikipedia.org/wiki/Meat_pie`,extract:`A meat pie is a pie baked with pastry with a filling of meat and often other savory ingredients. They are found in cuisines worldwide.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/MeatPie.JPG/960px-MeatPie.JPG`,page:`https://commons.wikimedia.org/wiki/File:MeatPie.JPG`,artist:`Jonathunder`,license:`CC BY-SA 3.0`}},"sydney/Pavlova":{wiki:{title:`Pavlova`,url:`https://en.wikipedia.org/wiki/Pavlova`,extract:`Pavlova is a meringue-based dessert. Originating in either Australia or New Zealand in the early 20th century, it was named after the Russian ballerina Anna Pavlova. Taking the form of a cake-like circular block of baked meringue, pavlova has a crisp crust and soft, light inside. The confection is usually topped with fruit and whipped cream.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/67/Pavlova_dessert.JPG/960px-Pavlova_dessert.JPG`,page:`https://commons.wikimedia.org/wiki/File:Pavlova_dessert.JPG`,artist:`Hazel Fowler`,license:`Public domain`}},"sydney/Lamington":{wiki:{title:`Lamington`,url:`https://en.wikipedia.org/wiki/Lamington`,extract:`A lamington is an Australian cake made from squares of butter cake or sponge cake coated in an outer layer of chocolate sauce and rolled in desiccated coconut. The thin mixture is absorbed into the outside of the sponge cake and left to set, giving the cake a distinctive texture. A common variation has a layer of cream or strawberry jam between two lamington halves.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/Mocha_Flake_amingtons.jpg/960px-Mocha_Flake_amingtons.jpg`,page:`https://commons.wikimedia.org/wiki/File:Mocha_Flake_amingtons.jpg`,artist:`Zeitgeistlondon`,license:`CC BY-SA 3.0`}},"dish:Jelly doughnut":{wiki:{title:`Jelly doughnut`,url:`https://en.wikipedia.org/wiki/Jelly_doughnut`,extract:`A jelly doughnut, or jam doughnut, is a doughnut with a fruit preserve filling.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Jelly-Donut.jpg/960px-Jelly-Donut.jpg`,page:`https://commons.wikimedia.org/wiki/File:Jelly-Donut.jpg`,artist:`Evan-Amos`,license:`Public domain`}},"dish:Spaghetti bolognese":{wiki:{title:`Bolognese sauce`,url:`https://en.wikipedia.org/wiki/Bolognese_sauce`,extract:`Bolognese sauce, known in Italian as ragù alla bolognese or ragù bolognese, is the main variety of ragù in Italian cuisine, typical of the city of Bologna.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/Tagliatelle_al_rag%C3%B9_%28image_modified%29.jpg/960px-Tagliatelle_al_rag%C3%B9_%28image_modified%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Tagliatelle_al_rag%C3%B9_(image_modified).jpg`,artist:`Ivan Vighetto`,license:`CC BY-SA 3.0`}},"dish:Espresso":{wiki:{title:`Espresso`,url:`https://en.wikipedia.org/wiki/Espresso`,extract:`Espresso is a concentrated form of coffee produced by forcing hot water under high pressure through finely ground coffee beans. Originating in Italy, espresso has become one of the most popular coffee-brewing methods worldwide. It is characterized by its small serving size, typically 25–30 ml, and its distinctive layers: a dark body topped with a lighter-colored foam called "crema".`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a5/Tazzina_di_caff%C3%A8_a_Ventimiglia.jpg/960px-Tazzina_di_caff%C3%A8_a_Ventimiglia.jpg`,page:`https://commons.wikimedia.org/wiki/File:Tazzina_di_caff%C3%A8_a_Ventimiglia.jpg`,artist:`Lemone`,license:`CC BY-SA 4.0`}},"dish:Granita":{wiki:{title:`Granita`,url:`https://en.wikipedia.org/wiki/Granita`,extract:`Granita or granita siciliana is a type of sorbet made from sugar solutions flavored with lemon, coffee, or fruit juices, and stirred during freezing to produce a soft mixture made up of many tiny ice crystals. Originally from Sicily, it is available throughout Italy in varying forms.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/37/Granita_originelle_au_citron_de_Sicile.jpg/960px-Granita_originelle_au_citron_de_Sicile.jpg`,page:`https://commons.wikimedia.org/wiki/File:Granita_originelle_au_citron_de_Sicile.jpg`,artist:`Angelo57p`,license:`CC BY-SA 4.0`}},"dish:Croissant":{wiki:{title:`Croissant`,url:`https://en.wikipedia.org/wiki/Croissant`,extract:`A croissant is a Viennoiserie in a crescent shape made from a laminated yeast dough that sits between a bread and a puff pastry.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/Croissant-Petr_Kratochvil.jpg/960px-Croissant-Petr_Kratochvil.jpg`,page:`https://commons.wikimedia.org/wiki/File:Croissant-Petr_Kratochvil.jpg`,artist:`Petr Kratochvil`,license:`CC0`}},"dish:Souvlaki":{wiki:{title:`Souvlaki`,url:`https://en.wikipedia.org/wiki/Souvlaki`,extract:`Souvlaki is a Greek food consisting of small pieces of meat and sometimes vegetables grilled on a skewer. It is usually eaten straight off the skewer while still hot. It can be served with or inside a rolled pita, typically with lemon, sauces, vegetables such as sliced tomato and onion, and fried potatoes as a side. The meat usually used in Greece and Cyprus is pork.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/%CE%95%CE%BB%CE%BB%CE%B7%CE%BD%CE%B9%CE%BA%CF%8C_%CE%A3%CE%BF%CF%85%CE%B2%CE%BB%CE%AC%CE%BA%CE%B9_-_panoramio.jpg/960px-%CE%95%CE%BB%CE%BB%CE%B7%CE%BD%CE%B9%CE%BA%CF%8C_%CE%A3%CE%BF%CF%85%CE%B2%CE%BB%CE%AC%CE%BA%CE%B9_-_panoramio.jpg`,page:`https://commons.wikimedia.org/wiki/File:%CE%95%CE%BB%CE%BB%CE%B7%CE%BD%CE%B9%CE%BA%CF%8C_%CE%A3%CE%BF%CF%85%CE%B2%CE%BB%CE%AC%CE%BA%CE%B9_-_panoramio.jpg`,artist:`EntaXoyas`,license:`CC BY-SA 3.0`}},"dish:Chicken parmesan":{wiki:{title:`Chicken parmesan`,url:`https://en.wikipedia.org/wiki/Chicken_parmesan`,extract:`Chicken parmesan or chicken parmigiana is a dish that consists of fried breaded chicken breast covered in tomato sauce and mozzarella, Parmesan or provolone. Ham or bacon is sometimes added.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/17/Chicken_parm_at_a_diner.jpg/960px-Chicken_parm_at_a_diner.jpg`,page:`https://commons.wikimedia.org/wiki/File:Chicken_parm_at_a_diner.jpg`,artist:`Oknazevad`,license:`CC BY-SA 4.0`}},"dish:Dim sim":{wiki:{title:`Dim sim`,url:`https://en.wikipedia.org/wiki/Dim_sim`,extract:`A dim sim is a meat and vegetable dumpling snack, inspired by Cantonese Dim Sum, that is popular in Australia. It was popularised in the 1940s by William Chen Wing Young, a Chinese Australian born in Wahgunyah, Victoria in 1896. Young's family originally came from Guangdong, and he was the father of Australian celebrity chef Elizabeth Chong. The name derives from the pronunciation diam1 sim² (點心) in Teochew.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/Fried_and_steamed_dim_sim_%28cropped%29.jpg/960px-Fried_and_steamed_dim_sim_%28cropped%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Fried_and_steamed_dim_sim_(cropped).jpg`,artist:`Finbar.concaig`,license:`CC BY-SA 4.0`}},"melbourne/Flat white":{wiki:{title:`Flat white`,url:`https://en.wikipedia.org/wiki/Flat_white`,extract:`A flat white is a drink consisting of espresso coffee and steamed milk. It generally has a higher proportion of espresso to milk than a latte, and does not have the thick layer of foam of a cappuccino. The origin of the flat white is unclear; café owners in both Australia and New Zealand claim its invention. The name, however, was in use in England in the 1960s for an espresso-based coffee.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/Flat_white_coffee_with_pretty_feather_pattern.jpg/960px-Flat_white_coffee_with_pretty_feather_pattern.jpg`,page:`https://commons.wikimedia.org/wiki/File:Flat_white_coffee_with_pretty_feather_pattern.jpg`,artist:`GeorgeMichaelFarewell`,license:`CC BY-SA 4.0`}},"melbourne/Hot jam doughnuts":{wiki:{title:`Jelly doughnut`,url:`https://en.wikipedia.org/wiki/Jelly_doughnut`,extract:`A jelly doughnut, or jam doughnut, is a doughnut with a fruit preserve filling.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Jelly-Donut.jpg/960px-Jelly-Donut.jpg`,page:`https://commons.wikimedia.org/wiki/File:Jelly-Donut.jpg`,artist:`Evan-Amos`,license:`Public domain`}},"melbourne/Chicken parma":{wiki:{title:`Chicken parmesan`,url:`https://en.wikipedia.org/wiki/Chicken_parmesan`,extract:`Chicken parmesan or chicken parmigiana is a dish that consists of fried breaded chicken breast covered in tomato sauce and mozzarella, Parmesan or provolone. Ham or bacon is sometimes added.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/17/Chicken_parm_at_a_diner.jpg/960px-Chicken_parm_at_a_diner.jpg`,page:`https://commons.wikimedia.org/wiki/File:Chicken_parm_at_a_diner.jpg`,artist:`Oknazevad`,license:`CC BY-SA 4.0`}},"melbourne/Souvlaki":{wiki:{title:`Souvlaki`,url:`https://en.wikipedia.org/wiki/Souvlaki`,extract:`Souvlaki is a Greek food consisting of small pieces of meat and sometimes vegetables grilled on a skewer. It is usually eaten straight off the skewer while still hot. It can be served with or inside a rolled pita, typically with lemon, sauces, vegetables such as sliced tomato and onion, and fried potatoes as a side. The meat usually used in Greece and Cyprus is pork.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/%CE%95%CE%BB%CE%BB%CE%B7%CE%BD%CE%B9%CE%BA%CF%8C_%CE%A3%CE%BF%CF%85%CE%B2%CE%BB%CE%AC%CE%BA%CE%B9_-_panoramio.jpg/960px-%CE%95%CE%BB%CE%BB%CE%B7%CE%BD%CE%B9%CE%BA%CF%8C_%CE%A3%CE%BF%CF%85%CE%B2%CE%BB%CE%AC%CE%BA%CE%B9_-_panoramio.jpg`,page:`https://commons.wikimedia.org/wiki/File:%CE%95%CE%BB%CE%BB%CE%B7%CE%BD%CE%B9%CE%BA%CF%8C_%CE%A3%CE%BF%CF%85%CE%B2%CE%BB%CE%AC%CE%BA%CE%B9_-_panoramio.jpg`,artist:`EntaXoyas`,license:`CC BY-SA 3.0`}},"melbourne/Dim sims":{wiki:{title:`Dim sim`,url:`https://en.wikipedia.org/wiki/Dim_sim`,extract:`A dim sim is a meat and vegetable dumpling snack, inspired by Cantonese Dim Sum, that is popular in Australia. It was popularised in the 1940s by William Chen Wing Young, a Chinese Australian born in Wahgunyah, Victoria in 1896. Young's family originally came from Guangdong, and he was the father of Australian celebrity chef Elizabeth Chong. The name derives from the pronunciation diam1 sim² (點心) in Teochew.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/Fried_and_steamed_dim_sim_%28cropped%29.jpg/960px-Fried_and_steamed_dim_sim_%28cropped%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Fried_and_steamed_dim_sim_(cropped).jpg`,artist:`Finbar.concaig`,license:`CC BY-SA 4.0`}},"melbourne/Laneway brunch":{wiki:{title:`Brunch`,url:`https://en.wikipedia.org/wiki/Brunch`,extract:`Brunch is a meal eaten in the late morning as a combination of a late breakfast and early lunch. In practice commercial establishments often offer brunch style foods outside of this period. The word brunch is a portmanteau of breakfast and lunch.`}},"dish:Rosette de Lyon":{wiki:{title:`Rosette de Lyon`,url:`https://en.wikipedia.org/wiki/Rosette_de_Lyon`,extract:`Rosette de Lyon is a cured saucisson from France. It is made from pork and usually served thinly sliced.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6e/Rosette_de_Lyon.jpg/960px-Rosette_de_Lyon.jpg`,page:`https://commons.wikimedia.org/wiki/File:Rosette_de_Lyon.jpg`,artist:`Jules Morgan`,license:`CC BY 2.0`}},"dish:Quenelle":{wiki:{title:`Quenelle`,url:`https://en.wikipedia.org/wiki/Quenelle`,extract:`A quenelle is a mixture of creamed fish or meat, sometimes combined with breadcrumbs, with a light egg binding, formed into an egg-like shape, and then cooked. The usual preparation is by poaching. Formerly, quenelles were often used as a garnish in haute cuisine. Today, they are more commonly served sauced as a dish in their own right. Similar items are found in many cuisines.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dd/Quenelle_de_brochet_sauce_Nantua.jpg/960px-Quenelle_de_brochet_sauce_Nantua.jpg`,page:`https://commons.wikimedia.org/wiki/File:Quenelle_de_brochet_sauce_Nantua.jpg`,artist:`Fryke27`,license:`CC BY-SA 3.0`}},"dish:Pâté en croûte":{wiki:{title:`Pâté`,url:`https://en.wikipedia.org/wiki/P%C3%A2t%C3%A9`,extract:`Pâté is a forcemeat. Originally, the dish was cooked in a pastry case and called pâté en croute; in more recent times it is more usually cooked without pastry in a terrine, and called pâté en terrine or simply terrine. Various ingredients are used, which may include meat from pork, poultry, fish or beef; fat; vegetables; herbs; spices; wine; and brandy.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/Pates_p1150435.jpg/960px-Pates_p1150435.jpg`,page:`https://commons.wikimedia.org/wiki/File:Pates_p1150435.jpg`,artist:`David Monniaux`,license:`CC BY-SA 3.0`}},"dish:Choucroute garnie":{wiki:{title:`Choucroute garnie`,url:`https://en.wikipedia.org/wiki/Choucroute_garnie`,extract:`Choucroute garnie is an Alsatian recipe of sauerkraut with sausages and other salted meats and charcuterie, and often potatoes.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/2021-01-10_13-08-38_ILCE-6500_DSC01353_DxO_%2850958169387%29.jpg/960px-2021-01-10_13-08-38_ILCE-6500_DSC01353_DxO_%2850958169387%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:2021-01-10_13-08-38_ILCE-6500_DSC01353_DxO_(50958169387).jpg`,artist:`Miguel Discart`,license:`CC BY-SA 2.0`}},"lyon/Pike quenelle":{wiki:{title:`Quenelle`,url:`https://en.wikipedia.org/wiki/Quenelle`,extract:`A quenelle is a mixture of creamed fish or meat, sometimes combined with breadcrumbs, with a light egg binding, formed into an egg-like shape, and then cooked. The usual preparation is by poaching. Formerly, quenelles were often used as a garnish in haute cuisine. Today, they are more commonly served sauced as a dish in their own right. Similar items are found in many cuisines.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dd/Quenelle_de_brochet_sauce_Nantua.jpg/960px-Quenelle_de_brochet_sauce_Nantua.jpg`,page:`https://commons.wikimedia.org/wiki/File:Quenelle_de_brochet_sauce_Nantua.jpg`,artist:`Fryke27`,license:`CC BY-SA 3.0`}},"lyon/Silk weaver's cheese":{wiki:{title:`Cervelle de canut`,url:`https://en.wikipedia.org/wiki/Cervelle_de_canut`,extract:`Cervelle de canut is a cheese spread or dip that is a specialty of Lyon, France.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/76/Cervelle_des_Canuts_servis_dans_le_Vieux_Lyon.jpg/960px-Cervelle_des_Canuts_servis_dans_le_Vieux_Lyon.jpg`,page:`https://commons.wikimedia.org/wiki/File:Cervelle_des_Canuts_servis_dans_le_Vieux_Lyon.jpg`,artist:`Jean-Marc ALBERT`,license:`CC BY-SA 3.0`}},"lyon/Fireman's apron":{wiki:{title:`Tablier de sapeur`,url:`https://en.wikipedia.org/wiki/Tablier_de_sapeur`,extract:`Tablier de sapeur is a Lyonnais speciality dish made from beef tripe, specifically the gras-double, which is the membrane of the rumen. It is one of the most common dishes served in the bouchons of Lyon.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Tablier_de_sapeur_-_d%C3%A9cember_2016.JPG/960px-Tablier_de_sapeur_-_d%C3%A9cember_2016.JPG`,page:`https://commons.wikimedia.org/wiki/File:Tablier_de_sapeur_-_d%C3%A9cember_2016.JPG`,artist:`Anca Luca`,license:`CC BY-SA 4.0`}},"lyon/Andouillette":{wiki:{title:`Andouillette`,url:`https://en.wikipedia.org/wiki/Andouillette`,extract:`Andouillette is a French coarse-grained sausage made from the intestine of pork, pepper, wine, onions, and seasonings.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9f/Andouillette_AAAAA_cuite.jpg/960px-Andouillette_AAAAA_cuite.jpg`,page:`https://commons.wikimedia.org/wiki/File:Andouillette_AAAAA_cuite.jpg`,artist:`DocteurCosmos`,license:`CC BY-SA 3.0`}},"dish:Steak frites":{wiki:{title:`Steak frites`,url:`https://en.wikipedia.org/wiki/Steak_frites`,extract:`Steak frites, meaning "steak [and] chipped potatoes" in French, is a dish consisting of beefsteak accompanied by fried chipped potatoes. It is commonly served in Belgian and French brasseries, and is considered by some to be the national dish of Belgium, which claims to be the country of origin.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9a/Reel_and_Brand_-_September_2021_-_Sarah_Stierch_05.jpg/960px-Reel_and_Brand_-_September_2021_-_Sarah_Stierch_05.jpg`,page:`https://commons.wikimedia.org/wiki/File:Reel_and_Brand_-_September_2021_-_Sarah_Stierch_05.jpg`,artist:`Missvain`,license:`CC BY 4.0`}},"dish:Escargot":{wiki:{title:`Snails as food`,url:`https://en.wikipedia.org/wiki/Snails_as_food`,extract:`Snails are eaten by humans in many areas such as Africa, Southeast Asia and Mediterranean Europe, while in other cultures, snails are seen as a taboo food. Borrowed from the French word for 'snail', the term escargot is what English speakers use to specifically denote edible land snails.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/d/d7/Caracoles-del-restaurante-granero.jpg`,page:`https://commons.wikimedia.org/wiki/File:Caracoles-del-restaurante-granero.jpg`,artist:`Restaurante Granero`,license:`Public domain`}},"dish:Falafel":{wiki:{title:`Falafel`,url:`https://en.wikipedia.org/wiki/Falafel`,extract:`Falafel is a deep-fried ball or patty-shaped fritter of Egyptian origin that features in Middle Eastern cuisine, particularly Levantine cuisines. It is made from ground fava beans, chickpeas, or both, and mixed with herbs and spices before frying.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/Falafels_2.jpg/960px-Falafels_2.jpg`,page:`https://commons.wikimedia.org/wiki/File:Falafels_2.jpg`,artist:`Popo le Chien`,license:`CC BY-SA 3.0`}},"dish:Shawarma":{wiki:{title:`Shawarma`,url:`https://en.wikipedia.org/wiki/Shawarma`,extract:`Shawarma is a popular street food in the Middle East that originated in the Levant during the Ottoman Empire. It consists of meat cut into thin slices, stacked in an inverted cone, and roasted on a slow-turning vertical spit. Traditionally made with lamb or mutton, it may also be made with chicken, turkey meat, beef, falafel or veal.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/Shawarma_2.jpg/960px-Shawarma_2.jpg`,page:`https://commons.wikimedia.org/wiki/File:Shawarma_2.jpg`,artist:`Vis M`,license:`CC BY-SA 4.0`}},"dish:Profiterole":{wiki:{title:`Profiterole`,url:`https://en.wikipedia.org/wiki/Profiterole`,extract:`A profiterole, or chou à la crème, known as a cream puff in the US and Canada, is a filled French choux pastry ball with a typically sweet and moist filling of whipped cream, custard, pastry cream, or ice cream. They may be garnished with chocolate sauce, caramel, or a dusting of powdered sugar.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/Paris_2e_-_Rue_Vivienne_-_Restaurant_Le_Vaudeville_-_Profiteroles_au_chocolat.jpg/960px-Paris_2e_-_Rue_Vivienne_-_Restaurant_Le_Vaudeville_-_Profiteroles_au_chocolat.jpg`,page:`https://commons.wikimedia.org/wiki/File:Paris_2e_-_Rue_Vivienne_-_Restaurant_Le_Vaudeville_-_Profiteroles_au_chocolat.jpg`,artist:`Romainbehar`,license:`CC0`}},"dish:Crêpe":{wiki:{title:`Crêpe`,url:`https://en.wikipedia.org/wiki/Cr%C3%AApe`,extract:`A crêpe is a dish made from unleavened batter or dough that is cooked on a frying pan or a griddle. Crêpes are usually one of two varieties: sweet crêpes or savoury crêpes. They are often served with a wide variety of fillings such as cheese, fruit, vegetables, meats, and a variety of spreads. Crêpes can also be flambéed, such as in Crêpes Suzette.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/Crepes_dsc07085.jpg/960px-Crepes_dsc07085.jpg`,page:`https://commons.wikimedia.org/wiki/File:Crepes_dsc07085.jpg`,artist:`David Monniaux`,license:`CC BY-SA 3.0`}},"dish:French onion soup":{wiki:{title:`French onion soup`,url:`https://en.wikipedia.org/wiki/French_onion_soup`,extract:`French onion soup is a soup of onions which are sautéed and then cooked in meat stock or water, usually served gratinéed with croutons or a larger piece of bread covered with cheese floating on top. Onion soups have been known in France since medieval times, but the version now familiar dates from the mid-19th century.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Soupe_%C3%A0_l%27oignon.jpg/960px-Soupe_%C3%A0_l%27oignon.jpg`,page:`https://commons.wikimedia.org/wiki/File:Soupe_%C3%A0_l%27oignon.jpg`,artist:`Ludovic Péron`,license:`CC BY-SA 3.0`}},"dish:Croque monsieur":{wiki:{title:`Croque monsieur`,url:`https://en.wikipedia.org/wiki/Croque_monsieur`,extract:`A croque monsieur is a hot sandwich made with ham and cheese.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/Croque_monsieur.jpg/960px-Croque_monsieur.jpg`,page:`https://commons.wikimedia.org/wiki/File:Croque_monsieur.jpg`,artist:`Michael Brewer`,license:`CC BY-SA 2.5`}},"dish:Hot chocolate":{wiki:{title:`Hot chocolate`,url:`https://en.wikipedia.org/wiki/Hot_chocolate`,extract:`Hot chocolate, also known as hot cocoa or drinking chocolate, is a heated drink consisting of shaved or melted chocolate or cocoa powder, and heated milk or water. It usually contains a sweetener, such as sugar, and is often garnished with whipped cream or marshmallows. Hot chocolate made with melted chocolate is characterized by less sweetness and a thicker consistency.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9c/After_The_St._Patrick%27s_Parade_Late_Lunch_%40_Lemon%2C_Dawson_Street%2C_Dublin%2C_Rep._Of_Ireland_A_Fine_Tradition%21_%286992614913%29.jpg/960px-After_The_St._Patrick%27s_Parade_Late_Lunch_%40_Lemon%2C_Dawson_Street%2C_Dublin%2C_Rep._Of_Ireland_A_Fine_Tradition%21_%286992614913%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:After_The_St._Patrick%27s_Parade_Late_Lunch_@_Lemon,_Dawson_Street,_Dublin,_Rep._Of_Ireland_A_Fine_Tradition!_(6992614913).jpg`,artist:`|| UggBoy♥UggGirl || PHOTO || WORLD || TRAVEL ||`,license:`CC BY 2.0`}},"paris/Croissant":{wiki:{title:`Croissant`,url:`https://en.wikipedia.org/wiki/Croissant`,extract:`A croissant is a Viennoiserie in a crescent shape made from a laminated yeast dough that sits between a bread and a puff pastry.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/Croissant-Petr_Kratochvil.jpg/960px-Croissant-Petr_Kratochvil.jpg`,page:`https://commons.wikimedia.org/wiki/File:Croissant-Petr_Kratochvil.jpg`,artist:`Petr Kratochvil`,license:`CC0`}},"paris/French onion soup":{wiki:{title:`French onion soup`,url:`https://en.wikipedia.org/wiki/French_onion_soup`,extract:`French onion soup is a soup of onions which are sautéed and then cooked in meat stock or water, usually served gratinéed with croutons or a larger piece of bread covered with cheese floating on top. Onion soups have been known in France since medieval times, but the version now familiar dates from the mid-19th century.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Soupe_%C3%A0_l%27oignon.jpg/960px-Soupe_%C3%A0_l%27oignon.jpg`,page:`https://commons.wikimedia.org/wiki/File:Soupe_%C3%A0_l%27oignon.jpg`,artist:`Ludovic Péron`,license:`CC BY-SA 3.0`}},"paris/Steak frites":{wiki:{title:`Steak frites`,url:`https://en.wikipedia.org/wiki/Steak_frites`,extract:`Steak frites, meaning "steak [and] chipped potatoes" in French, is a dish consisting of beefsteak accompanied by fried chipped potatoes. It is commonly served in Belgian and French brasseries, and is considered by some to be the national dish of Belgium, which claims to be the country of origin.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9a/Reel_and_Brand_-_September_2021_-_Sarah_Stierch_05.jpg/960px-Reel_and_Brand_-_September_2021_-_Sarah_Stierch_05.jpg`,page:`https://commons.wikimedia.org/wiki/File:Reel_and_Brand_-_September_2021_-_Sarah_Stierch_05.jpg`,artist:`Missvain`,license:`CC BY 4.0`}},"paris/Croque monsieur":{wiki:{title:`Croque monsieur`,url:`https://en.wikipedia.org/wiki/Croque_monsieur`,extract:`A croque monsieur is a hot sandwich made with ham and cheese.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/Croque_monsieur.jpg/960px-Croque_monsieur.jpg`,page:`https://commons.wikimedia.org/wiki/File:Croque_monsieur.jpg`,artist:`Michael Brewer`,license:`CC BY-SA 2.5`}},"paris/Macarons":{wiki:{title:`Macaron`,url:`https://en.wikipedia.org/wiki/Macaron`,extract:`A macaron or French macaroon is a sweet meringue-based confection made with egg white, icing sugar, granulated sugar, almond meal, and often food colouring.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/VanillaMacaron.jpg/960px-VanillaMacaron.jpg`,page:`https://commons.wikimedia.org/wiki/File:VanillaMacaron.jpg`,artist:`Michelle Naherny`,license:`CC BY-SA 4.0`}},"paris/Crêpes":{wiki:{title:`Crêpe`,url:`https://en.wikipedia.org/wiki/Cr%C3%AApe`,extract:`A crêpe is a dish made from unleavened batter or dough that is cooked on a frying pan or a griddle. Crêpes are usually one of two varieties: sweet crêpes or savoury crêpes. They are often served with a wide variety of fillings such as cheese, fruit, vegetables, meats, and a variety of spreads. Crêpes can also be flambéed, such as in Crêpes Suzette.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/Crepes_dsc07085.jpg/960px-Crepes_dsc07085.jpg`,page:`https://commons.wikimedia.org/wiki/File:Crepes_dsc07085.jpg`,artist:`David Monniaux`,license:`CC BY-SA 3.0`}},"dish:Socca":{wiki:{title:`Socca`,url:`https://en.wikipedia.org/wiki/Socca`,extract:`Socca is a small-sided team sports variant of association football, best known in 6-a-side 40-minute format. It is also played in a 7-a-side format.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/0/04/Socca_EuroCup_2024_-_Moldova_-_Italy.jpg/960px-Socca_EuroCup_2024_-_Moldova_-_Italy.jpg`,page:`https://commons.wikimedia.org/wiki/File:Socca_EuroCup_2024_-_Moldova_-_Italy.jpg`,artist:`Melange`,license:`CC BY-SA 4.0`}},"dish:Pissaladière":{wiki:{title:`Pissaladière`,url:`https://en.wikipedia.org/wiki/Pissaladi%C3%A8re`,extract:`Pissaladière is a dish of flatbread with toppings from the region of Provence and the French city of Nice. It is often compared to pizza. The dough is usually a bread dough thicker than that of the classic pizza Margherita, and the traditional topping in Nice usually consists of caramelised onions, black olives and anchovies.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Pissaladi%C3%A8re.jpg/960px-Pissaladi%C3%A8re.jpg`,page:`https://commons.wikimedia.org/wiki/File:Pissaladi%C3%A8re.jpg`,artist:`Cdg83`,license:`CC BY-SA 4.0`}},"dish:Tourte de blettes":{wiki:{title:`Tourte de blettes`,url:`https://en.wikipedia.org/wiki/Tourte_de_blettes`,extract:`Tourte de blettes is a pie made with Swiss chard, which can be served as a main course or as a sweet dessert. It is a culinary specialty of the city of Nice.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/Tourte_de_blettes.jpg/960px-Tourte_de_blettes.jpg`,page:`https://commons.wikimedia.org/wiki/File:Tourte_de_blettes.jpg`,artist:`Assassas77`,license:`CC BY-SA 4.0`}},"dish:Pan bagnat":{wiki:{title:`Pan bagnat`,url:`https://en.wikipedia.org/wiki/Pan_bagnat`,extract:`The pan bagnat is a sandwich that is a specialty of Nice, France. The sandwich is composed of pain de campagne, a whole wheat bread, enclosing a salade niçoise, a salad composed mainly of raw vegetables, hard boiled eggs, anchovies and/or tuna, and olive oil, salt, and pepper. Sometimes vinegar is added, but never mayonnaise. It was historically prepared to use day-old bread.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2b/Pan-bagnat002.jpg/960px-Pan-bagnat002.jpg`,page:`https://commons.wikimedia.org/wiki/File:Pan-bagnat002.jpg`,artist:`Arnaud 25`,license:`CC BY-SA 4.0`}},"dish:Daube":{wiki:{title:`Daube`,url:`https://en.wikipedia.org/wiki/Daube`,extract:`Daube is a French slow-cooked stew, usually of beef, but other meat is sometimes used. The best-known is the bœuf en daube à la provençale, a Provençal stew made with cheaper cuts of beef braised in wine, with vegetables, garlic and herbs, and traditionally cooked in a daubière–a braising pot.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/67/Daube_de_boeuf.JPG/960px-Daube_de_boeuf.JPG`,page:`https://commons.wikimedia.org/wiki/File:Daube_de_boeuf.JPG`,artist:`Véronique PAGNIER`,license:`CC BY-SA 3.0`}},"dish:Candied fruit":{wiki:{title:`Candied fruit`,url:`https://en.wikipedia.org/wiki/Candied_fruit`,extract:`Candied fruit, also known as glacé fruit, is whole fruit, smaller pieces of fruit, or pieces of peel, placed in heated sugar syrup, which absorbs the moisture from within the fruit and eventually preserves it. Depending on the size and type of fruit, this process can take from several days to several months.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/Candied_Fruit_-_La_Boquer%C3%ADa.jpg/960px-Candied_Fruit_-_La_Boquer%C3%ADa.jpg`,page:`https://commons.wikimedia.org/wiki/File:Candied_Fruit_-_La_Boquer%C3%ADa.jpg`,artist:`Hopefully acceptable username`,license:`Public domain`}},"nice/Socca":{wiki:{title:`Socca`,url:`https://en.wikipedia.org/wiki/Socca`,extract:`Socca is a small-sided team sports variant of association football, best known in 6-a-side 40-minute format. It is also played in a 7-a-side format.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/0/04/Socca_EuroCup_2024_-_Moldova_-_Italy.jpg/960px-Socca_EuroCup_2024_-_Moldova_-_Italy.jpg`,page:`https://commons.wikimedia.org/wiki/File:Socca_EuroCup_2024_-_Moldova_-_Italy.jpg`,artist:`Melange`,license:`CC BY-SA 4.0`}},"nice/Salade niçoise":{wiki:{title:`Salade niçoise`,url:`https://en.wikipedia.org/wiki/Salade_ni%C3%A7oise`,extract:`Salade niçoise is a salad that originated in the French city of Nice. It is traditionally made of tomatoes, hard-boiled eggs, Niçoise olives and anchovies or tuna, dressed with olive oil or, in some historical versions, a vinaigrette. It has been popular worldwide since the early 20th century, and has been prepared and discussed by many chefs.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/8/88/Nizza-Salat_an_der_F_Mittelmeerk%C3%BCste.JPG/960px-Nizza-Salat_an_der_F_Mittelmeerk%C3%BCste.JPG`,page:`https://commons.wikimedia.org/wiki/File:Nizza-Salat_an_der_F_Mittelmeerk%C3%BCste.JPG`,artist:`Wusel007`,license:`CC BY-SA 3.0`}},"nice/Pan bagnat":{wiki:{title:`Pan bagnat`,url:`https://en.wikipedia.org/wiki/Pan_bagnat`,extract:`The pan bagnat is a sandwich that is a specialty of Nice, France. The sandwich is composed of pain de campagne, a whole wheat bread, enclosing a salade niçoise, a salad composed mainly of raw vegetables, hard boiled eggs, anchovies and/or tuna, and olive oil, salt, and pepper. Sometimes vinegar is added, but never mayonnaise. It was historically prepared to use day-old bread.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2b/Pan-bagnat002.jpg/960px-Pan-bagnat002.jpg`,page:`https://commons.wikimedia.org/wiki/File:Pan-bagnat002.jpg`,artist:`Arnaud 25`,license:`CC BY-SA 4.0`}},"nice/Pissaladière":{wiki:{title:`Pissaladière`,url:`https://en.wikipedia.org/wiki/Pissaladi%C3%A8re`,extract:`Pissaladière is a dish of flatbread with toppings from the region of Provence and the French city of Nice. It is often compared to pizza. The dough is usually a bread dough thicker than that of the classic pizza Margherita, and the traditional topping in Nice usually consists of caramelised onions, black olives and anchovies.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Pissaladi%C3%A8re.jpg/960px-Pissaladi%C3%A8re.jpg`,page:`https://commons.wikimedia.org/wiki/File:Pissaladi%C3%A8re.jpg`,artist:`Cdg83`,license:`CC BY-SA 4.0`}},"nice/Swiss chard pie":{wiki:{title:`Tourte de blettes`,url:`https://en.wikipedia.org/wiki/Tourte_de_blettes`,extract:`Tourte de blettes is a pie made with Swiss chard, which can be served as a main course or as a sweet dessert. It is a culinary specialty of the city of Nice.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/Tourte_de_blettes.jpg/960px-Tourte_de_blettes.jpg`,page:`https://commons.wikimedia.org/wiki/File:Tourte_de_blettes.jpg`,artist:`Assassas77`,license:`CC BY-SA 4.0`}},"dish:Gudeg":{wiki:{title:`Gudeg`,url:`https://en.wikipedia.org/wiki/Gudeg`,extract:`Gudeg is a traditional Javanese dish from Yogyakarta, Indonesia. It is made from young, unripe jackfruit stewed for several hours with palm sugar and coconut milk. It is variously spiced with garlic, shallot, candlenut, coriander seed, galangal, bay leaves, and teak leaves, the latter giving the dish a reddish-brown color. It is sometimes called "green jack fruit sweet stew".`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Nasi_Gudeg.jpg/960px-Nasi_Gudeg.jpg`,page:`https://commons.wikimedia.org/wiki/File:Nasi_Gudeg.jpg`,artist:`christian razukas from Honolulu, Hawaii`,license:`CC BY-SA 2.0`}},"dish:Sate klatak":{wiki:{title:`Sate klatak`,url:`https://en.wikipedia.org/wiki/Sate_klatak`,extract:`Sate klatak is a unique goat or mutton satay dish, originally from Pleret District, Bantul Regency in Yogyakarta. In Javanese, the act of roasting satay in an open fire is called "klathak".`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/Sate_klatak_20170818_Yogyakarta.jpg/960px-Sate_klatak_20170818_Yogyakarta.jpg`,page:`https://commons.wikimedia.org/wiki/File:Sate_klatak_20170818_Yogyakarta.jpg`,artist:`Naval Scene`,license:`CC BY-SA 4.0`}},"dish:Tongseng":{wiki:{title:`Tongseng`,url:`https://en.wikipedia.org/wiki/Tongseng`,extract:`Tongseng is an Indonesian goat meat, mutton or beef stew dish in curry-like soup, with vegetables and kecap manis. Tongseng is commonly found in the Indonesian region of Central Java; from Surakarta to Yogyakarta. However, it is believed that the dish originated from Klego district in Boyolali, Central Java.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/eb/Tongseng_Dish.jpg/960px-Tongseng_Dish.jpg`,page:`https://commons.wikimedia.org/wiki/File:Tongseng_Dish.jpg`,artist:`Gunawan Kartapranata`,license:`CC BY-SA 3.0`}},"dish:Soto ayam":{wiki:{title:`Soto ayam`,url:`https://en.wikipedia.org/wiki/Soto_ayam`,extract:`Soto ayam is a traditional Indonesian dish with ingredients such as chicken, lontong, noodles, and rice vermicelli. Soto ayam is also popular in Singapore, Malaysia and Suriname, where it is made with slightly different ingredients and known as saoto. Turmeric is added as one of its main ingredients which makes the yellow chicken broth.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Soto_ayam.JPG/960px-Soto_ayam.JPG`,page:`https://commons.wikimedia.org/wiki/File:Soto_ayam.JPG`,artist:`Sakurai Midori`,license:`CC BY-SA 3.0`}},"dish:Sayur lodeh":{wiki:{title:`Sayur lodeh`,url:`https://en.wikipedia.org/wiki/Sayur_lodeh`,extract:`Sayur lodeh is an Indonesian vegetable soup prepared from vegetables cooked in coconut milk, most often associated with Javanese cuisine.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/8/8f/Lodeh.jpg`,page:`https://commons.wikimedia.org/wiki/File:Lodeh.jpg`,artist:`iNews`,license:`CC BY-SA 4.0`}},"dish:Pisang goreng":{wiki:{title:`Banana fritter`,url:`https://en.wikipedia.org/wiki/Banana_fritter`,extract:`A banana fritter is a fritter made by deep frying battered banana or plantain in hot cooking oil. It is a common dish across Southeast Asia, Madagascar, and South India.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9f/Banana_Fritters_and_tea.jpg/960px-Banana_Fritters_and_tea.jpg`,page:`https://commons.wikimedia.org/wiki/File:Banana_Fritters_and_tea.jpg`,artist:`Iloveporotta`,license:`CC BY-SA 4.0`}},"dish:Nasi kucing":{wiki:{title:`Nasi kucing`,url:`https://en.wikipedia.org/wiki/Nasi_kucing`,extract:`Nasi kucing is an Indonesian rice dish that originated in Central Java, primarily in the Yogyakarta, Semarang, and Surakarta areas but has since spread throughout the country. It consists of a small portion of rice with toppings, usually sambal, dried fish, and tempeh, wrapped in banana leaves.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/e/eb/NasiKucing.jpg`,page:`https://commons.wikimedia.org/wiki/File:NasiKucing.jpg`,artist:`remas.nu`,license:`CC BY-SA 4.0`}},"yogyakarta/Gudeg":{wiki:{title:`Gudeg`,url:`https://en.wikipedia.org/wiki/Gudeg`,extract:`Gudeg is a traditional Javanese dish from Yogyakarta, Indonesia. It is made from young, unripe jackfruit stewed for several hours with palm sugar and coconut milk. It is variously spiced with garlic, shallot, candlenut, coriander seed, galangal, bay leaves, and teak leaves, the latter giving the dish a reddish-brown color. It is sometimes called "green jack fruit sweet stew".`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Nasi_Gudeg.jpg/960px-Nasi_Gudeg.jpg`,page:`https://commons.wikimedia.org/wiki/File:Nasi_Gudeg.jpg`,artist:`christian razukas from Honolulu, Hawaii`,license:`CC BY-SA 2.0`}},"yogyakarta/Goat Satay on Bicycle Spokes":{wiki:{title:`Sate klatak`,url:`https://en.wikipedia.org/wiki/Sate_klatak`,extract:`Sate klatak is a unique goat or mutton satay dish, originally from Pleret District, Bantul Regency in Yogyakarta. In Javanese, the act of roasting satay in an open fire is called "klathak".`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/Sate_klatak_20170818_Yogyakarta.jpg/960px-Sate_klatak_20170818_Yogyakarta.jpg`,page:`https://commons.wikimedia.org/wiki/File:Sate_klatak_20170818_Yogyakarta.jpg`,artist:`Naval Scene`,license:`CC BY-SA 4.0`}},"yogyakarta/Javanese Charcoal Noodles":{wiki:{title:`Bakmi jawa`,url:`https://en.wikipedia.org/wiki/Bakmi_jawa`,extract:`Bakmi jawa, also called mi jawa or mie jawa in Indonesia, or mee Jawa in Malaysia, is a traditional Javanese-style noodle, commonly found in Indonesia and Malaysia. The dish is made of yellow noodles, chicken, vegetables, egg and spices. The recipe however, is slightly different between mie jawa in Indonesia and mee Jawa in Malaysia.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f8/Mie_Jawa.jpg/960px-Mie_Jawa.jpg`,page:`https://commons.wikimedia.org/wiki/File:Mie_Jawa.jpg`,artist:`Hastosuprayogo`,license:`CC BY-SA 4.0`}},"yogyakarta/Cat Rice":{wiki:{title:`Nasi kucing`,url:`https://en.wikipedia.org/wiki/Nasi_kucing`,extract:`Nasi kucing is an Indonesian rice dish that originated in Central Java, primarily in the Yogyakarta, Semarang, and Surakarta areas but has since spread throughout the country. It consists of a small portion of rice with toppings, usually sambal, dried fish, and tempeh, wrapped in banana leaves.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/e/eb/NasiKucing.jpg`,page:`https://commons.wikimedia.org/wiki/File:NasiKucing.jpg`,artist:`remas.nu`,license:`CC BY-SA 4.0`}},"yogyakarta/Bakpia":{wiki:{title:`Bakpia pathok`,url:`https://en.wikipedia.org/wiki/Bakpia_pathok`,extract:`Bakpia pathok is a small, round-shaped Chinese-influenced Indonesian sweet roll (bakpia), usually stuffed with mung beans, but have recently come in other fillings as well, such as chocolate, durian and cheese. This sweet roll is found in Javanese and Chinese Indonesian cuisine. They are one of Yogyakarta's specialties and are named after the Pathok suburb where the pastries originated.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/3/3c/Bakpia_pathok.jpg`,page:`https://commons.wikimedia.org/wiki/File:Bakpia_pathok.jpg`,artist:`Serenity`,license:`CC BY-SA 3.0`}},"yogyakarta/Charcoal Coffee":{wiki:{title:`Kopi joss`,url:`https://en.wikipedia.org/wiki/Kopi_joss`,extract:`Kopi joss or kopi jos is a traditional coffee beverage from Yogyakarta served with hot charcoal. The hot charcoal is submerged in brewed black coffee and sugar before serving. This coffee is typically sold at angkringans, a type of street food stall or cart, in Yogyakarta. A cup of kopi joss is usually priced around 5 thousand rupiah.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/8/81/Kopi_Joss.jpg`,page:`https://commons.wikimedia.org/wiki/File:Kopi_Joss.jpg`,artist:`Ivan Lanin from Jakarta, Indonesia`,license:`CC BY-SA 2.0`}},"dish:Betutu":{wiki:{title:`Betutu`,url:`https://en.wikipedia.org/wiki/Betutu`,extract:`Betutu is a Balinese dish of steamed or roasted chicken or duck in rich bumbu betutu. This highly seasoned and spiced dish is a popular dish in Bali and Lombok, Indonesia. An even spicier version is available using extra-spicy sauce made from uncooked (raw) onion slices mixed with red chili peppers and coconut oil.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/2/21/Bebek_Betutu.jpg`,page:`https://commons.wikimedia.org/wiki/File:Bebek_Betutu.jpg`,artist:`The man from Gianyar`,license:`CC BY-SA 4.0`}},"dish:Nasi campur":{wiki:{title:`Nasi campur`,url:`https://en.wikipedia.org/wiki/Nasi_campur`,extract:`Nasi campur, also known as nasi rames or sega campur in Java, refers to an Indonesian and Malay dish of a scoop of nasi putih accompanied by small portions of several other dishes, including meats, vegetables, peanuts, eggs, and fried-shrimp krupuk.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/2/25/Plate_of_nasi_campur_%28Mandarin_Oriental_Hotel_Mahapahit%2C_Surabaya%2C_Indonesia%29.png`,page:`https://commons.wikimedia.org/wiki/File:Plate_of_nasi_campur_(Mandarin_Oriental_Hotel_Mahapahit,_Surabaya,_Indonesia).png`,artist:`Unknown author`,license:`Public domain`}},"dish:Sate lilit":{wiki:{title:`Sate lilit`,url:`https://en.wikipedia.org/wiki/Sate_lilit`,extract:`Sate lilit is a satay variant in Indonesia, originating from Balinese cuisine. This satay is made from minced pork, fish, chicken, beef, or even turtle meat, which is then mixed with grated coconut, thick coconut milk, lemon juice, shallots, and pepper. The spiced minced meat is wound around bamboo, sugar cane or lemongrass sticks, it is then grilled on charcoal.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/6/6d/Sate_lilit.jpg`,page:`https://commons.wikimedia.org/wiki/File:Sate_lilit.jpg`,artist:`lifestyle.okezone.com`,license:`CC BY-SA 4.0`}},"dish:Bubur ketan hitam":{wiki:{title:`Bubur ketan hitam`,url:`https://en.wikipedia.org/wiki/Bubur_ketan_hitam`,extract:`Bubur ketan hitam, bubur pulut hitam or bubur injun is an Indonesian sweet dessert made from black glutinous rice porridge with coconut milk and palm sugar or cane sugar. The black glutinous rice are boiled until soft, and sugar and coconut milk are added. It is often described as "black glutinous rice pudding" and is very similar to black rice tong sui made from black rice.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Bubuh_Injin_Bali_1.jpg/960px-Bubuh_Injin_Bali_1.jpg`,page:`https://commons.wikimedia.org/wiki/File:Bubuh_Injin_Bali_1.jpg`,artist:`Gunawan Kartapranata`,license:`CC BY-SA 4.0`}},"bali/Suckling Pig":{wiki:{title:`Babi panggang`,url:`https://en.wikipedia.org/wiki/Babi_panggang`,extract:`Babi panggang refers to various Indonesian grilled pork dishes, 'babi' meaning pig or pork, and 'panggang' meaning grilled or roasted in the Indonesian language.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/Panggang_1.JPG/960px-Panggang_1.JPG`,page:`https://commons.wikimedia.org/wiki/File:Panggang_1.JPG`,artist:`Gunawan Kartapranata`,license:`CC BY-SA 3.0`}},"bali/Slow-Cooked Spiced Duck":{wiki:{title:`Betutu`,url:`https://en.wikipedia.org/wiki/Betutu`,extract:`Betutu is a Balinese dish of steamed or roasted chicken or duck in rich bumbu betutu. This highly seasoned and spiced dish is a popular dish in Bali and Lombok, Indonesia. An even spicier version is available using extra-spicy sauce made from uncooked (raw) onion slices mixed with red chili peppers and coconut oil.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/2/21/Bebek_Betutu.jpg`,page:`https://commons.wikimedia.org/wiki/File:Bebek_Betutu.jpg`,artist:`The man from Gianyar`,license:`CC BY-SA 4.0`}},"bali/Minced Satay":{wiki:{title:`Sate lilit`,url:`https://en.wikipedia.org/wiki/Sate_lilit`,extract:`Sate lilit is a satay variant in Indonesia, originating from Balinese cuisine. This satay is made from minced pork, fish, chicken, beef, or even turtle meat, which is then mixed with grated coconut, thick coconut milk, lemon juice, shallots, and pepper. The spiced minced meat is wound around bamboo, sugar cane or lemongrass sticks, it is then grilled on charcoal.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/6/6d/Sate_lilit.jpg`,page:`https://commons.wikimedia.org/wiki/File:Sate_lilit.jpg`,artist:`lifestyle.okezone.com`,license:`CC BY-SA 4.0`}},"bali/Lawar":{wiki:{title:`Lawar`,url:`https://en.wikipedia.org/wiki/Lawar`,extract:`Lawar is a town and a nagar panchayat in Meerut district in the Indian state of Uttar Pradesh.`}},"bali/Nasi Campur Bali":{wiki:{title:`Nasi campur`,url:`https://en.wikipedia.org/wiki/Nasi_campur`,extract:`Nasi campur, also known as nasi rames or sega campur in Java, refers to an Indonesian and Malay dish of a scoop of nasi putih accompanied by small portions of several other dishes, including meats, vegetables, peanuts, eggs, and fried-shrimp krupuk.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/2/25/Plate_of_nasi_campur_%28Mandarin_Oriental_Hotel_Mahapahit%2C_Surabaya%2C_Indonesia%29.png`,page:`https://commons.wikimedia.org/wiki/File:Plate_of_nasi_campur_(Mandarin_Oriental_Hotel_Mahapahit,_Surabaya,_Indonesia).png`,artist:`Unknown author`,license:`Public domain`}},"bali/Black Rice Pudding":{wiki:{title:`Bubur ketan hitam`,url:`https://en.wikipedia.org/wiki/Bubur_ketan_hitam`,extract:`Bubur ketan hitam, bubur pulut hitam or bubur injun is an Indonesian sweet dessert made from black glutinous rice porridge with coconut milk and palm sugar or cane sugar. The black glutinous rice are boiled until soft, and sugar and coconut milk are added. It is often described as "black glutinous rice pudding" and is very similar to black rice tong sui made from black rice.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Bubuh_Injin_Bali_1.jpg/960px-Bubuh_Injin_Bali_1.jpg`,page:`https://commons.wikimedia.org/wiki/File:Bubuh_Injin_Bali_1.jpg`,artist:`Gunawan Kartapranata`,license:`CC BY-SA 4.0`}},"dish:Gado-gado":{wiki:{title:`Gado-gado`,url:`https://en.wikipedia.org/wiki/Gado-gado`,extract:`Gado-gado is an Indonesian salad of raw, slightly boiled, blanched or steamed vegetables and hard-boiled eggs, boiled potato, fried tofu and tempeh, and sliced lontong, served with a peanut sauce dressing.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/26/Gado_gado_jakarta.jpg/960px-Gado_gado_jakarta.jpg`,page:`https://commons.wikimedia.org/wiki/File:Gado_gado_jakarta.jpg`,artist:`Piknikdong`,license:`CC BY-SA 4.0`}},"dish:Lontong Cap Go Meh":{wiki:{title:`Lontong cap go meh`,url:`https://en.wikipedia.org/wiki/Lontong_cap_go_meh`,extract:`Lontong cap go meh is a Chinese Indonesian take on traditional Indonesian dishes, more precisely Javanese cuisine. It is lontong served with richly-flavoured dishes which include opor ayam chicken in coconut milk, sayur lodeh vegetable soup, hot and spicy liver, hard-boiled pindang egg, koya powder made of soy and dried shrimp or beef floss, pickles, chili paste and prawn cracker.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/Lontong_Cap_Go_Meh_2.JPG/960px-Lontong_Cap_Go_Meh_2.JPG`,page:`https://commons.wikimedia.org/wiki/File:Lontong_Cap_Go_Meh_2.JPG`,artist:`Gunawan Kartapranata`,license:`CC BY-SA 3.0`}},"dish:Cendol":{wiki:{title:`Cendol`,url:`https://en.wikipedia.org/wiki/Cendol`,extract:`Cendol, also known as lot chong, mont let saung, nom lut, lod song and bánh lọt, is a traditional Southeast Asian dessert characterised by soft, green, worm-like jelly strands made from rice flour or mung bean starch, coconut milk and palm sugar syrup, typically served over shaved ice. The jelly is flavoured with pandan and combined with a creamy coconut milk base and the caramel-like sweetness of palm sugar.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Kampung_Paya_Jaras_Tengah%2C_Selangor_20250112_111330.jpg/960px-Kampung_Paya_Jaras_Tengah%2C_Selangor_20250112_111330.jpg`,page:`https://commons.wikimedia.org/wiki/File:Kampung_Paya_Jaras_Tengah,_Selangor_20250112_111330.jpg`,artist:`Wiki Farazi`,license:`CC0`}},"dish:Ketoprak":{wiki:{title:`Ketoprak`,url:`https://en.wikipedia.org/wiki/Ketoprak`,extract:`Ketoprak is a theatrical genre of Java featuring actors who may also sing to the accompaniment of the gamelan. It draws its stories from Javanese history and romances and in this differs from wayang wong, which shares with wayang kulit a repertoire drawn from the Hindu epics Mahabharata and Ramayana, as well as from ludruk which uses contemporary settings and the three-walled srimulat, which specializes in vampire…`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1c/Kethoprak_Tobong_Kelana_Bhakti_Budaya_1.jpg/960px-Kethoprak_Tobong_Kelana_Bhakti_Budaya_1.jpg`,page:`https://commons.wikimedia.org/wiki/File:Kethoprak_Tobong_Kelana_Bhakti_Budaya_1.jpg`,artist:`dian_vasthu00`,license:`CC BY-SA 2.0`}},"dish:Nasi goreng":{wiki:{title:`Nasi goreng`,url:`https://en.wikipedia.org/wiki/Nasi_goreng`,extract:`Nasi goreng, is a Southeast Asian rice dish typically prepared with pre-cooked rice stir-fried in a small amount of oil or margarine and seasoned with ingredients such as sweet soy sauce, shallots, garlic, ground shrimp paste, tamarind and chilli. It is commonly served with additional ingredients, including egg, chicken, prawns and vegetables.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c7/Nasi_Goreng_Kampung_%2811967588375%29.jpg/960px-Nasi_Goreng_Kampung_%2811967588375%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Nasi_Goreng_Kampung_(11967588375).jpg`,artist:`shankar s. from Dubai, united arab emirates`,license:`CC BY 2.0`}},"dish:Rijsttafel":{wiki:{title:`Rijsttafel`,url:`https://en.wikipedia.org/wiki/Rijsttafel`,extract:`Rijsttafel is an elaborate Indonesian meal adapted by the Dutch from the hidang presentation of nasi padang from the Padang region of West Sumatra. It consists of many side dishes in small portions, accompanied by rice prepared in several different ways. Popular side dishes include egg rolls, sambals, satay, fish, fruit, vegetables, pickles, and nuts.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b9/Rijsttafel_Den_Haag_Javastraat.jpg/960px-Rijsttafel_Den_Haag_Javastraat.jpg`,page:`https://commons.wikimedia.org/wiki/File:Rijsttafel_Den_Haag_Javastraat.jpg`,artist:`Takeaway`,license:`CC BY-SA 3.0`}},"dish:Martabak":{wiki:{title:`Murtabak`,url:`https://en.wikipedia.org/wiki/Murtabak`,extract:`Murtabak, or mutabbaq, is a stuffed pancake or pan-fried bread commonly found in the Arabian Peninsula, parts of the Indian subcontinent, and Southeast Asia, notably in Saudi Arabia, Yemen, parts of South India, Indonesia, Malaysia, Singapore, Brunei, and Southern Thailand. Depending on the location, the name and ingredients can vary significantly. The name mutabbaq means "folded" in Arabic.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/63/Murtabak.jpg/960px-Murtabak.jpg`,page:`https://commons.wikimedia.org/wiki/File:Murtabak.jpg`,artist:`Mojackjutaily`,license:`CC BY-SA 4.0`}},"jakarta/Betawi Beef Soup":{wiki:{title:`Soto (food)`,url:`https://en.wikipedia.org/wiki/Soto_(food)`,extract:`Soto is a traditional Indonesian soup mainly composed of broth, meat, and vegetables. Many traditional soups are called soto, whereas foreign- and Western-influenced soups are called sop.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/Soto_Ayam_Savoy_Homann_Hotel.JPG/960px-Soto_Ayam_Savoy_Homann_Hotel.JPG`,page:`https://commons.wikimedia.org/wiki/File:Soto_Ayam_Savoy_Homann_Hotel.JPG`,artist:`Gunawan Kartapranata`,license:`CC BY-SA 3.0`}},"jakarta/Kerak Telor":{wiki:{title:`Kerak telor`,url:`https://en.wikipedia.org/wiki/Kerak_telor`,extract:`Kerak telor is a Betawi traditional spicy omelet dish from Indonesia. It is made from glutinous rice cooked with egg and served with serundeng, fried shallots, and dried shrimp as toppings. Kerak telor is considered a snack and not a main dish. The dish has become popular at the annual Jakarta Fair.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/b/bd/Kerak_telor_Betawi.jpg`,page:`https://commons.wikimedia.org/wiki/File:Kerak_telor_Betawi.jpg`,artist:`Warta Kota`,license:`CC BY-SA 4.0`}},"jakarta/Nasi Uduk":{wiki:{title:`Nasi uduk`,url:`https://en.wikipedia.org/wiki/Nasi_uduk`,extract:`Nasi uduk is an Indonesian-style steamed rice cooked in coconut milk dish, especially popular in Betawi and Javanese culinary traditions.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a6/Nasi_uduk_netherlands.jpg/960px-Nasi_uduk_netherlands.jpg`,page:`https://commons.wikimedia.org/wiki/File:Nasi_uduk_netherlands.jpg`,artist:`Takeaway`,license:`CC BY-SA 3.0`}},"jakarta/Gado-Gado":{wiki:{title:`Gado-gado`,url:`https://en.wikipedia.org/wiki/Gado-gado`,extract:`Gado-gado is an Indonesian salad of raw, slightly boiled, blanched or steamed vegetables and hard-boiled eggs, boiled potato, fried tofu and tempeh, and sliced lontong, served with a peanut sauce dressing.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/26/Gado_gado_jakarta.jpg/960px-Gado_gado_jakarta.jpg`,page:`https://commons.wikimedia.org/wiki/File:Gado_gado_jakarta.jpg`,artist:`Piknikdong`,license:`CC BY-SA 4.0`}},"jakarta/Ketoprak":{wiki:{title:`Ketoprak`,url:`https://en.wikipedia.org/wiki/Ketoprak`,extract:`Ketoprak is a theatrical genre of Java featuring actors who may also sing to the accompaniment of the gamelan. It draws its stories from Javanese history and romances and in this differs from wayang wong, which shares with wayang kulit a repertoire drawn from the Hindu epics Mahabharata and Ramayana, as well as from ludruk which uses contemporary settings and the three-walled srimulat, which specializes in vampire…`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1c/Kethoprak_Tobong_Kelana_Bhakti_Budaya_1.jpg/960px-Kethoprak_Tobong_Kelana_Bhakti_Budaya_1.jpg`,page:`https://commons.wikimedia.org/wiki/File:Kethoprak_Tobong_Kelana_Bhakti_Budaya_1.jpg`,artist:`dian_vasthu00`,license:`CC BY-SA 2.0`}},"jakarta/Martabak Manis":{wiki:{title:`Martabak manis`,url:`https://en.wikipedia.org/wiki/Martabak_manis`,extract:`Martabak manis also known as Apam balik, terang bulan, peanut pancake, or ban jian kueh, is a sweet dessert originating in Fujian cuisine which now consists of many varieties at specialist roadside stalls or restaurants throughout Brunei, Indonesia, Malaysia and Singapore.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Giant_Apam_Balik.jpg/960px-Giant_Apam_Balik.jpg`,page:`https://commons.wikimedia.org/wiki/File:Giant_Apam_Balik.jpg`,artist:`Yun Huang Yong`,license:`CC BY 2.0`}},"dish:Panzerotti":{wiki:{title:`Panzerotti`,url:`https://en.wikipedia.org/wiki/Panzerotti`,extract:`Panzerotti, also known as panzarotti, are Italian savory bread products, originating in the Apulia region, which resemble small calzones, both in shape and in the dough used for their preparation. The term panzerotti applies exclusively to a fried product, though oven-baked calzones are similar and the two are often mistaken for each other.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Panzerotti_chez_PanzerotTiamo_%28Lyon%29_-_2.jpg/960px-Panzerotti_chez_PanzerotTiamo_%28Lyon%29_-_2.jpg`,page:`https://commons.wikimedia.org/wiki/File:Panzerotti_chez_PanzerotTiamo_(Lyon)_-_2.jpg`,artist:`Benoît Prieur`,license:`CC0`}},"dish:Focaccia":{wiki:{title:`Focaccia`,url:`https://en.wikipedia.org/wiki/Focaccia`,extract:`Focaccia is a flat leavened oven-baked Italian bread. It is similar to a flatbread called pizza bianca in Roman cuisine.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/Focaccia_with_Crumb.jpg/960px-Focaccia_with_Crumb.jpg`,page:`https://commons.wikimedia.org/wiki/File:Focaccia_with_Crumb.jpg`,artist:`Fred Benenson`,license:`CC BY-SA 4.0`}},"dish:Pizza al taglio":{wiki:{title:`Pizza al taglio`,url:`https://en.wikipedia.org/wiki/Pizza_al_taglio`,extract:`Pizza al taglio or pizza al trancio is a variety of pizza baked in large rectangular trays, and generally sold in rectangular or square slices by weight, with prices marked per kilogram or per 100 grams. This type of pizza was developed in Rome, Italy, and is common throughout Italy. Many variations and styles of pizza al taglio exist, and the dish is available in other areas of the world in addition to Italy.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/4/43/Pizza_al_taglio.jpg`,page:`https://commons.wikimedia.org/wiki/File:Pizza_al_taglio.jpg`,artist:`Shoebill2`,license:`Public domain`}},"dish:Panettone":{wiki:{title:`Panettone`,url:`https://en.wikipedia.org/wiki/Panettone`,extract:`Panettone is an Italian sweet bread and fruitcake that is associated with the city of Milan, Lombardy. It is usually prepared for Christmas and New Year in Western, Southern, and Southeastern Europe, as well as in South America, Eritrea, Australia, and North America. Panettone is tall, with the appearance and texture of bread.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e6/Panettone_-_Nicolettone_2017_-_IMG_7085_%2831752542285%29.jpg/960px-Panettone_-_Nicolettone_2017_-_IMG_7085_%2831752542285%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Panettone_-_Nicolettone_2017_-_IMG_7085_(31752542285).jpg`,artist:`N i c o l a from Fiumicino (Rome), Italy`,license:`CC BY 2.0`}},"dish:Ossobuco":{wiki:{title:`Ossobuco`,url:`https://en.wikipedia.org/wiki/Ossobuco`,extract:`Ossobuco or osso buco, also known as ossobuco alla milanese, is a specialty of Lombard cuisine of cross-cut veal shanks braised with vegetables, white wine, and broth. It is often garnished with gremolada and traditionally served with either risotto alla milanese or polenta, depending on the regional variation. The marrow from the hole in the bone is a prized delicacy and the defining feature of the dish.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/e/e1/Ossobuco.jpg`,page:`https://commons.wikimedia.org/wiki/File:Ossobuco.jpg`,artist:`Mogens Engelund`,license:`CC BY-SA 3.0`}},"dish:Veal Milanese":{wiki:{title:`Veal Milanese`,url:`https://en.wikipedia.org/wiki/Veal_Milanese`,extract:`Veal Milanese is a popular variety of cotoletta from the city of Milan, Italy. It is traditionally prepared with a veal rib chop or sirloin bone-in and made into a breaded cutlet, fried in butter.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/a/a7/Cotoletta_e_patate_al_forno.jpg`,page:`https://commons.wikimedia.org/wiki/File:Cotoletta_e_patate_al_forno.jpg`,artist:`Paolo Piscolla`,license:`CC BY-SA 2.0`}},"dish:Risotto alla milanese":{wiki:{title:`Risotto`,url:`https://en.wikipedia.org/wiki/Risotto`,extract:`Risotto is an Italian rice dish cooked with broth until it reaches a creamy consistency. The broth can be derived from meat, fish or vegetables. Many types of risotto contain butter, onion, white wine, and Parmesan cheese. It is one of the most common ways of cooking rice in Italy. Saffron was originally used for flavour and its signature yellow colour.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a5/Risotto_with_speck_and_goat_cheese_%286101067436%29.jpg/960px-Risotto_with_speck_and_goat_cheese_%286101067436%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Risotto_with_speck_and_goat_cheese_(6101067436).jpg`,artist:`Luca Nebuloni from Milan, Italy`,license:`CC BY 2.0`}},"dish:Cassoeula":{wiki:{title:`Cassoeula`,url:`https://en.wikipedia.org/wiki/Cassoeula`,extract:`Cassoeula or cazzoeula, sometimes Italianized as cassola, cazzuola or cazzola, or bottaggio, is a typical winter dish popular in western Lombardy, Italy, chiefly made from pork and Savoy cabbage. The dish has a strong, decisive flavour, and was a favourite of conductor Arturo Toscanini.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/8/85/Cassoeula.jpg/960px-Cassoeula.jpg`,page:`https://commons.wikimedia.org/wiki/File:Cassoeula.jpg`,artist:`Remulazz`,license:`CC BY-SA 4.0`}},"milan/Risotto alla Milanese":{wiki:{title:`Risotto`,url:`https://en.wikipedia.org/wiki/Risotto`,extract:`Risotto is an Italian rice dish cooked with broth until it reaches a creamy consistency. The broth can be derived from meat, fish or vegetables. Many types of risotto contain butter, onion, white wine, and Parmesan cheese. It is one of the most common ways of cooking rice in Italy. Saffron was originally used for flavour and its signature yellow colour.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a5/Risotto_with_speck_and_goat_cheese_%286101067436%29.jpg/960px-Risotto_with_speck_and_goat_cheese_%286101067436%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Risotto_with_speck_and_goat_cheese_(6101067436).jpg`,artist:`Luca Nebuloni from Milan, Italy`,license:`CC BY 2.0`}},"milan/Milanese Veal Cutlet":{wiki:{title:`Veal Milanese`,url:`https://en.wikipedia.org/wiki/Veal_Milanese`,extract:`Veal Milanese is a popular variety of cotoletta from the city of Milan, Italy. It is traditionally prepared with a veal rib chop or sirloin bone-in and made into a breaded cutlet, fried in butter.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/a/a7/Cotoletta_e_patate_al_forno.jpg`,page:`https://commons.wikimedia.org/wiki/File:Cotoletta_e_patate_al_forno.jpg`,artist:`Paolo Piscolla`,license:`CC BY-SA 2.0`}},"milan/Ossobuco":{wiki:{title:`Ossobuco`,url:`https://en.wikipedia.org/wiki/Ossobuco`,extract:`Ossobuco or osso buco, also known as ossobuco alla milanese, is a specialty of Lombard cuisine of cross-cut veal shanks braised with vegetables, white wine, and broth. It is often garnished with gremolada and traditionally served with either risotto alla milanese or polenta, depending on the regional variation. The marrow from the hole in the bone is a prized delicacy and the defining feature of the dish.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/e/e1/Ossobuco.jpg`,page:`https://commons.wikimedia.org/wiki/File:Ossobuco.jpg`,artist:`Mogens Engelund`,license:`CC BY-SA 3.0`}},"milan/Panzerotti":{wiki:{title:`Panzerotti`,url:`https://en.wikipedia.org/wiki/Panzerotti`,extract:`Panzerotti, also known as panzarotti, are Italian savory bread products, originating in the Apulia region, which resemble small calzones, both in shape and in the dough used for their preparation. The term panzerotti applies exclusively to a fried product, though oven-baked calzones are similar and the two are often mistaken for each other.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Panzerotti_chez_PanzerotTiamo_%28Lyon%29_-_2.jpg/960px-Panzerotti_chez_PanzerotTiamo_%28Lyon%29_-_2.jpg`,page:`https://commons.wikimedia.org/wiki/File:Panzerotti_chez_PanzerotTiamo_(Lyon)_-_2.jpg`,artist:`Benoît Prieur`,license:`CC0`}},"milan/Panettone":{wiki:{title:`Panettone`,url:`https://en.wikipedia.org/wiki/Panettone`,extract:`Panettone is an Italian sweet bread and fruitcake that is associated with the city of Milan, Lombardy. It is usually prepared for Christmas and New Year in Western, Southern, and Southeastern Europe, as well as in South America, Eritrea, Australia, and North America. Panettone is tall, with the appearance and texture of bread.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e6/Panettone_-_Nicolettone_2017_-_IMG_7085_%2831752542285%29.jpg/960px-Panettone_-_Nicolettone_2017_-_IMG_7085_%2831752542285%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Panettone_-_Nicolettone_2017_-_IMG_7085_(31752542285).jpg`,artist:`N i c o l a from Fiumicino (Rome), Italy`,license:`CC BY 2.0`}},"milan/Cassoeula":{wiki:{title:`Cassoeula`,url:`https://en.wikipedia.org/wiki/Cassoeula`,extract:`Cassoeula or cazzoeula, sometimes Italianized as cassola, cazzuola or cazzola, or bottaggio, is a typical winter dish popular in western Lombardy, Italy, chiefly made from pork and Savoy cabbage. The dish has a strong, decisive flavour, and was a favourite of conductor Arturo Toscanini.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/8/85/Cassoeula.jpg/960px-Cassoeula.jpg`,page:`https://commons.wikimedia.org/wiki/File:Cassoeula.jpg`,artist:`Remulazz`,license:`CC BY-SA 4.0`}},"dish:Carbonara":{wiki:{title:`Carbonara`,url:`https://en.wikipedia.org/wiki/Carbonara`,extract:`Carbonara is a pasta dish made with cured pork, hard cheese, eggs, salt, and black pepper. It is typical of the Lazio region of Italy. The dish took its modern form and name in the middle of the 20th century.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Espaguetis_carbonara.jpg/960px-Espaguetis_carbonara.jpg`,page:`https://commons.wikimedia.org/wiki/File:Espaguetis_carbonara.jpg`,artist:`Javier Somoza`,license:`CC BY-SA 4.0`}},"dish:Burrata":{wiki:{title:`Burrata`,url:`https://en.wikipedia.org/wiki/Burrata`,extract:`Burrata is an Italian cow's milk cheese made from mozzarella and cream.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/Burrata2.jpg/960px-Burrata2.jpg`,page:`https://commons.wikimedia.org/wiki/File:Burrata2.jpg`,artist:`Popo le Chien`,license:`CC0`}},"dish:Cacio e pepe":{wiki:{title:`Cacio e pepe`,url:`https://en.wikipedia.org/wiki/Cacio_e_pepe`,extract:`Cacio e pepe is a pasta dish typical of Lazio, Italy. It contains grated pecorino romano and black pepper with tonnarelli or spaghetti. Achieving a smooth and creamy texture during preparation requires special attention, as the cheese is prone to becoming lumpy.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/Cacio_e_pepe.jpg/960px-Cacio_e_pepe.jpg`,page:`https://commons.wikimedia.org/wiki/File:Cacio_e_pepe.jpg`,artist:`Popo le Chien`,license:`CC BY-SA 3.0`}},"dish:Pizza bianca":{wiki:{title:`Pizza bianca`,url:`https://en.wikipedia.org/wiki/Pizza_bianca`,extract:`Pizza bianca is a type of flatbread originating in Rome, Italy. It is a plain yeast flatbread which more closely resembles focaccia than typical cheese-topped pizza. It can be split and filled with ingredients such as prosciutto, Parmesan cheese or rocket and is typically served hot. In 2019 the government of Italy declared Pizza Bianca Romana alla Pala del Fornaio a traditional agri-food product of Italy.`}},"dish:Maritozzo":{wiki:{title:`Maritozzo`,url:`https://en.wikipedia.org/wiki/Maritozzo`,extract:`Maritozzo is a traditional Italian cream bun consisting of bread filled with a generous amount of whipped cream. Originally, "maritozzo" referred only to the bread part, and the version filled with whipped cream was called maritozzo con la panna, meaning "maritozzo with whipped cream".`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/Maritozzo_presso_Caff%C3%A8_delle_colline%2C_Reggio_Emilia.jpg/960px-Maritozzo_presso_Caff%C3%A8_delle_colline%2C_Reggio_Emilia.jpg`,page:`https://commons.wikimedia.org/wiki/File:Maritozzo_presso_Caff%C3%A8_delle_colline,_Reggio_Emilia.jpg`,artist:`Ensahequ`,license:`CC BY-SA 4.0`}},"dish:Carciofi alla giudia":{wiki:{title:`Carciofi alla giudia`,url:`https://en.wikipedia.org/wiki/Carciofi_alla_giudia`,extract:`Carciofi alla giudìa is among the best-known dishes of Roman Jewish cuisine. It is essentially a deep-fried artichoke, and the recipe originated in the Jewish community of Rome, giudìo being the exonym for the Jewish people in the Romanesco language.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7c/Carciofo_alla_Giudia.jpg/960px-Carciofo_alla_Giudia.jpg`,page:`https://commons.wikimedia.org/wiki/File:Carciofo_alla_Giudia.jpg`,artist:`Simone.lippi`,license:`CC BY-SA 3.0`}},"dish:Supplì":{wiki:{title:`Supplì`,url:`https://en.wikipedia.org/wiki/Suppl%C3%AC`,extract:`Supplì are Italian snacks consisting of a ball of rice with tomato sauce, typical of Roman cuisine. Some believe that they derive from the French croquettes and were introduced to Rome by the French troops of Napoleon at the beginning of the 19th century.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/Suppl%C3%AC.jpg/960px-Suppl%C3%AC.jpg`,page:`https://commons.wikimedia.org/wiki/File:Suppl%C3%AC.jpg`,artist:`FrederikBianko`,license:`CC BY-SA 3.0`}},"dish:Saltimbocca":{wiki:{title:`Saltimbocca`,url:`https://en.wikipedia.org/wiki/Saltimbocca`,extract:`Saltimbocca is an Italian dish. It consists of veal that has been wrapped (lined) with prosciutto and sage and then marinated in wine, oil or salt water, depending on the region or one's own taste.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Saltimbocca_01.jpg/960px-Saltimbocca_01.jpg`,page:`https://commons.wikimedia.org/wiki/File:Saltimbocca_01.jpg`,artist:`Arnaud 25`,license:`CC BY-SA 4.0`}},"dish:Cappuccino":{wiki:{title:`Cappuccino`,url:`https://en.wikipedia.org/wiki/Cappuccino`,extract:`Cappuccino is an espresso-based coffee drink traditionally prepared with steamed milk, including a layer of milk foam.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/Cappuccino_in_original.jpg/960px-Cappuccino_in_original.jpg`,page:`https://commons.wikimedia.org/wiki/File:Cappuccino_in_original.jpg`,artist:`Vee Satayamas`,license:`CC BY 2.0`}},"rome/Cacio e Pepe":{wiki:{title:`Cacio e pepe`,url:`https://en.wikipedia.org/wiki/Cacio_e_pepe`,extract:`Cacio e pepe is a pasta dish typical of Lazio, Italy. It contains grated pecorino romano and black pepper with tonnarelli or spaghetti. Achieving a smooth and creamy texture during preparation requires special attention, as the cheese is prone to becoming lumpy.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/Cacio_e_pepe.jpg/960px-Cacio_e_pepe.jpg`,page:`https://commons.wikimedia.org/wiki/File:Cacio_e_pepe.jpg`,artist:`Popo le Chien`,license:`CC BY-SA 3.0`}},"rome/Spaghetti alla Carbonara":{wiki:{title:`Carbonara`,url:`https://en.wikipedia.org/wiki/Carbonara`,extract:`Carbonara is a pasta dish made with cured pork, hard cheese, eggs, salt, and black pepper. It is typical of the Lazio region of Italy. The dish took its modern form and name in the middle of the 20th century.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Espaguetis_carbonara.jpg/960px-Espaguetis_carbonara.jpg`,page:`https://commons.wikimedia.org/wiki/File:Espaguetis_carbonara.jpg`,artist:`Javier Somoza`,license:`CC BY-SA 4.0`}},"rome/Supplì":{wiki:{title:`Supplì`,url:`https://en.wikipedia.org/wiki/Suppl%C3%AC`,extract:`Supplì are Italian snacks consisting of a ball of rice with tomato sauce, typical of Roman cuisine. Some believe that they derive from the French croquettes and were introduced to Rome by the French troops of Napoleon at the beginning of the 19th century.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/Suppl%C3%AC.jpg/960px-Suppl%C3%AC.jpg`,page:`https://commons.wikimedia.org/wiki/File:Suppl%C3%AC.jpg`,artist:`FrederikBianko`,license:`CC BY-SA 3.0`}},"rome/Roman-Style Artichokes":{wiki:{title:`Carciofi alla giudia`,url:`https://en.wikipedia.org/wiki/Carciofi_alla_giudia`,extract:`Carciofi alla giudìa is among the best-known dishes of Roman Jewish cuisine. It is essentially a deep-fried artichoke, and the recipe originated in the Jewish community of Rome, giudìo being the exonym for the Jewish people in the Romanesco language.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7c/Carciofo_alla_Giudia.jpg/960px-Carciofo_alla_Giudia.jpg`,page:`https://commons.wikimedia.org/wiki/File:Carciofo_alla_Giudia.jpg`,artist:`Simone.lippi`,license:`CC BY-SA 3.0`}},"rome/Saltimbocca":{wiki:{title:`Saltimbocca`,url:`https://en.wikipedia.org/wiki/Saltimbocca`,extract:`Saltimbocca is an Italian dish. It consists of veal that has been wrapped (lined) with prosciutto and sage and then marinated in wine, oil or salt water, depending on the region or one's own taste.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Saltimbocca_01.jpg/960px-Saltimbocca_01.jpg`,page:`https://commons.wikimedia.org/wiki/File:Saltimbocca_01.jpg`,artist:`Arnaud 25`,license:`CC BY-SA 4.0`}},"rome/Maritozzo":{wiki:{title:`Maritozzo`,url:`https://en.wikipedia.org/wiki/Maritozzo`,extract:`Maritozzo is a traditional Italian cream bun consisting of bread filled with a generous amount of whipped cream. Originally, "maritozzo" referred only to the bread part, and the version filled with whipped cream was called maritozzo con la panna, meaning "maritozzo with whipped cream".`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/Maritozzo_presso_Caff%C3%A8_delle_colline%2C_Reggio_Emilia.jpg/960px-Maritozzo_presso_Caff%C3%A8_delle_colline%2C_Reggio_Emilia.jpg`,page:`https://commons.wikimedia.org/wiki/File:Maritozzo_presso_Caff%C3%A8_delle_colline,_Reggio_Emilia.jpg`,artist:`Ensahequ`,license:`CC BY-SA 4.0`}},"dish:Lampredotto":{wiki:{title:`Lampredotto`,url:`https://en.wikipedia.org/wiki/Lampredotto`,extract:`Lampredotto is a typical Florentine dish, made from the fourth and final stomach of cattle, the abomasum.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/Lampredotto_2.jpg/960px-Lampredotto_2.jpg`,page:`https://commons.wikimedia.org/wiki/File:Lampredotto_2.jpg`,artist:`Lucarelli`,license:`CC BY-SA 3.0`}},"dish:Chianti":{wiki:{title:`Chianti`,url:`https://en.wikipedia.org/wiki/Chianti`,extract:`Chianti is an Italian red wine produced in the Chianti region of central Tuscany, principally from the Sangiovese grape. It was historically associated with a squat bottle enclosed in a straw basket, called a fiasco. However, the fiasco is now only used by a few makers of the wine; most Chianti is bottled in more standard-shaped wine bottles.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/6/66/Fiasco_di_vino_rosso_da_tavola_Monteriggioni.jpg`,page:`https://commons.wikimedia.org/wiki/File:Fiasco_di_vino_rosso_da_tavola_Monteriggioni.jpg`,artist:`giulio nepi`,license:`CC BY 2.0`}},"dish:Ribollita":{wiki:{title:`Ribollita`,url:`https://en.wikipedia.org/wiki/Ribollita`,extract:`Ribollita is a Tuscan panade made with bread and vegetables, often from leftovers. There are many variations, but it usually contains cannellini beans, lacinato kale, cabbage and inexpensive vegetables such as carrot, beans, chard, celery, potatoes and onion. It is often baked in a clay pot.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a3/Ribollita_Siena.jpg/960px-Ribollita_Siena.jpg`,page:`https://commons.wikimedia.org/wiki/File:Ribollita_Siena.jpg`,artist:`Ta4e Negodue`,license:`CC BY-SA 4.0`}},"dish:Bistecca alla fiorentina":{wiki:{title:`Bistecca alla fiorentina`,url:`https://en.wikipedia.org/wiki/Bistecca_alla_fiorentina`,extract:`Bistecca alla fiorentina is an Italian steak dish made of young steer (vitellone) or heifer (scottona) that is one of the most famous dishes in Tuscan cuisine. It is loin steak on the bone cooked on a grill until rare (50 °C).`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/1/12/Bistecca_alla_fiorentina-01.jpg`,page:`https://commons.wikimedia.org/wiki/File:Bistecca_alla_fiorentina-01.jpg`,artist:`mike packard`,license:`CC BY-SA 2.0`}},"dish:Biscotti":{wiki:{title:`Biscotti`,url:`https://en.wikipedia.org/wiki/Biscotti`,extract:`Biscotti are Italian almond biscuits originating in the city of Prato, Tuscany. They are twice-baked, oblong-shaped, dry, and crunchy. In Italy, they are known as cantucci, biscotti di Prato or biscotti etruschi and may be dipped in a drink, traditionally Vin Santo. Smaller biscotti may be known as biscottini or cantuccini. In Italian, the word biscotti encompasses all types of biscuits or cookies.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/Cantuccini-Toscani.jpg/960px-Cantuccini-Toscani.jpg`,page:`https://commons.wikimedia.org/wiki/File:Cantuccini-Toscani.jpg`,artist:`Gwang17 - Blog: intoafoodcoma.wordpress.com`,license:`CC BY-SA 4.0`}},"dish:Gelato":{wiki:{title:`Gelato`,url:`https://en.wikipedia.org/wiki/Gelato`,extract:`Gelato refers to a specific type of ice cream of Italian origin. In Italian, gelato is the common word for all types of ice cream. Artisanal gelato in Italy generally contains 6–9% butterfat, which is lower than other styles of frozen dessert.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3a/Delicious_Gelato_on_display.jpg/960px-Delicious_Gelato_on_display.jpg`,page:`https://commons.wikimedia.org/wiki/File:Delicious_Gelato_on_display.jpg`,artist:`EquipmentAndConcepts`,license:`CC BY-SA 4.0`}},"dish:Affogato":{wiki:{title:`Affogato`,url:`https://en.wikipedia.org/wiki/Affogato`,extract:`Affogato, or more fully affogato al caffè, is an Italian dessert comprising a scoop of gelato, either fiordilatte or vanilla, topped with espresso. Some variations add a shot of amaretto, bicerin, Kahlúa, or other liqueur.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/17/Vinoteca%2C_Smithfield%2C_London_%284485849609%29.jpg/960px-Vinoteca%2C_Smithfield%2C_London_%284485849609%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Vinoteca,_Smithfield,_London_(4485849609).jpg`,artist:`Ewan Munro from London, UK`,license:`CC BY-SA 2.0`}},"dish:Pappa al pomodoro":{wiki:{title:`Pappa al pomodoro`,url:`https://en.wikipedia.org/wiki/Pappa_al_pomodoro`,extract:`Pappa al pomodoro is a thick Tuscan bread soup typically prepared with fresh tomatoes, bread, olive oil, garlic, basil, and various other fresh ingredients. The bread is usually stale or leftover. A basic preparation of pappa al pomodoro involves lightly frying the garlic in oil, before briefly cooking it in a soup with the tomatoes, bread, and basil.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d9/PappaPomodoro.png/960px-PappaPomodoro.png`,page:`https://commons.wikimedia.org/wiki/File:PappaPomodoro.png`,artist:`Ɱ`,license:`CC BY-SA 3.0`}},"florence/Florentine T-bone Steak":{wiki:{title:`Bistecca alla fiorentina`,url:`https://en.wikipedia.org/wiki/Bistecca_alla_fiorentina`,extract:`Bistecca alla fiorentina is an Italian steak dish made of young steer (vitellone) or heifer (scottona) that is one of the most famous dishes in Tuscan cuisine. It is loin steak on the bone cooked on a grill until rare (50 °C).`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/1/12/Bistecca_alla_fiorentina-01.jpg`,page:`https://commons.wikimedia.org/wiki/File:Bistecca_alla_fiorentina-01.jpg`,artist:`mike packard`,license:`CC BY-SA 2.0`}},"florence/Lampredotto Sandwich":{wiki:{title:`Lampredotto`,url:`https://en.wikipedia.org/wiki/Lampredotto`,extract:`Lampredotto is a typical Florentine dish, made from the fourth and final stomach of cattle, the abomasum.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/Lampredotto_2.jpg/960px-Lampredotto_2.jpg`,page:`https://commons.wikimedia.org/wiki/File:Lampredotto_2.jpg`,artist:`Lucarelli`,license:`CC BY-SA 3.0`}},"florence/Ribollita":{wiki:{title:`Ribollita`,url:`https://en.wikipedia.org/wiki/Ribollita`,extract:`Ribollita is a Tuscan panade made with bread and vegetables, often from leftovers. There are many variations, but it usually contains cannellini beans, lacinato kale, cabbage and inexpensive vegetables such as carrot, beans, chard, celery, potatoes and onion. It is often baked in a clay pot.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a3/Ribollita_Siena.jpg/960px-Ribollita_Siena.jpg`,page:`https://commons.wikimedia.org/wiki/File:Ribollita_Siena.jpg`,artist:`Ta4e Negodue`,license:`CC BY-SA 4.0`}},"florence/Pappa al Pomodoro":{wiki:{title:`Pappa al pomodoro`,url:`https://en.wikipedia.org/wiki/Pappa_al_pomodoro`,extract:`Pappa al pomodoro is a thick Tuscan bread soup typically prepared with fresh tomatoes, bread, olive oil, garlic, basil, and various other fresh ingredients. The bread is usually stale or leftover. A basic preparation of pappa al pomodoro involves lightly frying the garlic in oil, before briefly cooking it in a soup with the tomatoes, bread, and basil.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d9/PappaPomodoro.png/960px-PappaPomodoro.png`,page:`https://commons.wikimedia.org/wiki/File:PappaPomodoro.png`,artist:`Ɱ`,license:`CC BY-SA 3.0`}},"florence/Schiacciata Sandwich":{wiki:{title:`Focaccia`,url:`https://en.wikipedia.org/wiki/Focaccia`,extract:`Focaccia is a flat leavened oven-baked Italian bread. It is similar to a flatbread called pizza bianca in Roman cuisine.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/Focaccia_with_Crumb.jpg/960px-Focaccia_with_Crumb.jpg`,page:`https://commons.wikimedia.org/wiki/File:Focaccia_with_Crumb.jpg`,artist:`Fred Benenson`,license:`CC BY-SA 4.0`}},"florence/Cantucci with Vin Santo":{wiki:{title:`Biscotti`,url:`https://en.wikipedia.org/wiki/Biscotti`,extract:`Biscotti are Italian almond biscuits originating in the city of Prato, Tuscany. They are twice-baked, oblong-shaped, dry, and crunchy. In Italy, they are known as cantucci, biscotti di Prato or biscotti etruschi and may be dipped in a drink, traditionally Vin Santo. Smaller biscotti may be known as biscottini or cantuccini. In Italian, the word biscotti encompasses all types of biscuits or cookies.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/Cantuccini-Toscani.jpg/960px-Cantuccini-Toscani.jpg`,page:`https://commons.wikimedia.org/wiki/File:Cantuccini-Toscani.jpg`,artist:`Gwang17 - Blog: intoafoodcoma.wordpress.com`,license:`CC BY-SA 4.0`}},"dish:Baccalà mantecato":{wiki:{title:`Baccalà mantecato`,url:`https://en.wikipedia.org/wiki/Baccal%C3%A0_mantecato`,extract:`Baccalà mantecato, meaning 'whipped salt cod spread' or 'creamed cod', is a Venetian appetizer (antipasto) made with dried cod (stockfish).`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bc/%22_13_-_ITALY_-_Cicchetti_Venetian_cuisine_appetizers_restaurant_%28_not_are_tapas_are_ciccheti_of_Venice%29_in_this_pics_Baccal%C3%A0_mantecato_%28Cod%29.jpg/960px-%22_13_-_ITALY_-_Cicchetti_Venetian_cuisine_appetizers_restaurant_%28_not_are_tapas_are_ciccheti_of_Venice%29_in_this_pics_Baccal%C3%A0_mantecato_%28Cod%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:%22_13_-_ITALY_-_Cicchetti_Venetian_cuisine_appetizers_restaurant_(_not_are_tapas_are_ciccheti_of_Venice)_in_this_pics_Baccal%C3%A0_mantecato_(Cod).jpg`,artist:`Ben & Lisa Waters [1]`,license:`CC BY 2.0`}},"dish:Cicchetti":{wiki:{title:`Cicchetti`,url:`https://en.wikipedia.org/wiki/Cicchetti`,extract:`Cicchetti, also sometimes spelled cichetti, are small snacks or side dishes, typically served in traditional bacari in Venice, Italy. Common cicchetti include tiny tramezzini, plates of olives or other vegetables, halved hard-boiled eggs, small servings of a combination of one or more of seafood, meat and vegetable ingredients laid on top of a slice of bread or polenta, and very small servings of typical full-course…`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/94/Cicchetti_Venezia_%281%29.jpg/960px-Cicchetti_Venezia_%281%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Cicchetti_Venezia_(1).jpg`,artist:`Benreis`,license:`CC BY-SA 4.0`}},"dish:Liver and onions":{wiki:{title:`Liver and onions`,url:`https://en.wikipedia.org/wiki/Liver_and_onions`,extract:`Liver and onions is a dish consisting of slices of liver and onions. The liver and the onions are usually sautéed or otherwise cooked together, but sometimes they may be sautéed separately and mixed together afterwards. The liver is often cut in fine slices, but it also may be diced.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/4/47/Tortillas_con_biste_de_higado.jpg`,page:`https://commons.wikimedia.org/wiki/File:Tortillas_con_biste_de_higado.jpg`,artist:`Jdvillalobos`,license:`CC BY 3.0`}},"dish:Tramezzino":{wiki:{title:`Tramezzino`,url:`https://en.wikipedia.org/wiki/Tramezzino`,extract:`Tramezzino is an Italian sandwich consisting of two slices of soft white bread, with the crusts removed, usually cut in a triangle. Popular fillings include prosciutto, tuna, and olives, but many other fillings can be used.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Tramezzino_%285268587628%29.jpg/960px-Tramezzino_%285268587628%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Tramezzino_(5268587628).jpg`,artist:`°linda°!°`,license:`CC BY 2.0`}},"dish:Sarde in saor":{wiki:{title:`Sarde in saor`,url:`https://en.wikipedia.org/wiki/Sarde_in_saor`,extract:`Sarde in saor are an Italian appetizer (antipasto) consisting of fried sardines, seasoned with sweet and sour onions, pine nuts, and raisins, typical of Venetian cuisine. They are a form of cicchetti, often served as snacks in Venetian bacari.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/73/Sarde_in_saor_dans_un_restaurant_v%C3%A9nitien_%28d%C3%A9cembre_2022%29.JPG/960px-Sarde_in_saor_dans_un_restaurant_v%C3%A9nitien_%28d%C3%A9cembre_2022%29.JPG`,page:`https://commons.wikimedia.org/wiki/File:Sarde_in_saor_dans_un_restaurant_v%C3%A9nitien_(d%C3%A9cembre_2022).JPG`,artist:`Benoît Prieur`,license:`CC0`}},"dish:Fritto misto":{wiki:{title:`Fritto misto`,url:`https://en.wikipedia.org/wiki/Fritto_misto`,extract:`Fritto misto is a mainly savoury dish popular in the cooking of various regions of Italy; a range of ingredients – meat, fish and vegetables – may be used: the ingredients are cut into small strips and deep-fried in oil. Each region varies the ingredients for its local version. Fritto misto may be served as an appetiser (antipasto) or as a one-plate buffet dish.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Italy-Italia_Italian_Food_Fritto_misto_alla_piemontese_PxT.JPG/960px-Italy-Italia_Italian_Food_Fritto_misto_alla_piemontese_PxT.JPG`,page:`https://commons.wikimedia.org/wiki/File:Italy-Italia_Italian_Food_Fritto_misto_alla_piemontese_PxT.JPG`,artist:`Paolo*torino`,license:`CC BY-SA 3.0`}},"venice/Sweet-and-Sour Sardines":{wiki:{title:`Sarde in saor`,url:`https://en.wikipedia.org/wiki/Sarde_in_saor`,extract:`Sarde in saor are an Italian appetizer (antipasto) consisting of fried sardines, seasoned with sweet and sour onions, pine nuts, and raisins, typical of Venetian cuisine. They are a form of cicchetti, often served as snacks in Venetian bacari.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/73/Sarde_in_saor_dans_un_restaurant_v%C3%A9nitien_%28d%C3%A9cembre_2022%29.JPG/960px-Sarde_in_saor_dans_un_restaurant_v%C3%A9nitien_%28d%C3%A9cembre_2022%29.JPG`,page:`https://commons.wikimedia.org/wiki/File:Sarde_in_saor_dans_un_restaurant_v%C3%A9nitien_(d%C3%A9cembre_2022).JPG`,artist:`Benoît Prieur`,license:`CC0`}},"venice/Creamed Salt Cod":{wiki:{title:`Baccalà mantecato`,url:`https://en.wikipedia.org/wiki/Baccal%C3%A0_mantecato`,extract:`Baccalà mantecato, meaning 'whipped salt cod spread' or 'creamed cod', is a Venetian appetizer (antipasto) made with dried cod (stockfish).`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bc/%22_13_-_ITALY_-_Cicchetti_Venetian_cuisine_appetizers_restaurant_%28_not_are_tapas_are_ciccheti_of_Venice%29_in_this_pics_Baccal%C3%A0_mantecato_%28Cod%29.jpg/960px-%22_13_-_ITALY_-_Cicchetti_Venetian_cuisine_appetizers_restaurant_%28_not_are_tapas_are_ciccheti_of_Venice%29_in_this_pics_Baccal%C3%A0_mantecato_%28Cod%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:%22_13_-_ITALY_-_Cicchetti_Venetian_cuisine_appetizers_restaurant_(_not_are_tapas_are_ciccheti_of_Venice)_in_this_pics_Baccal%C3%A0_mantecato_(Cod).jpg`,artist:`Ben & Lisa Waters [1]`,license:`CC BY 2.0`}},"venice/Bigoli in Salsa":{wiki:{title:`Bigoli in salsa`,url:`https://en.wikipedia.org/wiki/Bigoli_in_salsa`,extract:`Bigoli in salsa is a Venetian pasta dish made with whole-wheat bigoli, anchovies, extra virgin olive oil, and onion. While today anchovies are usually used, in the past it was often prepared with sardines. It is considered one of the signature dishes of Venice.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/Bigoli_with_anchovy_sauce_at_Ristorante_Ribot%2C_Venice.jpg/960px-Bigoli_with_anchovy_sauce_at_Ristorante_Ribot%2C_Venice.jpg`,page:`https://commons.wikimedia.org/wiki/File:Bigoli_with_anchovy_sauce_at_Ristorante_Ribot,_Venice.jpg`,artist:`brownpau from Washington, DC`,license:`CC BY 2.0`}},"venice/Venetian-Style Liver":{wiki:{title:`Liver and onions`,url:`https://en.wikipedia.org/wiki/Liver_and_onions`,extract:`Liver and onions is a dish consisting of slices of liver and onions. The liver and the onions are usually sautéed or otherwise cooked together, but sometimes they may be sautéed separately and mixed together afterwards. The liver is often cut in fine slices, but it also may be diced.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/4/47/Tortillas_con_biste_de_higado.jpg`,page:`https://commons.wikimedia.org/wiki/File:Tortillas_con_biste_de_higado.jpg`,artist:`Jdvillalobos`,license:`CC BY 3.0`}},"venice/Tramezzino":{wiki:{title:`Tramezzino`,url:`https://en.wikipedia.org/wiki/Tramezzino`,extract:`Tramezzino is an Italian sandwich consisting of two slices of soft white bread, with the crusts removed, usually cut in a triangle. Popular fillings include prosciutto, tuna, and olives, but many other fillings can be used.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Tramezzino_%285268587628%29.jpg/960px-Tramezzino_%285268587628%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Tramezzino_(5268587628).jpg`,artist:`°linda°!°`,license:`CC BY 2.0`}},"dish:Okonomiyaki":{wiki:{title:`Okonomiyaki`,url:`https://en.wikipedia.org/wiki/Okonomiyaki`,extract:`Okonomiyaki is a Japanese teppanyaki savory pancake dish consisting of wheat flour batter and other ingredients cooked on a teppan. Common additions include cabbage, meat, and seafood, and toppings include okonomiyaki sauce, aonori, katsuobushi, Japanese mayonnaise, and pickled ginger.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/Okonomiyaki_001.jpg/960px-Okonomiyaki_001.jpg`,page:`https://commons.wikimedia.org/wiki/File:Okonomiyaki_001.jpg`,artist:`ume-y`,license:`CC BY 2.0`}},"dish:Tsukemen":{wiki:{title:`Tsukemen`,url:`https://en.wikipedia.org/wiki/Tsukemen`,extract:`Tsukemen is a ramen dish in Japanese cuisine consisting of noodles that are eaten after being dipped in a separate bowl of soup or broth. The dish was invented in 1961 by Kazuo Yamagishi, a restaurateur in Tokyo, Japan. Since then, the dish has become popular throughout Japan, as well as overseas in the United States.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Tsukemen_at_a_Tokyo_restaurant.jpg/960px-Tsukemen_at_a_Tokyo_restaurant.jpg`,page:`https://commons.wikimedia.org/wiki/File:Tsukemen_at_a_Tokyo_restaurant.jpg`,artist:`City Foodsters`,license:`CC BY 2.0`}},"dish:Dandan noodles":{wiki:{title:`Dandan noodles`,url:`https://en.wikipedia.org/wiki/Dandan_noodles`,extract:`Dandan noodles is a Chinese noodle dish originating from Sichuan cuisine. The dish consists of wheat noodles served with a spicy sauce that usually contains pickled vegetables such as zha cai or ya cai, chili oil, Sichuan pepper, and minced pork, and is topped with scallions and peanuts. The dish can be served either dry, as in the Chengdu style, or as a noodle soup, as in the Hong Kong style.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Dan-dan_noodles%2C_Shanghai.jpg/960px-Dan-dan_noodles%2C_Shanghai.jpg`,page:`https://commons.wikimedia.org/wiki/File:Dan-dan_noodles,_Shanghai.jpg`,artist:`Steven G. Johnson`,license:`CC BY-SA 3.0`}},"dish:Momiji manjū":{wiki:{title:`Momiji manjū`,url:`https://en.wikipedia.org/wiki/Momiji_manj%C5%AB`,extract:`Momiji manjū is a type of wagashi that is baked. The confection is a buckwheat and rice cake shaped like a Japanese maple leaf, and is a local specialty on the island of Itsukushima (Miyajima) in Hiroshima. It is typically filled with red bean paste.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/Momiji_Manju_Hiroshima.JPG/960px-Momiji_Manju_Hiroshima.JPG`,page:`https://commons.wikimedia.org/wiki/File:Momiji_Manju_Hiroshima.JPG`,artist:`NY066`,license:`CC BY-SA 3.0`}},"dish:Danish pastry":{wiki:{title:`Danish pastry`,url:`https://en.wikipedia.org/wiki/Danish_pastry`,extract:`A Danish pastry is a multilayered, laminated sweet viennoiserie. Like other viennoiserie, such as croissants, it is neither a bread nor a pastry, as it uses yeast-leavened dough, that is laminated like puff pastry to create a layered texture.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Glazed_apple_Danish.jpg/960px-Glazed_apple_Danish.jpg`,page:`https://commons.wikimedia.org/wiki/File:Glazed_apple_Danish.jpg`,artist:`Peter Isotalo`,license:`CC BY-SA 3.0`}},"hiroshima/Hiroshima-style okonomiyaki":{wiki:{title:`Okonomiyaki`,url:`https://en.wikipedia.org/wiki/Okonomiyaki`,extract:`Okonomiyaki is a Japanese teppanyaki savory pancake dish consisting of wheat flour batter and other ingredients cooked on a teppan. Common additions include cabbage, meat, and seafood, and toppings include okonomiyaki sauce, aonori, katsuobushi, Japanese mayonnaise, and pickled ginger.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/Okonomiyaki_001.jpg/960px-Okonomiyaki_001.jpg`,page:`https://commons.wikimedia.org/wiki/File:Okonomiyaki_001.jpg`,artist:`ume-y`,license:`CC BY 2.0`}},"hiroshima/Grilled oysters":{wiki:{title:`Oyster`,url:`https://en.wikipedia.org/wiki/Oyster`,extract:`Oyster is the common name for a number of different families of salt-water bivalve molluscs that live in marine or brackish habitats. In some species, the valves are highly calcified, and many are somewhat irregular in shape. Many oysters are in the superfamily Ostreoidea.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/Crassostrea_gigas_p1040848.jpg/960px-Crassostrea_gigas_p1040848.jpg`,page:`https://commons.wikimedia.org/wiki/File:Crassostrea_gigas_p1040848.jpg`,artist:`David Monniaux`,license:`CC BY-SA 3.0`}},"hiroshima/Anago-meshi":{wiki:{title:`Anago`,url:`https://en.wikipedia.org/wiki/Anago`,extract:`Anago is the Japanese word for saltwater eels, normally referring to ma-anago. Ma-anago are used for a seafood dish in Japan. They are often simmered (sushi) or deep-fried (tempura), compared to unagi which are usually barbecued with a sauce (kabayaki). Anago is also slightly less rich and oily than unagi. Anago has a very soft texture and sweet taste.`}},"hiroshima/Momiji manju":{wiki:{title:`Momiji manjū`,url:`https://en.wikipedia.org/wiki/Momiji_manj%C5%AB`,extract:`Momiji manjū is a type of wagashi that is baked. The confection is a buckwheat and rice cake shaped like a Japanese maple leaf, and is a local specialty on the island of Itsukushima (Miyajima) in Hiroshima. It is typically filled with red bean paste.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/Momiji_Manju_Hiroshima.JPG/960px-Momiji_Manju_Hiroshima.JPG`,page:`https://commons.wikimedia.org/wiki/File:Momiji_Manju_Hiroshima.JPG`,artist:`NY066`,license:`CC BY-SA 3.0`}},"hiroshima/Shiru-nashi tantanmen":{wiki:{title:`Dandan noodles`,url:`https://en.wikipedia.org/wiki/Dandan_noodles`,extract:`Dandan noodles is a Chinese noodle dish originating from Sichuan cuisine. The dish consists of wheat noodles served with a spicy sauce that usually contains pickled vegetables such as zha cai or ya cai, chili oil, Sichuan pepper, and minced pork, and is topped with scallions and peanuts. The dish can be served either dry, as in the Chengdu style, or as a noodle soup, as in the Hong Kong style.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Dan-dan_noodles%2C_Shanghai.jpg/960px-Dan-dan_noodles%2C_Shanghai.jpg`,page:`https://commons.wikimedia.org/wiki/File:Dan-dan_noodles,_Shanghai.jpg`,artist:`Steven G. Johnson`,license:`CC BY-SA 3.0`}},"hiroshima/Hiroshima tsukemen":{wiki:{title:`Tsukemen`,url:`https://en.wikipedia.org/wiki/Tsukemen`,extract:`Tsukemen is a ramen dish in Japanese cuisine consisting of noodles that are eaten after being dipped in a separate bowl of soup or broth. The dish was invented in 1961 by Kazuo Yamagishi, a restaurateur in Tokyo, Japan. Since then, the dish has become popular throughout Japan, as well as overseas in the United States.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Tsukemen_at_a_Tokyo_restaurant.jpg/960px-Tsukemen_at_a_Tokyo_restaurant.jpg`,page:`https://commons.wikimedia.org/wiki/File:Tsukemen_at_a_Tokyo_restaurant.jpg`,artist:`City Foodsters`,license:`CC BY 2.0`}},"dish:Sushi":{wiki:{title:`Sushi`,url:`https://en.wikipedia.org/wiki/Sushi`,extract:`Sushi is a traditional Japanese dish made with vinegared rice , typically seasoned with sugar and salt, and combined with a variety of ingredients , such as seafood, vegetables, or meat; raw seafood is the most common, although some may be cooked. While sushi has numerous styles and presentations, the current defining component is the vinegared rice, also known as shari (しゃり), or sumeshi (酢飯).`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Sushi_platter.jpg/960px-Sushi_platter.jpg`,page:`https://commons.wikimedia.org/wiki/File:Sushi_platter.jpg`,artist:`chidorian from Japan`,license:`CC BY-SA 2.0`}},"dish:Tonkatsu":{wiki:{title:`Tonkatsu`,url:`https://en.wikipedia.org/wiki/Tonkatsu`,extract:`Tonkatsu is a type of Japanese cutlet made from pork. Slices of pork loin or fillet are coated with panko and then deep-fried in oil.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/%22Amai-Yuwaku%22_Special_Loin_Pork_Cutlet1.jpg/960px-%22Amai-Yuwaku%22_Special_Loin_Pork_Cutlet1.jpg`,page:`https://commons.wikimedia.org/wiki/File:%22Amai-Yuwaku%22_Special_Loin_Pork_Cutlet1.jpg`,artist:`ＫｏＺ`,license:`CC BY-SA 4.0`}},"dish:Tempura":{wiki:{title:`Tempura`,url:`https://en.wikipedia.org/wiki/Tempura`,extract:`Tempura is a Japanese dish that usually consists of seafood and vegetables that have been coated in a thin batter and deep-fried. Tempura originated in the 16th century, when Portuguese Jesuits brought the Western-style cooking method of coating foods with flour and frying, via Nanban trade.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2e/Tempura_01.jpg/960px-Tempura_01.jpg`,page:`https://commons.wikimedia.org/wiki/File:Tempura_01.jpg`,artist:`Yaco*`,license:`CC BY 2.0`}},"dish:Yakitori":{wiki:{title:`Yakitori`,url:`https://en.wikipedia.org/wiki/Yakitori`,extract:`In Japanese cuisine, yakitori is chicken cooked on a skewer over a charcoal fire and seasoned with tare sauce or salt. The term sometimes refers to kushiyaki in general.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Cooking_yakitori.jpg/960px-Cooking_yakitori.jpg`,page:`https://commons.wikimedia.org/wiki/File:Cooking_yakitori.jpg`,artist:`竹麦魚(Searobin)`,license:`CC BY-SA 3.0`}},"dish:Oyakodon":{wiki:{title:`Oyakodon`,url:`https://en.wikipedia.org/wiki/Oyakodon`,extract:`Oyakodon (親子丼), literally "parent-and-child donburi", is a donburi, or Japanese rice bowl dish, in which chicken, egg, sliced scallion, and other ingredients are all simmered together in a kind of soup that is made with soy sauce and stock, and then served on top of a large bowl of rice. The name of the dish is a poetic reflection of both chicken and egg being used in the dish.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Oyakodon_003.jpg/960px-Oyakodon_003.jpg`,page:`https://commons.wikimedia.org/wiki/File:Oyakodon_003.jpg`,artist:`Ocdp`,license:`CC0`}},"dish:Monjayaki":{wiki:{title:`Monjayaki`,url:`https://en.wikipedia.org/wiki/Monjayaki`,extract:`Monjayaki is a type of Japanese pan-fried batter, popular in the Kantō region, similar to okonomiyaki, but using different liquid ingredients.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/Monjayaki_Before.JPG/960px-Monjayaki_Before.JPG`,page:`https://commons.wikimedia.org/wiki/File:Monjayaki_Before.JPG`,artist:`Jpatokal`,license:`CC BY-SA 3.0`}},"dish:Melonpan":{wiki:{title:`Melonpan`,url:`https://en.wikipedia.org/wiki/Melonpan`,extract:`Melonpan , also called melon bun or melon bread, is a Japanese sweetbun covered in a layer of crispy cookie dough. The texture resembles that of a melon, such as a cantaloupe. It is not traditionally melon-flavored.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a0/Melonpan_on_the_plastic_bag.jpg/960px-Melonpan_on_the_plastic_bag.jpg`,page:`https://commons.wikimedia.org/wiki/File:Melonpan_on_the_plastic_bag.jpg`,artist:`Kyu3a`,license:`CC BY-SA 4.0`}},"dish:Soba":{wiki:{title:`Soba`,url:`https://en.wikipedia.org/wiki/Soba`,extract:`Soba are Japanese noodles made from buckwheat flour, with varying amounts of wheat flour mixed in. It has an ashen brown color, and a slightly grainy texture. The noodles are served either chilled with a dipping sauce, or hot in a noodle soup. They are used in a wide variety of dishes.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9a/Dried_soba_noodles_by_FotoosVanRobin.jpg/960px-Dried_soba_noodles_by_FotoosVanRobin.jpg`,page:`https://commons.wikimedia.org/wiki/File:Dried_soba_noodles_by_FotoosVanRobin.jpg`,artist:`FotoosVanRobin`,license:`CC BY-SA 2.0`}},"tokyo/Sushi":{wiki:{title:`Sushi`,url:`https://en.wikipedia.org/wiki/Sushi`,extract:`Sushi is a traditional Japanese dish made with vinegared rice , typically seasoned with sugar and salt, and combined with a variety of ingredients , such as seafood, vegetables, or meat; raw seafood is the most common, although some may be cooked. While sushi has numerous styles and presentations, the current defining component is the vinegared rice, also known as shari (しゃり), or sumeshi (酢飯).`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Sushi_platter.jpg/960px-Sushi_platter.jpg`,page:`https://commons.wikimedia.org/wiki/File:Sushi_platter.jpg`,artist:`chidorian from Japan`,license:`CC BY-SA 2.0`}},"tokyo/Ramen":{wiki:{title:`Ramen`,url:`https://en.wikipedia.org/wiki/Ramen`,extract:`Ramen is a Japanese-Chinese fusion noodle dish. It includes Chinese-style alkaline wheat noodles served in several flavors of hot broth. Common flavors are soy sauce and miso, with typical toppings including sliced pork , nori, lacto-fermented bamboo shoots (menma), narutomaki, and scallions.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c3/Shoyu_Ramen%EF%BC%88Tokyo_Ramen%EF%BC%89_-_01.jpg/960px-Shoyu_Ramen%EF%BC%88Tokyo_Ramen%EF%BC%89_-_01.jpg`,page:`https://commons.wikimedia.org/wiki/File:Shoyu_Ramen%EF%BC%88Tokyo_Ramen%EF%BC%89_-_01.jpg`,artist:`Quercus acuta`,license:`CC BY-SA 4.0`}},"tokyo/Monjayaki":{wiki:{title:`Monjayaki`,url:`https://en.wikipedia.org/wiki/Monjayaki`,extract:`Monjayaki is a type of Japanese pan-fried batter, popular in the Kantō region, similar to okonomiyaki, but using different liquid ingredients.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/Monjayaki_Before.JPG/960px-Monjayaki_Before.JPG`,page:`https://commons.wikimedia.org/wiki/File:Monjayaki_Before.JPG`,artist:`Jpatokal`,license:`CC BY-SA 3.0`}},"tokyo/Tempura":{wiki:{title:`Tempura`,url:`https://en.wikipedia.org/wiki/Tempura`,extract:`Tempura is a Japanese dish that usually consists of seafood and vegetables that have been coated in a thin batter and deep-fried. Tempura originated in the 16th century, when Portuguese Jesuits brought the Western-style cooking method of coating foods with flour and frying, via Nanban trade.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2e/Tempura_01.jpg/960px-Tempura_01.jpg`,page:`https://commons.wikimedia.org/wiki/File:Tempura_01.jpg`,artist:`Yaco*`,license:`CC BY 2.0`}},"tokyo/Yakitori":{wiki:{title:`Yakitori`,url:`https://en.wikipedia.org/wiki/Yakitori`,extract:`In Japanese cuisine, yakitori is chicken cooked on a skewer over a charcoal fire and seasoned with tare sauce or salt. The term sometimes refers to kushiyaki in general.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Cooking_yakitori.jpg/960px-Cooking_yakitori.jpg`,page:`https://commons.wikimedia.org/wiki/File:Cooking_yakitori.jpg`,artist:`竹麦魚(Searobin)`,license:`CC BY-SA 3.0`}},"tokyo/Tonkatsu":{wiki:{title:`Tonkatsu`,url:`https://en.wikipedia.org/wiki/Tonkatsu`,extract:`Tonkatsu is a type of Japanese cutlet made from pork. Slices of pork loin or fillet are coated with panko and then deep-fried in oil.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/%22Amai-Yuwaku%22_Special_Loin_Pork_Cutlet1.jpg/960px-%22Amai-Yuwaku%22_Special_Loin_Pork_Cutlet1.jpg`,page:`https://commons.wikimedia.org/wiki/File:%22Amai-Yuwaku%22_Special_Loin_Pork_Cutlet1.jpg`,artist:`ＫｏＺ`,license:`CC BY-SA 4.0`}},"dish:Tamagoyaki":{wiki:{title:`Tamagoyaki`,url:`https://en.wikipedia.org/wiki/Tamagoyaki`,extract:`Tamagoyaki is a type of Japanese omelette made by rolling together several layers of fried beaten eggs. It is often prepared in a rectangular omelette pan called a makiyakinabe or tamagoyaki. The word "tamago" means egg in Japanese, and the word "yaki" means to be cooked over direct heat.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/0/06/%E9%B3%A5%E7%84%BC%E3%81%8D%E5%B1%85%E9%85%92%E5%B1%8B_%2839394233682%29.jpg/960px-%E9%B3%A5%E7%84%BC%E3%81%8D%E5%B1%85%E9%85%92%E5%B1%8B_%2839394233682%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:%E9%B3%A5%E7%84%BC%E3%81%8D%E5%B1%85%E9%85%92%E5%B1%8B_(39394233682).jpg`,artist:`極地狐`,license:`CC BY 2.0`}},"dish:Tsukemono":{wiki:{title:`Tsukemono`,url:`https://en.wikipedia.org/wiki/Tsukemono`,extract:`Tsukemono, oshinko or konomono are Japanese preserved vegetables. They are served with rice as an okazu, with drinks as an otsumami (snack), as an accompaniment to or garnish for meals, and as a course in the kaiseki portion of a Japanese tea ceremony.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Tsukemono2.jpg/960px-Tsukemono2.jpg`,page:`https://commons.wikimedia.org/wiki/File:Tsukemono2.jpg`,artist:`Mimissu`,license:`CC BY-SA 4.0`}},"dish:Inarizushi":{wiki:{title:`Sushi`,url:`https://en.wikipedia.org/wiki/Sushi`,extract:`Sushi is a traditional Japanese dish made with vinegared rice , typically seasoned with sugar and salt, and combined with a variety of ingredients , such as seafood, vegetables, or meat; raw seafood is the most common, although some may be cooked. While sushi has numerous styles and presentations, the current defining component is the vinegared rice, also known as shari (しゃり), or sumeshi (酢飯).`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Sushi_platter.jpg/960px-Sushi_platter.jpg`,page:`https://commons.wikimedia.org/wiki/File:Sushi_platter.jpg`,artist:`chidorian from Japan`,license:`CC BY-SA 2.0`}},"dish:Udon":{wiki:{title:`Udon`,url:`https://en.wikipedia.org/wiki/Udon`,extract:`Udon is a thick noodle made from wheat flour, used in Japanese cuisine. There are a variety of ways it is prepared and served. Its simplest form is in a soup as kake udon with a mild broth called kakejiru made from dashi, soy sauce, and mirin. It is usually topped with thinly chopped scallions. Other common toppings include prawn tempura, kakiage, abura-age, kamaboko, and shichimi spice added to taste.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/94/%E9%B6%8F%E5%A4%A9%E3%81%AE%E3%81%86%E3%81%A9%E3%82%93.jpg/960px-%E9%B6%8F%E5%A4%A9%E3%81%AE%E3%81%86%E3%81%A9%E3%82%93.jpg`,page:`https://commons.wikimedia.org/wiki/File:%E9%B6%8F%E5%A4%A9%E3%81%AE%E3%81%86%E3%81%A9%E3%82%93.jpg`,artist:`加茂川の民`,license:`CC0`}},"dish:Obanzai":{wiki:{title:`Obanzai`,url:`https://en.wikipedia.org/wiki/Obanzai`,extract:`Obanzai (おばんざい) is a traditional style of Japanese cuisine native to Kyoto. For food to be considered obanzai, at least half of its ingredients must be produced or processed in Kyoto. Ingredients in obanzai cooking must also be in season. Obanzai cooking heavily relies on vegetables and seafood, prepared simply.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/Obanzai-kyotofood-2018-12-30.jpg/960px-Obanzai-kyotofood-2018-12-30.jpg`,page:`https://commons.wikimedia.org/wiki/File:Obanzai-kyotofood-2018-12-30.jpg`,artist:`Nesnad`,license:`CC BY 4.0`}},"dish:Ramen":{wiki:{title:`Ramen`,url:`https://en.wikipedia.org/wiki/Ramen`,extract:`Ramen is a Japanese-Chinese fusion noodle dish. It includes Chinese-style alkaline wheat noodles served in several flavors of hot broth. Common flavors are soy sauce and miso, with typical toppings including sliced pork , nori, lacto-fermented bamboo shoots (menma), narutomaki, and scallions.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c3/Shoyu_Ramen%EF%BC%88Tokyo_Ramen%EF%BC%89_-_01.jpg/960px-Shoyu_Ramen%EF%BC%88Tokyo_Ramen%EF%BC%89_-_01.jpg`,page:`https://commons.wikimedia.org/wiki/File:Shoyu_Ramen%EF%BC%88Tokyo_Ramen%EF%BC%89_-_01.jpg`,artist:`Quercus acuta`,license:`CC BY-SA 4.0`}},"dish:Kaiseki":{wiki:{title:`Kaiseki`,url:`https://en.wikipedia.org/wiki/Kaiseki`,extract:`Kaiseki (懐石) or kaiseki-ryōri is a traditional multi-course Japanese dinner. The term also refers to the collection of skills and techniques that allow the preparation of such meals and is analogous to Western haute cuisine.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/Jisaku_Kaiseki_Ryori_01.jpg/960px-Jisaku_Kaiseki_Ryori_01.jpg`,page:`https://commons.wikimedia.org/wiki/File:Jisaku_Kaiseki_Ryori_01.jpg`,artist:`Unknown author`,license:`CC BY-SA 3.0`}},"kyoto/Kaiseki":{wiki:{title:`Kaiseki`,url:`https://en.wikipedia.org/wiki/Kaiseki`,extract:`Kaiseki (懐石) or kaiseki-ryōri is a traditional multi-course Japanese dinner. The term also refers to the collection of skills and techniques that allow the preparation of such meals and is analogous to Western haute cuisine.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/Jisaku_Kaiseki_Ryori_01.jpg/960px-Jisaku_Kaiseki_Ryori_01.jpg`,page:`https://commons.wikimedia.org/wiki/File:Jisaku_Kaiseki_Ryori_01.jpg`,artist:`Unknown author`,license:`CC BY-SA 3.0`}},"kyoto/Matcha sweets":{wiki:{title:`Matcha`,url:`https://en.wikipedia.org/wiki/Matcha`,extract:`Matcha is a finely ground powder of green tea specially processed from shade-grown tea leaves. Shade growing gives matcha its characteristic bright green color and strong umami flavor. Matcha is typically consumed suspended in hot water.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d9/Matcha_Scoop.jpg/960px-Matcha_Scoop.jpg`,page:`https://commons.wikimedia.org/wiki/File:Matcha_Scoop.jpg`,artist:`Evanhoever`,license:`CC BY-SA 4.0`}},"kyoto/Yatsuhashi":{wiki:{title:`Yatsuhashi`,url:`https://en.wikipedia.org/wiki/Yatsuhashi`,extract:`Yatsuhashi is a wagashi sold mainly as a miyagegashi . It is one of the best known meibutsu of Kyoto. It is made from glutinous rice flour , sugar, and cinnamon. Baked, it is similar to senbei. The shape of the hard crackers resembles a Japanese harp or koto, or a bamboo stalk cut lengthways.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/10/Yatsuhashi_20160422.JPG/960px-Yatsuhashi_20160422.JPG`,page:`https://commons.wikimedia.org/wiki/File:Yatsuhashi_20160422.JPG`,artist:`PekePON`,license:`CC BY-SA 4.0`}},"kyoto/Obanzai":{wiki:{title:`Obanzai`,url:`https://en.wikipedia.org/wiki/Obanzai`,extract:`Obanzai (おばんざい) is a traditional style of Japanese cuisine native to Kyoto. For food to be considered obanzai, at least half of its ingredients must be produced or processed in Kyoto. Ingredients in obanzai cooking must also be in season. Obanzai cooking heavily relies on vegetables and seafood, prepared simply.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/Obanzai-kyotofood-2018-12-30.jpg/960px-Obanzai-kyotofood-2018-12-30.jpg`,page:`https://commons.wikimedia.org/wiki/File:Obanzai-kyotofood-2018-12-30.jpg`,artist:`Nesnad`,license:`CC BY 4.0`}},"dish:Takoyaki":{wiki:{title:`Takoyaki`,url:`https://en.wikipedia.org/wiki/Takoyaki`,extract:`Takoyaki is a ball-shaped Japanese snack made of a wheat flour–based batter and cooked in a special molded pan. It is typically filled with minced or diced octopus, tempura scraps, pickled ginger, and green onion. The balls are brushed with takoyaki sauce and mayonnaise, and then sprinkled with green laver and shavings of dried bonito.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5c/%E3%82%BD%E3%83%BC%E3%82%B9%E3%81%A8%E3%83%9D%E3%83%B3%E9%85%A2%E3%81%AE%E3%81%9F%E3%81%93%E7%84%BC%E3%81%8D.jpg/960px-%E3%82%BD%E3%83%BC%E3%82%B9%E3%81%A8%E3%83%9D%E3%83%B3%E9%85%A2%E3%81%AE%E3%81%9F%E3%81%93%E7%84%BC%E3%81%8D.jpg`,page:`https://commons.wikimedia.org/wiki/File:%E3%82%BD%E3%83%BC%E3%82%B9%E3%81%A8%E3%83%9D%E3%83%B3%E9%85%A2%E3%81%AE%E3%81%9F%E3%81%93%E7%84%BC%E3%81%8D.jpg`,artist:`加茂川の民`,license:`CC0`}},"dish:Kushikatsu":{wiki:{title:`Kushikatsu`,url:`https://en.wikipedia.org/wiki/Kushikatsu`,extract:`Kushikatsu (串カツ), also known as kushiage (串揚げ), is a Japanese dish of deep-fried skewered meat and vegetables. In Japanese, kushi (串) refers to the skewers used while katsu means a deep-fried cutlet of meat.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f4/KushikatsuDaruma01.jpg/960px-KushikatsuDaruma01.jpg`,page:`https://commons.wikimedia.org/wiki/File:KushikatsuDaruma01.jpg`,artist:`Aiko99ann`,license:`CC BY-SA 3.0`}},"dish:Baozi":{wiki:{title:`Baozi`,url:`https://en.wikipedia.org/wiki/Baozi`,extract:`Baozi, or simply bao, is a type of yeast-leavened filled bun in various Chinese cuisines. There are many variations in fillings and preparations, though the buns are most often made from wheat flour and steamed. They are a variation of mantou from Northern China.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f4/Baozi_Chengdu.JPG/960px-Baozi_Chengdu.JPG`,page:`https://commons.wikimedia.org/wiki/File:Baozi_Chengdu.JPG`,artist:`Popo le Chien`,license:`CC0`}},"dish:Shumai":{wiki:{title:`Shumai`,url:`https://en.wikipedia.org/wiki/Shumai`,extract:`Shumai is a type of traditional Chinese dumpling meat made of ground pork. In Cantonese cuisine, it is usually served as a dim sum snack, and is served with an additional serving of soy sauce. In addition to accompanying the Chinese diaspora, variations of shumai can be found in Japan, Southeast Asia, and South America. Variations include the Hawaiian pork hash and the Indonesian siomay.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/Yellow_dim_sum_in_steamer_basket.jpg/960px-Yellow_dim_sum_in_steamer_basket.jpg`,page:`https://commons.wikimedia.org/wiki/File:Yellow_dim_sum_in_steamer_basket.jpg`,artist:`Mshuang2`,license:`CC0`}},"dish:Red bean soup":{wiki:{title:`Hong dou tang`,url:`https://en.wikipedia.org/wiki/Hong_dou_tang`,extract:`Hong dou tang (紅豆湯), hong dou sha (紅豆沙), or red bean soup is a sweet Chinese dessert soup made from azuki beans. It is served in mainland China, Taiwan, Hong Kong, Macau, and places with Chinese diaspora. It is categorized as a tong sui, or sweet soup. It is often served cold during the summer, and hot in the winter. Leftover red bean soup can also be frozen to make ice pops and is a popular dessert.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/63/HK_STT_%E7%9F%B3%E5%A1%98%E5%92%80_Shek_Tong_Tsui_%E5%B1%B1%E9%81%93_Hill_Road_%E6%A5%AD%E6%98%8C%E5%A4%A7%E5%BB%88_Yip_Cheong_Building_%E6%B5%B7%E6%82%85%E6%B5%B7%E9%AE%AE%E9%85%92%E5%AE%B6_Ocean_Palace_Seafood_Chinese_Restaurant_food_%E7%B4%85%E8%B1%86%E7%B3%96%E6%B0%B4_Red_bean_dessert_soup_September_2022_Px3_04.jpg/960px-thumbnail.jpg`,page:`https://commons.wikimedia.org/wiki/File:HK_STT_%E7%9F%B3%E5%A1%98%E5%92%80_Shek_Tong_Tsui_%E5%B1%B1%E9%81%93_Hill_Road_%E6%A5%AD%E6%98%8C%E5%A4%A7%E5%BB%88_Yip_Cheong_Building_%E6%B5%B7%E6%82%85%E6%B5%B7%E9%AE%AE%E9%85%92%E5%AE%B6_Ocean_Palace_Seafood_Chinese_Restaurant_food_%E7%B4%85%E8%B1%86%E7%B3%96%E6%B0%B4_Red_bean_dessert_soup_September_2022_Px3_04.jpg`,artist:`Shusm Wlwawiv AA`,license:`CC BY-SA 4.0`}},"dish:Horumonyaki":{wiki:{title:`Horumonyaki`,url:`https://en.wikipedia.org/wiki/Horumonyaki`,extract:`Horumonyaki is a kind of Japanese cuisine made from beef or pork offal. Kitazato Shigeo, the chef of a yōshoku restaurant in Osaka, devised this dish and registered a trademark in 1940. It was originally derived from yakiniku. The name horumon is derived from the word "hormone", with the intended meaning of "stimulation", as in the original Greek. Horumonyaki has a reputation for being a "stamina-building" food.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/%E3%83%9B%E3%83%AB%E3%83%A2%E3%83%B3%E7%84%BC%EF%BC%88%E3%82%80%E3%81%A4%E8%8F%8A%EF%BC%89.jpg/960px-%E3%83%9B%E3%83%AB%E3%83%A2%E3%83%B3%E7%84%BC%EF%BC%88%E3%82%80%E3%81%A4%E8%8F%8A%EF%BC%89.jpg`,page:`https://commons.wikimedia.org/wiki/File:%E3%83%9B%E3%83%AB%E3%83%A2%E3%83%B3%E7%84%BC%EF%BC%88%E3%82%80%E3%81%A4%E8%8F%8A%EF%BC%89.jpg`,artist:`くろふね`,license:`CC BY-SA 4.0`}},"osaka/Takoyaki":{wiki:{title:`Takoyaki`,url:`https://en.wikipedia.org/wiki/Takoyaki`,extract:`Takoyaki is a ball-shaped Japanese snack made of a wheat flour–based batter and cooked in a special molded pan. It is typically filled with minced or diced octopus, tempura scraps, pickled ginger, and green onion. The balls are brushed with takoyaki sauce and mayonnaise, and then sprinkled with green laver and shavings of dried bonito.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5c/%E3%82%BD%E3%83%BC%E3%82%B9%E3%81%A8%E3%83%9D%E3%83%B3%E9%85%A2%E3%81%AE%E3%81%9F%E3%81%93%E7%84%BC%E3%81%8D.jpg/960px-%E3%82%BD%E3%83%BC%E3%82%B9%E3%81%A8%E3%83%9D%E3%83%B3%E9%85%A2%E3%81%AE%E3%81%9F%E3%81%93%E7%84%BC%E3%81%8D.jpg`,page:`https://commons.wikimedia.org/wiki/File:%E3%82%BD%E3%83%BC%E3%82%B9%E3%81%A8%E3%83%9D%E3%83%B3%E9%85%A2%E3%81%AE%E3%81%9F%E3%81%93%E7%84%BC%E3%81%8D.jpg`,artist:`加茂川の民`,license:`CC0`}},"osaka/Okonomiyaki":{wiki:{title:`Okonomiyaki`,url:`https://en.wikipedia.org/wiki/Okonomiyaki`,extract:`Okonomiyaki is a Japanese teppanyaki savory pancake dish consisting of wheat flour batter and other ingredients cooked on a teppan. Common additions include cabbage, meat, and seafood, and toppings include okonomiyaki sauce, aonori, katsuobushi, Japanese mayonnaise, and pickled ginger.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/Okonomiyaki_001.jpg/960px-Okonomiyaki_001.jpg`,page:`https://commons.wikimedia.org/wiki/File:Okonomiyaki_001.jpg`,artist:`ume-y`,license:`CC BY 2.0`}},"osaka/Kushikatsu":{wiki:{title:`Kushikatsu`,url:`https://en.wikipedia.org/wiki/Kushikatsu`,extract:`Kushikatsu (串カツ), also known as kushiage (串揚げ), is a Japanese dish of deep-fried skewered meat and vegetables. In Japanese, kushi (串) refers to the skewers used while katsu means a deep-fried cutlet of meat.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f4/KushikatsuDaruma01.jpg/960px-KushikatsuDaruma01.jpg`,page:`https://commons.wikimedia.org/wiki/File:KushikatsuDaruma01.jpg`,artist:`Aiko99ann`,license:`CC BY-SA 3.0`}},"osaka/Kitsune udon":{wiki:{title:`Udon`,url:`https://en.wikipedia.org/wiki/Udon`,extract:`Udon is a thick noodle made from wheat flour, used in Japanese cuisine. There are a variety of ways it is prepared and served. Its simplest form is in a soup as kake udon with a mild broth called kakejiru made from dashi, soy sauce, and mirin. It is usually topped with thinly chopped scallions. Other common toppings include prawn tempura, kakiage, abura-age, kamaboko, and shichimi spice added to taste.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/94/%E9%B6%8F%E5%A4%A9%E3%81%AE%E3%81%86%E3%81%A9%E3%82%93.jpg/960px-%E9%B6%8F%E5%A4%A9%E3%81%AE%E3%81%86%E3%81%A9%E3%82%93.jpg`,page:`https://commons.wikimedia.org/wiki/File:%E9%B6%8F%E5%A4%A9%E3%81%AE%E3%81%86%E3%81%A9%E3%82%93.jpg`,artist:`加茂川の民`,license:`CC0`}},"osaka/Butaman":{wiki:{title:`Baozi`,url:`https://en.wikipedia.org/wiki/Baozi`,extract:`Baozi, or simply bao, is a type of yeast-leavened filled bun in various Chinese cuisines. There are many variations in fillings and preparations, though the buns are most often made from wheat flour and steamed. They are a variation of mantou from Northern China.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f4/Baozi_Chengdu.JPG/960px-Baozi_Chengdu.JPG`,page:`https://commons.wikimedia.org/wiki/File:Baozi_Chengdu.JPG`,artist:`Popo le Chien`,license:`CC0`}},"osaka/Horumon":{wiki:{title:`Horumonyaki`,url:`https://en.wikipedia.org/wiki/Horumonyaki`,extract:`Horumonyaki is a kind of Japanese cuisine made from beef or pork offal. Kitazato Shigeo, the chef of a yōshoku restaurant in Osaka, devised this dish and registered a trademark in 1940. It was originally derived from yakiniku. The name horumon is derived from the word "hormone", with the intended meaning of "stimulation", as in the original Greek. Horumonyaki has a reputation for being a "stamina-building" food.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/%E3%83%9B%E3%83%AB%E3%83%A2%E3%83%B3%E7%84%BC%EF%BC%88%E3%82%80%E3%81%A4%E8%8F%8A%EF%BC%89.jpg/960px-%E3%83%9B%E3%83%AB%E3%83%A2%E3%83%B3%E7%84%BC%EF%BC%88%E3%82%80%E3%81%A4%E8%8F%8A%EF%BC%89.jpg`,page:`https://commons.wikimedia.org/wiki/File:%E3%83%9B%E3%83%AB%E3%83%A2%E3%83%B3%E7%84%BC%EF%BC%88%E3%82%80%E3%81%A4%E8%8F%8A%EF%BC%89.jpg`,artist:`くろふね`,license:`CC BY-SA 4.0`}},"dish:Chicken chop":{wiki:{title:`Chicken chop`,url:`https://en.wikipedia.org/wiki/Chicken_chop`,extract:`Chicken chop is a dish invented by Hainanese migrant workers during the colonial Malaya period. The dish is a local adaptation of fried and grilled chicken, often found in Malaysian kopitiams and restaurants specialising in Hainanese cuisine or western cuisine.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/14/Chicken_Chop_With_French_Fries_and_Coleslaw.jpg/960px-Chicken_Chop_With_French_Fries_and_Coleslaw.jpg`,page:`https://commons.wikimedia.org/wiki/File:Chicken_Chop_With_French_Fries_and_Coleslaw.jpg`,artist:`Banej`,license:`CC BY-SA 3.0`}},"dish:Kaya toast":{wiki:{title:`Kaya toast`,url:`https://en.wikipedia.org/wiki/Kaya_toast`,extract:`Kaya toast is a dish consisting of two slices of toast with butter and kaya, commonly served alongside kopi and soft-boiled eggs. The dish was believed to be created by Hainanese immigrants to the Straits Settlements in the 19th century while serving on British ships at the Port of Singapore.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Kaya_toast_on_a_plate.jpg/960px-Kaya_toast_on_a_plate.jpg`,page:`https://commons.wikimedia.org/wiki/File:Kaya_toast_on_a_plate.jpg`,artist:`Pinklily08`,license:`CC BY-SA 4.0`}},"dish:Banana cake":{wiki:{title:`Banana cake`,url:`https://en.wikipedia.org/wiki/Banana_cake`,extract:`A banana cake is a cake prepared using banana as a primary ingredient and typical cake ingredients. It can be prepared in various manners, including as a layer cake, as muffins and as cupcakes. Steamed banana cake is found in Malaysian, Indonesian and Vietnamese cuisine. In the Philippines, the term "Banana Cake" refers to banana bread introduced during the American colonial period of the Philippines.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c8/Vegan_Banana_Celebration_Cake_%285061766386%29.jpg/960px-Vegan_Banana_Celebration_Cake_%285061766386%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Vegan_Banana_Celebration_Cake_(5061766386).jpg`,artist:`Vegan Feast Catering`,license:`CC BY 2.0`}},"dish:Fish head curry":{wiki:{title:`Fish head curry`,url:`https://en.wikipedia.org/wiki/Fish_head_curry`,extract:`Fish head curry is a dish in Malaysian and Singaporean cuisines with mixed Indian and Chinese origins. The head of a red snapper is stewed in a Kerala-style curry with assorted vegetables such as okra and eggplants. It is usually served with either rice or bread, or as a shared dish.`}},"dish:Lontong":{wiki:{title:`Lontong`,url:`https://en.wikipedia.org/wiki/Lontong`,extract:`Lontong is an Indonesian dish made of compressed rice cake in the form of a cylinder wrapped inside a banana leaf, commonly found in Indonesia, Malaysia, and Singapore. Rice is rolled inside a banana leaf and boiled, then cut into small cakes as a staple food replacement for steamed rice.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4e/Lontong.jpg/960px-Lontong.jpg`,page:`https://commons.wikimedia.org/wiki/File:Lontong.jpg`,artist:`No machine-readable author provided. Diádoco assumed (based on copyright claims).`,license:`CC BY 3.0`}},"dish:Laksa":{wiki:{title:`Laksa`,url:`https://en.wikipedia.org/wiki/Laksa`,extract:`Laksa is a spicy noodle dish popular in Southeast Asia. Laksa consists of various types of noodles, most commonly thick rice noodles, with toppings such as chicken, prawns or fish. Most variations of laksa are prepared with a rich and spicy coconut curry soup or a broth seasoned with a souring ingredient like tamarind or asam gelugur.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1c/Nyonya_Laksa.jpg/960px-Nyonya_Laksa.jpg`,page:`https://commons.wikimedia.org/wiki/File:Nyonya_Laksa.jpg`,artist:`Giddy98`,license:`CC BY-SA 4.0`}},"dish:Otak-otak":{wiki:{title:`Otak-otak`,url:`https://en.wikipedia.org/wiki/Otak-otak`,extract:`Otak-otak is a Southeast Asian fish cake made of ground fish mixed with spices and wrapped in leaf parcels. Otak-otak is traditionally served steamed or grilled, encased within the leaf parcel it is cooked in, and can be eaten solely as a snack or with steamed rice as part of a meal.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/10/Otak-otak_Jakarta.JPG/960px-Otak-otak_Jakarta.JPG`,page:`https://commons.wikimedia.org/wiki/File:Otak-otak_Jakarta.JPG`,artist:`Midori`,license:`CC BY 3.0`}},"johor-bahru/Laksa Johor":{wiki:{title:`Laksa`,url:`https://en.wikipedia.org/wiki/Laksa`,extract:`Laksa is a spicy noodle dish popular in Southeast Asia. Laksa consists of various types of noodles, most commonly thick rice noodles, with toppings such as chicken, prawns or fish. Most variations of laksa are prepared with a rich and spicy coconut curry soup or a broth seasoned with a souring ingredient like tamarind or asam gelugur.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1c/Nyonya_Laksa.jpg/960px-Nyonya_Laksa.jpg`,page:`https://commons.wikimedia.org/wiki/File:Nyonya_Laksa.jpg`,artist:`Giddy98`,license:`CC BY-SA 4.0`}},"johor-bahru/Mee Rebus":{wiki:{title:`Mee rebus`,url:`https://en.wikipedia.org/wiki/Mee_rebus`,extract:`Mee rebus ( mee rə-BOHSS or rə-BUUSS, Malay pronunciation: [mi rəbos], also known as mie rebus/mi rebus and mie kuah is a Maritime Southeast Asian noodle soup dish. Literally translated as "boiled noodles", it is popular in Maritime Southeast Asian countries such as Indonesia, Malaysia, and Singapore.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Mee_Rebus_by_Banej%2C_Singapore_October_2017.jpg/960px-Mee_Rebus_by_Banej%2C_Singapore_October_2017.jpg`,page:`https://commons.wikimedia.org/wiki/File:Mee_Rebus_by_Banej,_Singapore_October_2017.jpg`,artist:`Banej`,license:`CC BY-SA 3.0`}},"johor-bahru/Otak-Otak":{wiki:{title:`Otak-otak`,url:`https://en.wikipedia.org/wiki/Otak-otak`,extract:`Otak-otak is a Southeast Asian fish cake made of ground fish mixed with spices and wrapped in leaf parcels. Otak-otak is traditionally served steamed or grilled, encased within the leaf parcel it is cooked in, and can be eaten solely as a snack or with steamed rice as part of a meal.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/10/Otak-otak_Jakarta.JPG/960px-Otak-otak_Jakarta.JPG`,page:`https://commons.wikimedia.org/wiki/File:Otak-otak_Jakarta.JPG`,artist:`Midori`,license:`CC BY 3.0`}},"johor-bahru/Fish Head Curry":{wiki:{title:`Fish head curry`,url:`https://en.wikipedia.org/wiki/Fish_head_curry`,extract:`Fish head curry is a dish in Malaysian and Singaporean cuisines with mixed Indian and Chinese origins. The head of a red snapper is stewed in a Kerala-style curry with assorted vegetables such as okra and eggplants. It is usually served with either rice or bread, or as a shared dish.`}},"johor-bahru/Hainanese Chicken Chop":{wiki:{title:`Chicken chop`,url:`https://en.wikipedia.org/wiki/Chicken_chop`,extract:`Chicken chop is a dish invented by Hainanese migrant workers during the colonial Malaya period. The dish is a local adaptation of fried and grilled chicken, often found in Malaysian kopitiams and restaurants specialising in Hainanese cuisine or western cuisine.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/14/Chicken_Chop_With_French_Fries_and_Coleslaw.jpg/960px-Chicken_Chop_With_French_Fries_and_Coleslaw.jpg`,page:`https://commons.wikimedia.org/wiki/File:Chicken_Chop_With_French_Fries_and_Coleslaw.jpg`,artist:`Banej`,license:`CC BY-SA 3.0`}},"dish:Asam pedas":{wiki:{title:`Asam pedas`,url:`https://en.wikipedia.org/wiki/Asam_pedas`,extract:`Asam pedas is a traditional sour and spicy gulai commonly found in Southeast Asia, particularly in Malaysia, Indonesia and Singapore. The dish is typically associated with Malay, Minangkabau, Acehnese and Peranakan cuisines, and is prepared using various types of seafood or freshwater fish.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/ASAM_PEDAS_IKAN_PARI.jpg/960px-ASAM_PEDAS_IKAN_PARI.jpg`,page:`https://commons.wikimedia.org/wiki/File:ASAM_PEDAS_IKAN_PARI.jpg`,artist:`Elly Suhailee`,license:`CC BY-SA 4.0`}},"dish:Teh tarik":{wiki:{title:`Teh tarik`,url:`https://en.wikipedia.org/wiki/Teh_tarik`,extract:`Teh tarik is a hot milk tea beverage most commonly found in restaurants, outdoor stalls, mamaks and kopitiams in Malaysia, Brunei, Indonesia, Singapore, and Thailand. It is a common street drink culture in Malaysia, where it is considered the country's national drink.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Teh_Tarik_at_the_Iskandar_Curry_House_at_One_Riverside_%28DSCF0286%29.jpg/960px-Teh_Tarik_at_the_Iskandar_Curry_House_at_One_Riverside_%28DSCF0286%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Teh_Tarik_at_the_Iskandar_Curry_House_at_One_Riverside_(DSCF0286).jpg`,artist:`Yu Chu Chin`,license:`CC BY-SA 4.0`}},"dish:Nasi kandar":{wiki:{title:`Nasi kandar`,url:`https://en.wikipedia.org/wiki/Nasi_kandar`,extract:`Nasi kandar is a popular northern Malaysian dish from Penang, originally introduced by Tamil Muslim traders from India. The meal consists of steamed rice combined with an array of distinct curries, side dishes, and gravies. The selection of curries consists of various blends of vegetables, seafood or meat.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/A_plate_of_Nasi_Kandar.jpg/960px-A_plate_of_Nasi_Kandar.jpg`,page:`https://commons.wikimedia.org/wiki/File:A_plate_of_Nasi_Kandar.jpg`,artist:`Kutubkhanah`,license:`CC BY-SA 4.0`}},"dish:Rojak":{wiki:{title:`Rojak`,url:`https://en.wikipedia.org/wiki/Rojak`,extract:`Rojak or rujak is a salad dish of Javanese origin, commonly found in Indonesia, Malaysia, and Singapore. The most popular variant in all three countries is composed of a mixture of sliced fruit and vegetables and served with a spicy palm sugar dressing.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/Rujak_Buah_%28Indonesian_Fruit_Salad%29.JPG/960px-Rujak_Buah_%28Indonesian_Fruit_Salad%29.JPG`,page:`https://commons.wikimedia.org/wiki/File:Rujak_Buah_(Indonesian_Fruit_Salad).JPG`,artist:`Sofiah Budiastuti`,license:`CC BY-SA 4.0`}},"dish:Chilli crab":{wiki:{title:`Chilli crab`,url:`https://en.wikipedia.org/wiki/Chilli_crab`,extract:`Chilli crab is a Southeast Asian seafood dish that is most popular in the cuisines of Malaysia and Singapore. The widely known version of chilli crab today could be traced back to the 1950s in Malaysia and Singapore. Mud crabs are commonly used and are stir-fried in a semi-thick, sweet, and savoury tomato-and-chilli-based sauce.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/c/c6/Chilli_crab-02.jpg`,page:`https://commons.wikimedia.org/wiki/File:Chilli_crab-02.jpg`,artist:`megawatts86`,license:`CC BY-SA 2.0`}},"dish:Ikan bakar":{wiki:{title:`Ikan bakar`,url:`https://en.wikipedia.org/wiki/Ikan_bakar`,extract:`Ikan bakar is an Indonesian and Malay dish, prepared with charcoal-grilled fish or other forms of seafood. Ikan bakar literally means "grilled fish" in the Indonesian and Malay languages. Ikan bakar differs from other grilled fish dishes in that it often contains flavorings like bumbu, kecap manis, and sambal, and is covered in a banana leaf and cooked on a charcoal fire.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Gurame_bakar_kecap_2.JPG/960px-Gurame_bakar_kecap_2.JPG`,page:`https://commons.wikimedia.org/wiki/File:Gurame_bakar_kecap_2.JPG`,artist:`Gunawan Kartapranata`,license:`CC BY-SA 4.0`}},"dish:Gulai":{wiki:{title:`Gulai`,url:`https://en.wikipedia.org/wiki/Gulai`,extract:`Gulai is a type of spiced stew commonly found in the culinary traditions of Malaysia, Indonesia and other parts of Maritime Southeast Asia, including Brunei, Singapore and southern Thailand. Closely associated with both Malay and Minangkabau cuisines, it is characterised by a rich, aromatic sauce made from coconut milk and a blend of ground spices, typically including turmeric, coriander, chilli and other local…`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/Gulai_ayam3.jpg/960px-Gulai_ayam3.jpg`,page:`https://commons.wikimedia.org/wiki/File:Gulai_ayam3.jpg`,artist:`Sonia`,license:`CC BY-SA 4.0`}},"dish:Rendang":{wiki:{title:`Rendang`,url:`https://en.wikipedia.org/wiki/Rendang`,extract:`Rendang is a stir-fried meat dish or dry curry made of meat stewed in coconut milk and spices, widely popular across Indonesia, Malaysia, Singapore, Brunei, and the southern parts of the Philippines, where each version is considered local cuisine. It refers to both a cooking method of frying and the dish cooked in that way.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/Rendang_daging_sapi_asli_Padang.JPG/960px-Rendang_daging_sapi_asli_Padang.JPG`,page:`https://commons.wikimedia.org/wiki/File:Rendang_daging_sapi_asli_Padang.JPG`,artist:`Midori`,license:`CC BY 3.0`}},"langkawi/Laksa Langkawi":{wiki:{title:`Laksa`,url:`https://en.wikipedia.org/wiki/Laksa`,extract:`Laksa is a spicy noodle dish popular in Southeast Asia. Laksa consists of various types of noodles, most commonly thick rice noodles, with toppings such as chicken, prawns or fish. Most variations of laksa are prepared with a rich and spicy coconut curry soup or a broth seasoned with a souring ingredient like tamarind or asam gelugur.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1c/Nyonya_Laksa.jpg/960px-Nyonya_Laksa.jpg`,page:`https://commons.wikimedia.org/wiki/File:Nyonya_Laksa.jpg`,artist:`Giddy98`,license:`CC BY-SA 4.0`}},"langkawi/Nasi Campur":{wiki:{title:`Nasi campur`,url:`https://en.wikipedia.org/wiki/Nasi_campur`,extract:`Nasi campur, also known as nasi rames or sega campur in Java, refers to an Indonesian and Malay dish of a scoop of nasi putih accompanied by small portions of several other dishes, including meats, vegetables, peanuts, eggs, and fried-shrimp krupuk.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/2/25/Plate_of_nasi_campur_%28Mandarin_Oriental_Hotel_Mahapahit%2C_Surabaya%2C_Indonesia%29.png`,page:`https://commons.wikimedia.org/wiki/File:Plate_of_nasi_campur_(Mandarin_Oriental_Hotel_Mahapahit,_Surabaya,_Indonesia).png`,artist:`Unknown author`,license:`Public domain`}},"langkawi/Ikan Bakar":{wiki:{title:`Ikan bakar`,url:`https://en.wikipedia.org/wiki/Ikan_bakar`,extract:`Ikan bakar is an Indonesian and Malay dish, prepared with charcoal-grilled fish or other forms of seafood. Ikan bakar literally means "grilled fish" in the Indonesian and Malay languages. Ikan bakar differs from other grilled fish dishes in that it often contains flavorings like bumbu, kecap manis, and sambal, and is covered in a banana leaf and cooked on a charcoal fire.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Gurame_bakar_kecap_2.JPG/960px-Gurame_bakar_kecap_2.JPG`,page:`https://commons.wikimedia.org/wiki/File:Gurame_bakar_kecap_2.JPG`,artist:`Gunawan Kartapranata`,license:`CC BY-SA 4.0`}},"langkawi/Asam Pedas":{wiki:{title:`Asam pedas`,url:`https://en.wikipedia.org/wiki/Asam_pedas`,extract:`Asam pedas is a traditional sour and spicy gulai commonly found in Southeast Asia, particularly in Malaysia, Indonesia and Singapore. The dish is typically associated with Malay, Minangkabau, Acehnese and Peranakan cuisines, and is prepared using various types of seafood or freshwater fish.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/ASAM_PEDAS_IKAN_PARI.jpg/960px-ASAM_PEDAS_IKAN_PARI.jpg`,page:`https://commons.wikimedia.org/wiki/File:ASAM_PEDAS_IKAN_PARI.jpg`,artist:`Elly Suhailee`,license:`CC BY-SA 4.0`}},"langkawi/Roti Canai":{wiki:{title:`Roti canai`,url:`https://en.wikipedia.org/wiki/Roti_canai`,extract:`Roti canai, or roti prata, also known as roti chanai and roti cane, is an unleavened flatbread of Indian origin found in the cuisines of Southeast Asia, especially those of Brunei, Indonesia, Malaysia, Singapore, and Thailand.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/YosriRotiCanai.jpg/960px-YosriRotiCanai.jpg`,page:`https://commons.wikimedia.org/wiki/File:YosriRotiCanai.jpg`,artist:`Yosri at ms.wikipedia`,license:`GFDL`}},"langkawi/Satay":{wiki:{title:`Satay`,url:`https://en.wikipedia.org/wiki/Satay`,extract:`Satay or sate is a Southeast Asian dish consisting of small pieces of seasoned meat, seafood or vegetables skewered on sticks and grilled over charcoal. It is typically served with a sauce, most commonly peanut-based and accompanied by rice cakes, cucumber or pickled vegetables. Common ingredients include chicken, beef, goat, pork and seafood, while regional and vegetarian variations are also found.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Sate_Udang.JPG/960px-Sate_Udang.JPG`,page:`https://commons.wikimedia.org/wiki/File:Sate_Udang.JPG`,artist:`Gunawan Kartapranata`,license:`CC BY-SA 4.0`}},"dish:Hainanese chicken rice":{wiki:{title:`Hainanese chicken rice`,url:`https://en.wikipedia.org/wiki/Hainanese_chicken_rice`,extract:`Hainanese chicken rice is a dish of poached or roasted chicken with seasoned rice, served with chilli sauce and usually with cucumbers, tomato slices or cilantro garnishes. It was created by immigrants from Hainan in southern China and adapted from the Hainanese dishes of Wenchang chicken and Wenchang chicken rice.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Hainanese_Chicken_Rice.jpg/960px-Hainanese_Chicken_Rice.jpg`,page:`https://commons.wikimedia.org/wiki/File:Hainanese_Chicken_Rice.jpg`,artist:`No machine-readable author provided. Terence assumed (based on copyright claims).`,license:`CC BY 2.5`}},"dish:Satay celup":{wiki:{title:`Satay celup`,url:`https://en.wikipedia.org/wiki/Satay_celup`,extract:`Satay celup or sate celup is a Malaysian dish where an assortment of raw and semi-cooked seafood, meat and vegetables on skewers are dunked into a hot boiling pot of satay gravy.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/Kingtu_Restaurant.jpg/960px-Kingtu_Restaurant.jpg`,page:`https://commons.wikimedia.org/wiki/File:Kingtu_Restaurant.jpg`,artist:`Chongkian`,license:`CC BY-SA 4.0`}},"malacca/Chicken Rice Balls":{wiki:{title:`Hainanese chicken rice`,url:`https://en.wikipedia.org/wiki/Hainanese_chicken_rice`,extract:`Hainanese chicken rice is a dish of poached or roasted chicken with seasoned rice, served with chilli sauce and usually with cucumbers, tomato slices or cilantro garnishes. It was created by immigrants from Hainan in southern China and adapted from the Hainanese dishes of Wenchang chicken and Wenchang chicken rice.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Hainanese_Chicken_Rice.jpg/960px-Hainanese_Chicken_Rice.jpg`,page:`https://commons.wikimedia.org/wiki/File:Hainanese_Chicken_Rice.jpg`,artist:`No machine-readable author provided. Terence assumed (based on copyright claims).`,license:`CC BY 2.5`}},"malacca/Nyonya Laksa":{wiki:{title:`Laksa`,url:`https://en.wikipedia.org/wiki/Laksa`,extract:`Laksa is a spicy noodle dish popular in Southeast Asia. Laksa consists of various types of noodles, most commonly thick rice noodles, with toppings such as chicken, prawns or fish. Most variations of laksa are prepared with a rich and spicy coconut curry soup or a broth seasoned with a souring ingredient like tamarind or asam gelugur.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1c/Nyonya_Laksa.jpg/960px-Nyonya_Laksa.jpg`,page:`https://commons.wikimedia.org/wiki/File:Nyonya_Laksa.jpg`,artist:`Giddy98`,license:`CC BY-SA 4.0`}},"malacca/Asam Pedas":{wiki:{title:`Asam pedas`,url:`https://en.wikipedia.org/wiki/Asam_pedas`,extract:`Asam pedas is a traditional sour and spicy gulai commonly found in Southeast Asia, particularly in Malaysia, Indonesia and Singapore. The dish is typically associated with Malay, Minangkabau, Acehnese and Peranakan cuisines, and is prepared using various types of seafood or freshwater fish.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/ASAM_PEDAS_IKAN_PARI.jpg/960px-ASAM_PEDAS_IKAN_PARI.jpg`,page:`https://commons.wikimedia.org/wiki/File:ASAM_PEDAS_IKAN_PARI.jpg`,artist:`Elly Suhailee`,license:`CC BY-SA 4.0`}},"malacca/Satay Celup":{wiki:{title:`Satay celup`,url:`https://en.wikipedia.org/wiki/Satay_celup`,extract:`Satay celup or sate celup is a Malaysian dish where an assortment of raw and semi-cooked seafood, meat and vegetables on skewers are dunked into a hot boiling pot of satay gravy.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/Kingtu_Restaurant.jpg/960px-Kingtu_Restaurant.jpg`,page:`https://commons.wikimedia.org/wiki/File:Kingtu_Restaurant.jpg`,artist:`Chongkian`,license:`CC BY-SA 4.0`}},"malacca/Gula Melaka Cendol":{wiki:{title:`Cendol`,url:`https://en.wikipedia.org/wiki/Cendol`,extract:`Cendol, also known as lot chong, mont let saung, nom lut, lod song and bánh lọt, is a traditional Southeast Asian dessert characterised by soft, green, worm-like jelly strands made from rice flour or mung bean starch, coconut milk and palm sugar syrup, typically served over shaved ice. The jelly is flavoured with pandan and combined with a creamy coconut milk base and the caramel-like sweetness of palm sugar.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Kampung_Paya_Jaras_Tengah%2C_Selangor_20250112_111330.jpg/960px-Kampung_Paya_Jaras_Tengah%2C_Selangor_20250112_111330.jpg`,page:`https://commons.wikimedia.org/wiki/File:Kampung_Paya_Jaras_Tengah,_Selangor_20250112_111330.jpg`,artist:`Wiki Farazi`,license:`CC0`}},"malacca/Devil's Curry":{wiki:{title:`Devil's curry`,url:`https://en.wikipedia.org/wiki/Devil's_curry`,extract:`Devil's curry, also known as kari debal in Kristang, is a very spicy curry flavoured with candlenuts, galangal, mustard seed and vinegar from the Eurasian Kristang (Cristão) culinary tradition in Malacca, Malaysia, Indonesia and the Indo-Dutch diaspora. It was historically served one or two days after Christmas and on other special occasions.`}},"dish:Bak kut teh":{wiki:{title:`Bak kut teh`,url:`https://en.wikipedia.org/wiki/Bak_kut_teh`,extract:`Bak kut teh is a pork rib dish cooked in broth popularly served in Malaysia and Singapore where there is a predominant Hoklo and Teochew community.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/Song_Fa_Bak_Kut_Teh%2C_New_Bridge_Rd%2C_Singapore_%282023%29_06.jpg/960px-Song_Fa_Bak_Kut_Teh%2C_New_Bridge_Rd%2C_Singapore_%282023%29_06.jpg`,page:`https://commons.wikimedia.org/wiki/File:Song_Fa_Bak_Kut_Teh,_New_Bridge_Rd,_Singapore_(2023)_06.jpg`,artist:`Chainwit.`,license:`CC BY 4.0`}},"dish:Hokkien mee":{wiki:{title:`Hokkien mee`,url:`https://en.wikipedia.org/wiki/Hokkien_mee`,extract:`Hokkien mee, meaning "Fujian noodles" in Southern Min, is a group of related Southeast Asian dishes that have their origins in the cuisine of China's Fujian (Hokkien) province.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/Newton_HokkienMee.JPG/960px-Newton_HokkienMee.JPG`,page:`https://commons.wikimedia.org/wiki/File:Newton_HokkienMee.JPG`,artist:`Jpatokal`,license:`CC BY-SA 4.0`}},"dish:Satay":{wiki:{title:`Satay`,url:`https://en.wikipedia.org/wiki/Satay`,extract:`Satay or sate is a Southeast Asian dish consisting of small pieces of seasoned meat, seafood or vegetables skewered on sticks and grilled over charcoal. It is typically served with a sauce, most commonly peanut-based and accompanied by rice cakes, cucumber or pickled vegetables. Common ingredients include chicken, beef, goat, pork and seafood, while regional and vegetarian variations are also found.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Sate_Udang.JPG/960px-Sate_Udang.JPG`,page:`https://commons.wikimedia.org/wiki/File:Sate_Udang.JPG`,artist:`Gunawan Kartapranata`,license:`CC BY-SA 4.0`}},"dish:Char kway teow":{wiki:{title:`Char kway teow`,url:`https://en.wikipedia.org/wiki/Char_kway_teow`,extract:`Char kway teow is a stir-fried rice noodle dish from Maritime Southeast Asia. In Hokkien and Teochew, char means 'stir-fried' and kway teow refers to flat rice noodles. It is made from flat rice noodles or kway teow of approximately 1 cm in width, stir-fried over very high heat with garlic, light and dark soy sauce, chili paste, whole prawns, shelled blood cockles, chopped Chinese chives, slices of Chinese sausage,…`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/0/04/Char_kway_teow.jpg`,page:`https://commons.wikimedia.org/wiki/File:Char_kway_teow.jpg`,artist:`Elizetang`,license:`Public domain`}},"kuala-lumpur/Nasi Lemak":{wiki:{title:`Nasi lemak`,url:`https://en.wikipedia.org/wiki/Nasi_lemak`,extract:`Nasi lemak is a dish originating in Malay cuisine that consists of rice cooked in coconut milk and pandan leaf. It is commonly found in Malaysia, where it is considered the national dish. As it is common throughout the Malay world, it is also a native dish in neighbouring areas with significant ethnic Malay populations, such as Singapore and Southern Thailand.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/Nasi_Lemak_dengan_Chili_Nasi_Lemak_dan_Sotong_Pedas%2C_di_Penang_Summer_Restaurant.jpg/960px-Nasi_Lemak_dengan_Chili_Nasi_Lemak_dan_Sotong_Pedas%2C_di_Penang_Summer_Restaurant.jpg`,page:`https://commons.wikimedia.org/wiki/File:Nasi_Lemak_dengan_Chili_Nasi_Lemak_dan_Sotong_Pedas,_di_Penang_Summer_Restaurant.jpg`,artist:`Meandkancil2020`,license:`CC BY-SA 4.0`}},"kuala-lumpur/Roti Canai":{wiki:{title:`Roti canai`,url:`https://en.wikipedia.org/wiki/Roti_canai`,extract:`Roti canai, or roti prata, also known as roti chanai and roti cane, is an unleavened flatbread of Indian origin found in the cuisines of Southeast Asia, especially those of Brunei, Indonesia, Malaysia, Singapore, and Thailand.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/YosriRotiCanai.jpg/960px-YosriRotiCanai.jpg`,page:`https://commons.wikimedia.org/wiki/File:YosriRotiCanai.jpg`,artist:`Yosri at ms.wikipedia`,license:`GFDL`}},"kuala-lumpur/Bak Kut Teh":{wiki:{title:`Bak kut teh`,url:`https://en.wikipedia.org/wiki/Bak_kut_teh`,extract:`Bak kut teh is a pork rib dish cooked in broth popularly served in Malaysia and Singapore where there is a predominant Hoklo and Teochew community.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/Song_Fa_Bak_Kut_Teh%2C_New_Bridge_Rd%2C_Singapore_%282023%29_06.jpg/960px-Song_Fa_Bak_Kut_Teh%2C_New_Bridge_Rd%2C_Singapore_%282023%29_06.jpg`,page:`https://commons.wikimedia.org/wiki/File:Song_Fa_Bak_Kut_Teh,_New_Bridge_Rd,_Singapore_(2023)_06.jpg`,artist:`Chainwit.`,license:`CC BY 4.0`}},"kuala-lumpur/KL Hokkien Mee":{wiki:{title:`Hokkien mee`,url:`https://en.wikipedia.org/wiki/Hokkien_mee`,extract:`Hokkien mee, meaning "Fujian noodles" in Southern Min, is a group of related Southeast Asian dishes that have their origins in the cuisine of China's Fujian (Hokkien) province.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/Newton_HokkienMee.JPG/960px-Newton_HokkienMee.JPG`,page:`https://commons.wikimedia.org/wiki/File:Newton_HokkienMee.JPG`,artist:`Jpatokal`,license:`CC BY-SA 4.0`}},"kuala-lumpur/Satay":{wiki:{title:`Satay`,url:`https://en.wikipedia.org/wiki/Satay`,extract:`Satay or sate is a Southeast Asian dish consisting of small pieces of seasoned meat, seafood or vegetables skewered on sticks and grilled over charcoal. It is typically served with a sauce, most commonly peanut-based and accompanied by rice cakes, cucumber or pickled vegetables. Common ingredients include chicken, beef, goat, pork and seafood, while regional and vegetarian variations are also found.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Sate_Udang.JPG/960px-Sate_Udang.JPG`,page:`https://commons.wikimedia.org/wiki/File:Sate_Udang.JPG`,artist:`Gunawan Kartapranata`,license:`CC BY-SA 4.0`}},"dish:Ais kacang":{wiki:{title:`Ais kacang`,url:`https://en.wikipedia.org/wiki/Ais_kacang`,extract:`Ais kacang or air batu campur, Jawi: ‏اءير باتو چمڤور "mixed ice", often abbr. ABC) is a dessert common in Malaysia, Singapore and Brunei.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/38/Ais_kacang.jpg/960px-Ais_kacang.jpg`,page:`https://commons.wikimedia.org/wiki/File:Ais_kacang.jpg`,artist:`Andrew Bogott`,license:`CC BY-SA 3.0`}},"dish:Oyster omelette":{wiki:{title:`Oyster omelette`,url:`https://en.wikipedia.org/wiki/Oyster_omelette`,extract:`The oyster omelette or oyster cake, also known as o-a-tsian, o-chien or orh luak, is a dish of Southern Min origin that is renowned for its savory flavor in its native Minnan region and Chaoshan, along with Taiwan and many parts of Southeast Asia, such as Indonesia, Philippines, Thailand, Malaysia or Singapore, due to the influence of the Hokkien and Teochew diaspora.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/Billyfoodoysteromelette.jpg/960px-Billyfoodoysteromelette.jpg`,page:`https://commons.wikimedia.org/wiki/File:Billyfoodoysteromelette.jpg`,artist:`Archon6812`,license:`CC BY-SA 3.0`}},"penang/Penang Char Kway Teow":{wiki:{title:`Char kway teow`,url:`https://en.wikipedia.org/wiki/Char_kway_teow`,extract:`Char kway teow is a stir-fried rice noodle dish from Maritime Southeast Asia. In Hokkien and Teochew, char means 'stir-fried' and kway teow refers to flat rice noodles. It is made from flat rice noodles or kway teow of approximately 1 cm in width, stir-fried over very high heat with garlic, light and dark soy sauce, chili paste, whole prawns, shelled blood cockles, chopped Chinese chives, slices of Chinese sausage,…`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/0/04/Char_kway_teow.jpg`,page:`https://commons.wikimedia.org/wiki/File:Char_kway_teow.jpg`,artist:`Elizetang`,license:`Public domain`}},"penang/Penang Assam Laksa":{wiki:{title:`Laksa`,url:`https://en.wikipedia.org/wiki/Laksa`,extract:`Laksa is a spicy noodle dish popular in Southeast Asia. Laksa consists of various types of noodles, most commonly thick rice noodles, with toppings such as chicken, prawns or fish. Most variations of laksa are prepared with a rich and spicy coconut curry soup or a broth seasoned with a souring ingredient like tamarind or asam gelugur.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1c/Nyonya_Laksa.jpg/960px-Nyonya_Laksa.jpg`,page:`https://commons.wikimedia.org/wiki/File:Nyonya_Laksa.jpg`,artist:`Giddy98`,license:`CC BY-SA 4.0`}},"penang/Nasi Kandar":{wiki:{title:`Nasi kandar`,url:`https://en.wikipedia.org/wiki/Nasi_kandar`,extract:`Nasi kandar is a popular northern Malaysian dish from Penang, originally introduced by Tamil Muslim traders from India. The meal consists of steamed rice combined with an array of distinct curries, side dishes, and gravies. The selection of curries consists of various blends of vegetables, seafood or meat.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/A_plate_of_Nasi_Kandar.jpg/960px-A_plate_of_Nasi_Kandar.jpg`,page:`https://commons.wikimedia.org/wiki/File:A_plate_of_Nasi_Kandar.jpg`,artist:`Kutubkhanah`,license:`CC BY-SA 4.0`}},"penang/Penang Hokkien Mee":{wiki:{title:`Hokkien mee`,url:`https://en.wikipedia.org/wiki/Hokkien_mee`,extract:`Hokkien mee, meaning "Fujian noodles" in Southern Min, is a group of related Southeast Asian dishes that have their origins in the cuisine of China's Fujian (Hokkien) province.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/Newton_HokkienMee.JPG/960px-Newton_HokkienMee.JPG`,page:`https://commons.wikimedia.org/wiki/File:Newton_HokkienMee.JPG`,artist:`Jpatokal`,license:`CC BY-SA 4.0`}},"penang/Cendol":{wiki:{title:`Cendol`,url:`https://en.wikipedia.org/wiki/Cendol`,extract:`Cendol, also known as lot chong, mont let saung, nom lut, lod song and bánh lọt, is a traditional Southeast Asian dessert characterised by soft, green, worm-like jelly strands made from rice flour or mung bean starch, coconut milk and palm sugar syrup, typically served over shaved ice. The jelly is flavoured with pandan and combined with a creamy coconut milk base and the caramel-like sweetness of palm sugar.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Kampung_Paya_Jaras_Tengah%2C_Selangor_20250112_111330.jpg/960px-Kampung_Paya_Jaras_Tengah%2C_Selangor_20250112_111330.jpg`,page:`https://commons.wikimedia.org/wiki/File:Kampung_Paya_Jaras_Tengah,_Selangor_20250112_111330.jpg`,artist:`Wiki Farazi`,license:`CC0`}},"penang/Oyster Omelette":{wiki:{title:`Oyster omelette`,url:`https://en.wikipedia.org/wiki/Oyster_omelette`,extract:`The oyster omelette or oyster cake, also known as o-a-tsian, o-chien or orh luak, is a dish of Southern Min origin that is renowned for its savory flavor in its native Minnan region and Chaoshan, along with Taiwan and many parts of Southeast Asia, such as Indonesia, Philippines, Thailand, Malaysia or Singapore, due to the influence of the Hokkien and Teochew diaspora.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/Billyfoodoysteromelette.jpg/960px-Billyfoodoysteromelette.jpg`,page:`https://commons.wikimedia.org/wiki/File:Billyfoodoysteromelette.jpg`,artist:`Archon6812`,license:`CC BY-SA 3.0`}},"dish:Mantou":{wiki:{title:`Mantou`,url:`https://en.wikipedia.org/wiki/Mantou`,extract:`Mantou, often referred to as a Chinese steamed bun, is a white and soft type of steamed bread or bun popular in northern China. Folk etymology connects the name mantou to a tale about Zhuge Liang.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/5/5a/%E0%B9%82%E0%B8%95%E0%B9%8A%E0%B8%B0%E0%B8%88%E0%B8%B5%E0%B8%99%E0%B8%AB%E0%B8%A1%E0%B8%B1%E0%B9%88%E0%B8%99%E0%B9%82%E0%B8%96%E0%B8%A7.jpg`,page:`https://commons.wikimedia.org/wiki/File:%E0%B9%82%E0%B8%95%E0%B9%8A%E0%B8%B0%E0%B8%88%E0%B8%B5%E0%B8%99%E0%B8%AB%E0%B8%A1%E0%B8%B1%E0%B9%88%E0%B8%99%E0%B9%82%E0%B8%96%E0%B8%A7.jpg`,artist:`Aumrino970`,license:`CC BY-SA 4.0`}},"dish:Black pepper crab":{wiki:{title:`Black pepper crab`,url:`https://en.wikipedia.org/wiki/Black_pepper_crab`,extract:`Black pepper crab is one of the popular ways that crab is served in Singaporean cuisine. It is made by frying hard-shell crabs with black pepper. Unlike the other popular chilli crab dish, it is not cooked in a sauce and therefore has a dry consistency.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/Black_Peppered_Crab_%286895480431%29.jpg/960px-Black_Peppered_Crab_%286895480431%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Black_Peppered_Crab_(6895480431).jpg`,artist:`Bill Scott`,license:`CC BY 2.0`}},"dish:Masala dosa":{wiki:{title:`Masala dosa`,url:`https://en.wikipedia.org/wiki/Masala_dosa`,extract:`Masala dosa is a dish of South India, consisting of a savoury dosa crepe stuffed with a spiced potato stir fry. It is a popular breakfast item in South India, though it can be served at all times of the day and found in many other parts of the country and overseas.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/ba/Masala_Dosa_2023.jpg/960px-Masala_Dosa_2023.jpg`,page:`https://commons.wikimedia.org/wiki/File:Masala_Dosa_2023.jpg`,artist:`Yakshitha`,license:`CC BY-SA 4.0`}},"singapore/Hainanese Chicken Rice":{wiki:{title:`Hainanese chicken rice`,url:`https://en.wikipedia.org/wiki/Hainanese_chicken_rice`,extract:`Hainanese chicken rice is a dish of poached or roasted chicken with seasoned rice, served with chilli sauce and usually with cucumbers, tomato slices or cilantro garnishes. It was created by immigrants from Hainan in southern China and adapted from the Hainanese dishes of Wenchang chicken and Wenchang chicken rice.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Hainanese_Chicken_Rice.jpg/960px-Hainanese_Chicken_Rice.jpg`,page:`https://commons.wikimedia.org/wiki/File:Hainanese_Chicken_Rice.jpg`,artist:`No machine-readable author provided. Terence assumed (based on copyright claims).`,license:`CC BY 2.5`}},"singapore/Chilli Crab":{wiki:{title:`Chilli crab`,url:`https://en.wikipedia.org/wiki/Chilli_crab`,extract:`Chilli crab is a Southeast Asian seafood dish that is most popular in the cuisines of Malaysia and Singapore. The widely known version of chilli crab today could be traced back to the 1950s in Malaysia and Singapore. Mud crabs are commonly used and are stir-fried in a semi-thick, sweet, and savoury tomato-and-chilli-based sauce.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/c/c6/Chilli_crab-02.jpg`,page:`https://commons.wikimedia.org/wiki/File:Chilli_crab-02.jpg`,artist:`megawatts86`,license:`CC BY-SA 2.0`}},"singapore/Laksa":{wiki:{title:`Laksa`,url:`https://en.wikipedia.org/wiki/Laksa`,extract:`Laksa is a spicy noodle dish popular in Southeast Asia. Laksa consists of various types of noodles, most commonly thick rice noodles, with toppings such as chicken, prawns or fish. Most variations of laksa are prepared with a rich and spicy coconut curry soup or a broth seasoned with a souring ingredient like tamarind or asam gelugur.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1c/Nyonya_Laksa.jpg/960px-Nyonya_Laksa.jpg`,page:`https://commons.wikimedia.org/wiki/File:Nyonya_Laksa.jpg`,artist:`Giddy98`,license:`CC BY-SA 4.0`}},"singapore/Char Kway Teow":{wiki:{title:`Char kway teow`,url:`https://en.wikipedia.org/wiki/Char_kway_teow`,extract:`Char kway teow is a stir-fried rice noodle dish from Maritime Southeast Asia. In Hokkien and Teochew, char means 'stir-fried' and kway teow refers to flat rice noodles. It is made from flat rice noodles or kway teow of approximately 1 cm in width, stir-fried over very high heat with garlic, light and dark soy sauce, chili paste, whole prawns, shelled blood cockles, chopped Chinese chives, slices of Chinese sausage,…`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/0/04/Char_kway_teow.jpg`,page:`https://commons.wikimedia.org/wiki/File:Char_kway_teow.jpg`,artist:`Elizetang`,license:`Public domain`}},"singapore/Kaya Toast":{wiki:{title:`Kaya toast`,url:`https://en.wikipedia.org/wiki/Kaya_toast`,extract:`Kaya toast is a dish consisting of two slices of toast with butter and kaya, commonly served alongside kopi and soft-boiled eggs. The dish was believed to be created by Hainanese immigrants to the Straits Settlements in the 19th century while serving on British ships at the Port of Singapore.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Kaya_toast_on_a_plate.jpg/960px-Kaya_toast_on_a_plate.jpg`,page:`https://commons.wikimedia.org/wiki/File:Kaya_toast_on_a_plate.jpg`,artist:`Pinklily08`,license:`CC BY-SA 4.0`}},"singapore/Satay":{wiki:{title:`Satay`,url:`https://en.wikipedia.org/wiki/Satay`,extract:`Satay or sate is a Southeast Asian dish consisting of small pieces of seasoned meat, seafood or vegetables skewered on sticks and grilled over charcoal. It is typically served with a sauce, most commonly peanut-based and accompanied by rice cakes, cucumber or pickled vegetables. Common ingredients include chicken, beef, goat, pork and seafood, while regional and vegetarian variations are also found.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Sate_Udang.JPG/960px-Sate_Udang.JPG`,page:`https://commons.wikimedia.org/wiki/File:Sate_Udang.JPG`,artist:`Gunawan Kartapranata`,license:`CC BY-SA 4.0`}},"dish:Gogi-guksu":{wiki:{title:`Gogi-guksu`,url:`https://en.wikipedia.org/wiki/Gogi-guksu`,extract:`Gogi-guksu is a regional dish of Jeju Province, South Korea. It is a pork-based wheat noodle soup, served with sliced pork and garnishes like chives.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/Jeju_gogi_noodle.jpg/960px-Jeju_gogi_noodle.jpg`,page:`https://commons.wikimedia.org/wiki/File:Jeju_gogi_noodle.jpg`,artist:`Narnars0`,license:`CC BY-SA 3.0`}},"dish:Kimchi-jjigae":{wiki:{title:`Kimchi-jjigae`,url:`https://en.wikipedia.org/wiki/Kimchi-jjigae`,extract:`Kimchi-jjigae (Korean: 김치찌개) or kimchi stew is a jjigae, or stew-like Korean dish, made with kimchi and other ingredients, such as pork, scallions, onions, and diced tofu. It is one of the most common stews in Korean cuisine.`}},"jeju/Black pork BBQ":{wiki:{title:`Jeju Black pig`,url:`https://en.wikipedia.org/wiki/Jeju_Black_pig`,extract:`The Jeju Black is a Korean breed of domestic pig. It is named for and originates from Jeju Island, which lies to the south of the country in the Korea Strait. It is a small pig, with black skin and a smooth coat of hair. It has erect, unfolded ears, as well as a narrow snout.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/Jeju_Black_Pig.jpg/960px-Jeju_Black_Pig.jpg`,page:`https://commons.wikimedia.org/wiki/File:Jeju_Black_Pig.jpg`,artist:`A____ R__`,license:`CC BY-SA 2.0`}},"jeju/Gogi-guksu":{wiki:{title:`Gogi-guksu`,url:`https://en.wikipedia.org/wiki/Gogi-guksu`,extract:`Gogi-guksu is a regional dish of Jeju Province, South Korea. It is a pork-based wheat noodle soup, served with sliced pork and garnishes like chives.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/Jeju_gogi_noodle.jpg/960px-Jeju_gogi_noodle.jpg`,page:`https://commons.wikimedia.org/wiki/File:Jeju_gogi_noodle.jpg`,artist:`Narnars0`,license:`CC BY-SA 3.0`}},"jeju/Jeonbok-juk":{wiki:{title:`Juk (Korean food)`,url:`https://en.wikipedia.org/wiki/Juk_(Korean_food)`,extract:`Juk is a Korean porridge dish that is made by boiling rice or other grains or legumes, such as beans, sesame, nuts, and pumpkin. Juk is often eaten warm, especially as a morning meal, but can also be eaten at any time of the day.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/a/a8/Korean_abalone_porridge-Jeonbokjuk-02.jpg`,page:`https://commons.wikimedia.org/wiki/File:Korean_abalone_porridge-Jeonbokjuk-02.jpg`,artist:`by ~Nisa at Flickr`,license:`CC BY-SA 2.0`}},"jeju/Galchi-jorim":{wiki:{title:`Jorim`,url:`https://en.wikipedia.org/wiki/Jorim`,extract:`Jorim (Korean: 조림) is a category of dishes in Korean cuisine, made by simmering vegetables, meat, fish, seafood, or tofu in seasoned broth until the liquid is absorbed into the ingredients and reduced down. Jorim dishes are usually soy sauce-based, but gochujang or gochugaru can also be added, especially when fishier, red-fleshed fish such as mackerel, saury, or hairtail are used.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/d/da/Godeungeo-jorim.jpg`,page:`https://commons.wikimedia.org/wiki/File:Godeungeo-jorim.jpg`,artist:`쑤기언니`,license:`CC BY 4.0`}},"dish:Seolleongtang":{wiki:{title:`Seolleongtang`,url:`https://en.wikipedia.org/wiki/Seolleongtang`,extract:`Seolleongtang (Korean: 설렁탕) or ox bone soup is a Korean tang (soup) made from ox bones, brisket and other cuts. Seasoning is generally done at the table according to personal taste by adding salt, ground black pepper, red pepper, minced garlic, or chopped spring onions. It is a local dish of Seoul.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e5/Seolleongtang2024.jpg/960px-Seolleongtang2024.jpg`,page:`https://commons.wikimedia.org/wiki/File:Seolleongtang2024.jpg`,artist:`Kimhs5400`,license:`CC BY 4.0`}},"dish:Bindae-tteok":{wiki:{title:`Bindae-tteok`,url:`https://en.wikipedia.org/wiki/Bindae-tteok`,extract:`Bindae-tteok (Korean: 빈대떡), or mung bean pancake, is a type of buchimgae that originated in the Pyongan Province. It is made by grinding soaked mung beans, adding vegetables and meat and pan-frying it into a round, flat shape.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Korea_GwangjangMarket_Eats_11_Bindaetteok.jpg/960px-Korea_GwangjangMarket_Eats_11_Bindaetteok.jpg`,page:`https://commons.wikimedia.org/wiki/File:Korea_GwangjangMarket_Eats_11_Bindaetteok.jpg`,artist:`Korea.net / Korean Culture and Information Service`,license:`CC BY-SA 2.0`}},"dish:Makgeolli":{wiki:{title:`Makgeolli`,url:`https://en.wikipedia.org/wiki/Makgeolli`,extract:`Makgeolli, sometimes anglicized to makkoli, is a Korean alcoholic drink. It is a milky, off-white, and lightly sparkling rice wine that has a slight viscosity, and tastes slightly sweet, tangy, bitter, and astringent. Chalky sediment gives it a cloudy appearance. As a low proof drink of six to nine percent alcohol by volume, it is often considered a "communal beverage" rather than hard liquor.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/Makgeolli_2.jpg/960px-Makgeolli_2.jpg`,page:`https://commons.wikimedia.org/wiki/File:Makgeolli_2.jpg`,artist:`국립국어원`,license:`CC BY-SA 2.0 kr`}},"dish:Kalguksu":{wiki:{title:`Kal-guksu`,url:`https://en.wikipedia.org/wiki/Kal-guksu`,extract:`Kal-guksu is a Korean noodle dish consisting of handmade, knife-cut wheat flour noodles served in a large bowl with broth and other ingredients. It is traditionally considered a seasonal food, consumed most often in summer. Its name comes from the fact that the noodles are not extruded, pulled, or spun, but cut.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/8/87/Haemul-kal-guksu.jpg`,page:`https://commons.wikimedia.org/wiki/File:Haemul-kal-guksu.jpg`,artist:`행복한 초록개구리`,license:`CC BY 4.0`}},"dish:Mandu (food)":{wiki:{title:`Mandu (food)`,url:`https://en.wikipedia.org/wiki/Mandu_(food)`,extract:`Mandu (Korean: 만두), or mandoo, are dumplings in Korean cuisine. Mandu can be steamed, boiled, pan-fried, or deep-fried. The styles also vary across regions in the Korean Peninsula. Mandu were long part of Korean royal court cuisine, but are now found in supermarkets, restaurants, and snack places such as pojangmacha and bunsikjip throughout South Korea.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/%EB%A7%8C%EB%91%90.jpg/960px-%EB%A7%8C%EB%91%90.jpg`,page:`https://commons.wikimedia.org/wiki/File:%EB%A7%8C%EB%91%90.jpg`,artist:`Raven9722`,license:`CC0`}},"dish:Samgyetang":{wiki:{title:`Samgye-tang`,url:`https://en.wikipedia.org/wiki/Samgye-tang`,extract:`Samgye-tang (Korean: 삼계탕), or "ginseng chicken soup" is a tang that consists primarily of a whole young chicken (poussin) or quail filled with garlic, rice, jujube, mung bean, and ginseng. It is traditionally considered to be a health food. Samgye-tang is a representative summer health food.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Samgye-tang_2.jpg/960px-Samgye-tang_2.jpg`,page:`https://commons.wikimedia.org/wiki/File:Samgye-tang_2.jpg`,artist:`wizdata`,license:`CC0`}},"dish:Naengmyeon":{wiki:{title:`Naengmyeon`,url:`https://en.wikipedia.org/wiki/Naengmyeon`,extract:`Naengmyeon or raengmyŏn is a noodle dish of North Korean origin which consists of long and thin handmade noodles made from the flour and starch of various ingredients, including most commonly buckwheat but also potatoes, sweet potatoes, arrowroot starch, and kudzu. Other varieties of naengmyeon are made from ingredients such as seaweed and green tea.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/5/58/Naengmyeon_%28cold_noodles%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Naengmyeon_(cold_noodles).jpg`,artist:`wjlee4284`,license:`CC BY 2.5`}},"dish:Bulgogi":{wiki:{title:`Bulgogi`,url:`https://en.wikipedia.org/wiki/Bulgogi`,extract:`Bulgogi is a gui made of thin, marinated slices of meat, most commonly beef, grilled on a barbecue or on a stove-top griddle. It is also often stir-fried in a pan in home cooking. Sirloin and rib eye are frequently used cuts of beef for the dish. Bulgogi is a very popular dish in South Korea, where it can be found anywhere from upscale restaurants to local supermarkets as pan-ready kits.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ce/Bulgogi_2.jpg/960px-Bulgogi_2.jpg`,page:`https://commons.wikimedia.org/wiki/File:Bulgogi_2.jpg`,artist:`국립국어원`,license:`CC BY-SA 2.0 kr`}},"dish:Samgyeopsal":{wiki:{title:`Samgyeopsal`,url:`https://en.wikipedia.org/wiki/Samgyeopsal`,extract:`Samgyeopsal, samgyeopsal-gui, or grilled pork belly is a type of gui in Korean cuisine.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/Samgyeopsal-gui.jpg/960px-Samgyeopsal-gui.jpg`,page:`https://commons.wikimedia.org/wiki/File:Samgyeopsal-gui.jpg`,artist:`jinsoo jang`,license:`CC0`}},"dish:Tteokbokki":{wiki:{title:`Tteokbokki`,url:`https://en.wikipedia.org/wiki/Tteokbokki`,extract:`Tteokbokki , topokki or simmered rice cake, is a Korean food made from small-sized garae-tteok called tteokmyeon or commonly tteokbokki-tteok. It is often paired with eomuk, boiled eggs, and scallions, and seasoned with spicy gochujang. Less often, it is served in a non-spicy ganjang-based (soy) sauce, which is sometimes called gungjung-tteokbokki.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/Tteokbokki.JPG/960px-Tteokbokki.JPG`,page:`https://commons.wikimedia.org/wiki/File:Tteokbokki.JPG`,artist:`Popo le Chien`,license:`CC0`}},"seoul/Korean BBQ":{wiki:{title:`Samgyeopsal`,url:`https://en.wikipedia.org/wiki/Samgyeopsal`,extract:`Samgyeopsal, samgyeopsal-gui, or grilled pork belly is a type of gui in Korean cuisine.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/Samgyeopsal-gui.jpg/960px-Samgyeopsal-gui.jpg`,page:`https://commons.wikimedia.org/wiki/File:Samgyeopsal-gui.jpg`,artist:`jinsoo jang`,license:`CC0`}},"seoul/Bibimbap":{wiki:{title:`Bibimbap`,url:`https://en.wikipedia.org/wiki/Bibimbap`,extract:`Bibimbap, sometimes romanised as bi bim bap or bi bim bop, is a Korean rice dish. It is served as a bowl of warm white rice topped with namul and gochujang. Egg and sliced meat are common additions, stirred together thoroughly just before eating. The term bibim means "mixing" and bap is cooked rice.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/44/Dolsot-bibimbap.jpg/960px-Dolsot-bibimbap.jpg`,page:`https://commons.wikimedia.org/wiki/File:Dolsot-bibimbap.jpg`,artist:`Sous Chef`,license:`CC BY 2.0`}},"seoul/Tteokbokki":{wiki:{title:`Tteokbokki`,url:`https://en.wikipedia.org/wiki/Tteokbokki`,extract:`Tteokbokki , topokki or simmered rice cake, is a Korean food made from small-sized garae-tteok called tteokmyeon or commonly tteokbokki-tteok. It is often paired with eomuk, boiled eggs, and scallions, and seasoned with spicy gochujang. Less often, it is served in a non-spicy ganjang-based (soy) sauce, which is sometimes called gungjung-tteokbokki.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/Tteokbokki.JPG/960px-Tteokbokki.JPG`,page:`https://commons.wikimedia.org/wiki/File:Tteokbokki.JPG`,artist:`Popo le Chien`,license:`CC0`}},"seoul/Bindaetteok":{wiki:{title:`Bindae-tteok`,url:`https://en.wikipedia.org/wiki/Bindae-tteok`,extract:`Bindae-tteok (Korean: 빈대떡), or mung bean pancake, is a type of buchimgae that originated in the Pyongan Province. It is made by grinding soaked mung beans, adding vegetables and meat and pan-frying it into a round, flat shape.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Korea_GwangjangMarket_Eats_11_Bindaetteok.jpg/960px-Korea_GwangjangMarket_Eats_11_Bindaetteok.jpg`,page:`https://commons.wikimedia.org/wiki/File:Korea_GwangjangMarket_Eats_11_Bindaetteok.jpg`,artist:`Korea.net / Korean Culture and Information Service`,license:`CC BY-SA 2.0`}},"seoul/Korean fried chicken":{wiki:{title:`Korean fried chicken`,url:`https://en.wikipedia.org/wiki/Korean_fried_chicken`,extract:`Korean fried chicken, in Korean chikin, refers to a variety of fried chicken dishes created in South Korea. These include the basic huraideu-chicken and the spicy yangnyeom chicken. In South Korea, fried chicken is consumed as a meal, an appetizer, anju, or as an after-meal snack.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/Iksan_City_48_Korean_Style_Fried_chicken.jpg/960px-Iksan_City_48_Korean_Style_Fried_chicken.jpg`,page:`https://commons.wikimedia.org/wiki/File:Iksan_City_48_Korean_Style_Fried_chicken.jpg`,artist:`KOREA.NET`,license:`CC BY-SA 2.0`}},"seoul/Naengmyeon":{wiki:{title:`Naengmyeon`,url:`https://en.wikipedia.org/wiki/Naengmyeon`,extract:`Naengmyeon or raengmyŏn is a noodle dish of North Korean origin which consists of long and thin handmade noodles made from the flour and starch of various ingredients, including most commonly buckwheat but also potatoes, sweet potatoes, arrowroot starch, and kudzu. Other varieties of naengmyeon are made from ingredients such as seaweed and green tea.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/5/58/Naengmyeon_%28cold_noodles%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Naengmyeon_(cold_noodles).jpg`,artist:`wjlee4284`,license:`CC BY 2.5`}},"dish:Hoe (food)":{wiki:{title:`Hoe (food)`,url:`https://en.wikipedia.org/wiki/Hoe_(food)`,extract:`Hoe is a Korean delicacy that is eaten by trimming raw meat or raw fish. It is similar to Japanese sashimi. In addition to fish, it is also made with other marine products such as shrimp and squid, shellfish, raw meat of land animals, and vegetable ingredients, but without any special prefix, it mainly refers to raw fish.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/Hoe_%28raw_fish%29.jpg/960px-Hoe_%28raw_fish%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Hoe_(raw_fish).jpg`,artist:`littlepepper`,license:`CC0`}},"dish:Hotteok":{wiki:{title:`Hotteok`,url:`https://en.wikipedia.org/wiki/Hotteok`,extract:`Hotteok, sometimes called hoeddeok, is a type of filled pancake known as a popular street food in South Korea. It originated in Qing dynasty China and was first brought into Joseon Korea during the 19th century.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/Hotteok.jpg/960px-Hotteok.jpg`,page:`https://commons.wikimedia.org/wiki/File:Hotteok.jpg`,artist:`Korea.net / Korean Culture and Information Service`,license:`CC BY-SA 2.0`}},"dish:Fishcake":{wiki:{title:`Fishcake`,url:`https://en.wikipedia.org/wiki/Fishcake`,extract:`A fishcake is a culinary dish consisting of filleted fish or other seafood minced or ground, mixed with a starchy ingredient, and fried until golden. They can also frequently be oven-baked.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/Fish_cakes_food_dinner.jpg/960px-Fish_cakes_food_dinner.jpg`,page:`https://commons.wikimedia.org/wiki/File:Fish_cakes_food_dinner.jpg`,artist:`Jon Sullivan`,license:`Public domain`}},"dish:Milmyeon":{wiki:{title:`Milmyeon`,url:`https://en.wikipedia.org/wiki/Milmyeon`,extract:`Milmyeon is a noodle dish that originated in Busan, South Korea. Milmyeon is a variant of the northern Korean noodle dish naengmyeon. It consists of wheat noodles in a cold meat broth or a spicy sauce, and topped with vegetables and garnish.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/9/9c/Korean_cold_noodle_soup-Milmyeon-01.jpg`,page:`https://commons.wikimedia.org/wiki/File:Korean_cold_noodle_soup-Milmyeon-01.jpg`,artist:`by shizu k (shezzz) at Flickr`,license:`CC BY-SA 2.0`}},"dish:Dwaeji-gukbap":{wiki:{title:`Dwaeji-gukbap`,url:`https://en.wikipedia.org/wiki/Dwaeji-gukbap`,extract:`Dwaeji-gukbap (Korean: 돼지국밥) is a South Korean soup especially popular in Busan made with pork, soy sauce, miso, rice wine, sesame oil, and bone broth. The name literally translates to "pork, soup, rice". It is served with various side dishes like rice, salted shrimp, onion, noodle, kimchi, garlic, and green peppers, which all can be added to the soup.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/8/8b/Dwaeji-gukbap.jpg`,page:`https://commons.wikimedia.org/wiki/File:Dwaeji-gukbap.jpg`,artist:`http://blog.daum.net/wjlee4284 사이팔사]`,license:`CC BY 2.0 kr`}},"dish:Pajeon":{wiki:{title:`Pajeon`,url:`https://en.wikipedia.org/wiki/Pajeon`,extract:`Pajeon is a variety of jeon with scallion as its prominent ingredient, as pa (파) means 'scallion'. It is a Korean dish made from a batter of eggs, wheat flour, rice flour, scallions, and often other ingredients depending on the variety. Beef, pork, kimchi, shellfish, and other seafood are mostly used. If one of these ingredients, such as squid, dominates the jeon, the name will reflect that; e.g.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d3/Korean_pancake-Pajeon-05.jpg/960px-Korean_pancake-Pajeon-05.jpg`,page:`https://commons.wikimedia.org/wiki/File:Korean_pancake-Pajeon-05.jpg`,artist:`by Tales of an LA Addict (Abby) at Flickr`,license:`CC BY-SA 2.0`}},"busan/Dwaeji gukbap":{wiki:{title:`Dwaeji-gukbap`,url:`https://en.wikipedia.org/wiki/Dwaeji-gukbap`,extract:`Dwaeji-gukbap (Korean: 돼지국밥) is a South Korean soup especially popular in Busan made with pork, soy sauce, miso, rice wine, sesame oil, and bone broth. The name literally translates to "pork, soup, rice". It is served with various side dishes like rice, salted shrimp, onion, noodle, kimchi, garlic, and green peppers, which all can be added to the soup.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/8/8b/Dwaeji-gukbap.jpg`,page:`https://commons.wikimedia.org/wiki/File:Dwaeji-gukbap.jpg`,artist:`http://blog.daum.net/wjlee4284 사이팔사]`,license:`CC BY 2.0 kr`}},"busan/Milmyeon":{wiki:{title:`Milmyeon`,url:`https://en.wikipedia.org/wiki/Milmyeon`,extract:`Milmyeon is a noodle dish that originated in Busan, South Korea. Milmyeon is a variant of the northern Korean noodle dish naengmyeon. It consists of wheat noodles in a cold meat broth or a spicy sauce, and topped with vegetables and garnish.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/9/9c/Korean_cold_noodle_soup-Milmyeon-01.jpg`,page:`https://commons.wikimedia.org/wiki/File:Korean_cold_noodle_soup-Milmyeon-01.jpg`,artist:`by shizu k (shezzz) at Flickr`,license:`CC BY-SA 2.0`}},"busan/Eomuk":{wiki:{title:`Fishcake`,url:`https://en.wikipedia.org/wiki/Fishcake`,extract:`A fishcake is a culinary dish consisting of filleted fish or other seafood minced or ground, mixed with a starchy ingredient, and fried until golden. They can also frequently be oven-baked.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/Fish_cakes_food_dinner.jpg/960px-Fish_cakes_food_dinner.jpg`,page:`https://commons.wikimedia.org/wiki/File:Fish_cakes_food_dinner.jpg`,artist:`Jon Sullivan`,license:`Public domain`}},"busan/Ssiat hotteok":{wiki:{title:`Hotteok`,url:`https://en.wikipedia.org/wiki/Hotteok`,extract:`Hotteok, sometimes called hoeddeok, is a type of filled pancake known as a popular street food in South Korea. It originated in Qing dynasty China and was first brought into Joseon Korea during the 19th century.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/Hotteok.jpg/960px-Hotteok.jpg`,page:`https://commons.wikimedia.org/wiki/File:Hotteok.jpg`,artist:`Korea.net / Korean Culture and Information Service`,license:`CC BY-SA 2.0`}},"busan/Hoe":{wiki:{title:`Hoe (food)`,url:`https://en.wikipedia.org/wiki/Hoe_(food)`,extract:`Hoe is a Korean delicacy that is eaten by trimming raw meat or raw fish. It is similar to Japanese sashimi. In addition to fish, it is also made with other marine products such as shrimp and squid, shellfish, raw meat of land animals, and vegetable ingredients, but without any special prefix, it mainly refers to raw fish.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/Hoe_%28raw_fish%29.jpg/960px-Hoe_%28raw_fish%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Hoe_(raw_fish).jpg`,artist:`littlepepper`,license:`CC0`}},"busan/Dongnae pajeon":{wiki:{title:`Pajeon`,url:`https://en.wikipedia.org/wiki/Pajeon`,extract:`Pajeon is a variety of jeon with scallion as its prominent ingredient, as pa (파) means 'scallion'. It is a Korean dish made from a batter of eggs, wheat flour, rice flour, scallions, and often other ingredients depending on the variety. Beef, pork, kimchi, shellfish, and other seafood are mostly used. If one of these ingredients, such as squid, dominates the jeon, the name will reflect that; e.g.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d3/Korean_pancake-Pajeon-05.jpg/960px-Korean_pancake-Pajeon-05.jpg`,page:`https://commons.wikimedia.org/wiki/File:Korean_pancake-Pajeon-05.jpg`,artist:`by Tales of an LA Addict (Abby) at Flickr`,license:`CC BY-SA 2.0`}},"dish:Pringá":{wiki:{title:`Pringá`,url:`https://en.wikipedia.org/wiki/Pring%C3%A1`,extract:`Pringá is a Spanish dish popular in Andalusia, which consists of roast beef or pork, cured sausages such as chorizo and morcilla, and beef or pork fat slow-cooked for many hours until the meat falls apart easily. Pieces of crusty bread are used to pull away a little meat, sausage, and fat. It is a social dish eaten around the family dinner table.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/Pringa_pan.JPG/960px-Pringa_pan.JPG`,page:`https://commons.wikimedia.org/wiki/File:Pringa_pan.JPG`,artist:`Tirithel`,license:`CC BY-SA 4.0`}},"dish:Spanish omelette":{wiki:{title:`Spanish omelette`,url:`https://en.wikipedia.org/wiki/Spanish_omelette`,extract:`A Spanish omelette or Spanish tortilla is an omelette made with eggs and potatoes, often including onions. It is often served at room temperature as a tapa. It is one of the most popular dishes in Spanish cuisine.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/Tortilla_de_patata_-_San_Sebasti%C3%A1n.jpg/960px-Tortilla_de_patata_-_San_Sebasti%C3%A1n.jpg`,page:`https://commons.wikimedia.org/wiki/File:Tortilla_de_patata_-_San_Sebasti%C3%A1n.jpg`,artist:`Kent Wang`,license:`CC BY-SA 2.0`}},"dish:Churro":{wiki:{title:`Churro`,url:`https://en.wikipedia.org/wiki/Churro`,extract:`A churro is a type of fried dough from Spanish and Portuguese cuisine, made with choux pastry dough piped into hot oil with a piping bag and large closed star tip or similar shape. They are also found in Latin American cuisine, Philippine cuisine and in other areas that have received immigration from Spanish- and Portuguese-speaking countries, especially in France and the Southwestern United States.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/Chocolate_con_churros_%2827343655726%29.jpg/960px-Chocolate_con_churros_%2827343655726%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Chocolate_con_churros_(27343655726).jpg`,artist:`Joy`,license:`CC BY 2.0`}},"dish:Meringue":{wiki:{title:`Meringue`,url:`https://en.wikipedia.org/wiki/Meringue`,extract:`Meringue is a type of dessert or candy, traditionally made from whipped egg whites and sugar, and occasionally an acidic ingredient such as lemon, vinegar, or cream of tartar. A binding agent such as salt, flour, or gelatin may also be added to the eggs. The key to the formation of a good meringue is the formation of stiff peaks by denaturing the protein ovalbumin via mechanical shear.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Meringues_9027.jpg/960px-Meringues_9027.jpg`,page:`https://commons.wikimedia.org/wiki/File:Meringues_9027.jpg`,artist:`Mike Lehmann, Mike Switzerland 12:44, 27 January 2007 (UTC)`,license:`CC BY-SA 3.0`}},"dish:Flamenquín":{wiki:{title:`Flamenquín`,url:`https://en.wikipedia.org/wiki/Flamenqu%C3%ADn`,extract:`The flamenquín is a traditional dish from Cordoba (Andalusia) made with slices of jamón serrano wrapped in pieces of pork loin, coated breadcrumb batter, and deep-fried. It is often garnished with French fries and mayonnaise. A common variation replaces the loin with boiled ham. It can also be made with other fillings, such as fish, cheese, or poultry.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/Cordoba-3_%2848026709313%29.jpg/960px-Cordoba-3_%2848026709313%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Cordoba-3_(48026709313).jpg`,artist:`Ajay Suresh from New York, NY, USA`,license:`CC BY 2.0`}},"seville/Pringá sandwich":{wiki:{title:`Pringá`,url:`https://en.wikipedia.org/wiki/Pring%C3%A1`,extract:`Pringá is a Spanish dish popular in Andalusia, which consists of roast beef or pork, cured sausages such as chorizo and morcilla, and beef or pork fat slow-cooked for many hours until the meat falls apart easily. Pieces of crusty bread are used to pull away a little meat, sausage, and fat. It is a social dish eaten around the family dinner table.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/Pringa_pan.JPG/960px-Pringa_pan.JPG`,page:`https://commons.wikimedia.org/wiki/File:Pringa_pan.JPG`,artist:`Tirithel`,license:`CC BY-SA 4.0`}},"seville/Oxtail stew":{wiki:{title:`Oxtail`,url:`https://en.wikipedia.org/wiki/Oxtail`,extract:`Oxtail is the culinary name for the tail of cattle. While the word once meant only the tail of an ox, today it can also refer to the tails of other cattle. An oxtail typically weighs around 3.5 kilograms and is skinned and cut into shorter lengths for sale.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/94/Raw_oxtail-01.jpg/960px-Raw_oxtail-01.jpg`,page:`https://commons.wikimedia.org/wiki/File:Raw_oxtail-01.jpg`,artist:`FotoosVanRobin`,license:`CC BY-SA 2.0`}},"seville/Andalusian fried fish":{wiki:{title:`Pescado frito`,url:`https://en.wikipedia.org/wiki/Pescado_frito`,extract:`Pescado frito, also called pescaíto frito, is a traditional dish from the Southern coast of Spain, typically found in Andalusia, but also in Catalonia, Valencia, the Canary Islands and the Balearic Islands.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Frito_gaditano-_2009.jpg/960px-Frito_gaditano-_2009.jpg`,page:`https://commons.wikimedia.org/wiki/File:Frito_gaditano-_2009.jpg`,artist:`Tamorlan`,license:`CC BY 3.0`}},"seville/Salmorejo":{wiki:{title:`Salmorejo`,url:`https://en.wikipedia.org/wiki/Salmorejo`,extract:`Salmorejo, sometimes known as ardoria or ardorío, is a traditional soup originating from Córdoba, Andalusia, southern Spain, made of tomato, bread, extra virgin olive oil and garlic. The salmorejo is served cold and may be garnished with diced Spanish ibérico ham and diced hard-boiled eggs.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/Salmorejo_cordouan.JPG/960px-Salmorejo_cordouan.JPG`,page:`https://commons.wikimedia.org/wiki/File:Salmorejo_cordouan.JPG`,artist:`P.Lechien`,license:`CC0`}},"seville/Serranito":{wiki:{title:`Serranito`,url:`https://en.wikipedia.org/wiki/Serranito`,extract:`In Andalusian cuisine, a serranito is a kind of warm sandwich, popular in Seville. It is the Andalusian traditional version of fast food.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/Serranito_de_cerdo.JPG/960px-Serranito_de_cerdo.JPG`,page:`https://commons.wikimedia.org/wiki/File:Serranito_de_cerdo.JPG`,artist:`Miguelbremen`,license:`CC BY-SA 3.0`}},"dish:Jamón":{wiki:{title:`Jamón`,url:`https://en.wikipedia.org/wiki/Jam%C3%B3n`,extract:`Jamón is a type of dry-cured ham produced in Spain. It is one of the most globally recognised food items of Spanish cuisine. It is also regularly a component of tapas.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/b/bd/Despa%C3%B1a_jamon_carving.jpg`,page:`https://commons.wikimedia.org/wiki/File:Despa%C3%B1a_jamon_carving.jpg`,artist:`Juancarlos Casas Gutierrez`,license:`CC BY 2.0`}},"dish:Pa amb tomàquet":{wiki:{title:`Pa amb tomàquet`,url:`https://en.wikipedia.org/wiki/Pa_amb_tom%C3%A0quet`,extract:`Pa amb tomàquet, also known as pa amb tomata or pa amb tomaca, is a traditional food of Catalan, Balearic and, to a lesser extent, Valencian and Aragonese cuisine. Pa amb tomàquet is considered a staple of Catalonia's cuisine and Catalan national identity.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8a/Pa_amb_tomaquet.jpg/960px-Pa_amb_tomaquet.jpg`,page:`https://commons.wikimedia.org/wiki/File:Pa_amb_tomaquet.jpg`,artist:`Jennifer Woodard Maderazo`,license:`CC BY 2.0`}},"dish:Arròs negre":{wiki:{title:`Arròs negre`,url:`https://en.wikipedia.org/wiki/Arr%C3%B2s_negre`,extract:`Arròs negre or arrós negre is a Valencian and Catalan dish made with cuttlefish or squid and rice, somewhat similar to seafood paella. Some call it paella negra, although it is traditionally not called a paella even though it is prepared in a similar manner.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/14-08-04-barcelona-RalfR-41.jpg/960px-14-08-04-barcelona-RalfR-41.jpg`,page:`https://commons.wikimedia.org/wiki/File:14-08-04-barcelona-RalfR-41.jpg`,artist:`Ralf Roletschek`,license:`GFDL 1.2`}},"dish:Fideuà":{wiki:{title:`Fideuà`,url:`https://en.wikipedia.org/wiki/Fideu%C3%A0`,extract:`Fideuà is a seafood dish originally from the coast of Valencia that is similar to paella, and even more so to arròs a banda, but with pasta noodles instead of rice. Its main ingredients are pasta noodles, fish, and shellfish. It is seasoned mainly with lemon.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Fideua_-_xurde.jpg/960px-Fideua_-_xurde.jpg`,page:`https://commons.wikimedia.org/wiki/File:Fideua_-_xurde.jpg`,artist:`Jorge Díaz from Madrid, Spain`,license:`CC BY-SA 2.0`}},"dish:Crema catalana":{wiki:{title:`Crema catalana`,url:`https://en.wikipedia.org/wiki/Crema_catalana`,extract:`Crema catalana, or crema cremada, is a Catalan dessert consisting of a custard topped with a layer of caramelized sugar. It is "virtually identical" to the French crème brûlée. It is made from milk, egg yolks, and sugar. Some modern recipes add cornflour. It is typically flavored with lemon zest, cinnamon, or vanilla, and a crisp caramel crust is made by caramelizing sugar placed on top of the custard.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/Creme_catalane.jpg/960px-Creme_catalane.jpg`,page:`https://commons.wikimedia.org/wiki/File:Creme_catalane.jpg`,artist:`Popo le Chien`,license:`CC0`}},"dish:Croquette":{wiki:{title:`Croquette`,url:`https://en.wikipedia.org/wiki/Croquette`,extract:`A croquette is a deep-fried roll originating in French cuisine and most extended in Spanish cuisine consisting of a thick binder combined with a filling, which is then breaded. It is served as a side dish, a snack, or fast food worldwide.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/Croquetas_Caseras_%287068664101%29.jpg/960px-Croquetas_Caseras_%287068664101%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Croquetas_Caseras_(7068664101).jpg`,artist:`Jonathan Pincas from Leon, Spain`,license:`CC BY 2.0`}},"dish:Escalivada":{wiki:{title:`Escalivada`,url:`https://en.wikipedia.org/wiki/Escalivada`,extract:`Escalivada, also sometimes transcribed in French as 'escalibade' and in Spanish as escalibada, is a traditional dish from Roussillon, Catalonia, València, Murcia and Aragón of smoky grilled vegetables. It typically consists of roasted eggplant and bell peppers with olive oil and sometimes onion, tomato, minced garlic, and salt.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Escalivada.jpg/960px-Escalivada.jpg`,page:`https://commons.wikimedia.org/wiki/File:Escalivada.jpg`,artist:`Emi Yañez`,license:`CC BY 2.0`}},"barcelona/Bread with tomato":{wiki:{title:`Pa amb tomàquet`,url:`https://en.wikipedia.org/wiki/Pa_amb_tom%C3%A0quet`,extract:`Pa amb tomàquet, also known as pa amb tomata or pa amb tomaca, is a traditional food of Catalan, Balearic and, to a lesser extent, Valencian and Aragonese cuisine. Pa amb tomàquet is considered a staple of Catalonia's cuisine and Catalan national identity.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8a/Pa_amb_tomaquet.jpg/960px-Pa_amb_tomaquet.jpg`,page:`https://commons.wikimedia.org/wiki/File:Pa_amb_tomaquet.jpg`,artist:`Jennifer Woodard Maderazo`,license:`CC BY 2.0`}},"barcelona/Black rice":{wiki:{title:`Arròs negre`,url:`https://en.wikipedia.org/wiki/Arr%C3%B2s_negre`,extract:`Arròs negre or arrós negre is a Valencian and Catalan dish made with cuttlefish or squid and rice, somewhat similar to seafood paella. Some call it paella negra, although it is traditionally not called a paella even though it is prepared in a similar manner.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/14-08-04-barcelona-RalfR-41.jpg/960px-14-08-04-barcelona-RalfR-41.jpg`,page:`https://commons.wikimedia.org/wiki/File:14-08-04-barcelona-RalfR-41.jpg`,artist:`Ralf Roletschek`,license:`GFDL 1.2`}},"barcelona/Seafood noodle paella":{wiki:{title:`Fideuà`,url:`https://en.wikipedia.org/wiki/Fideu%C3%A0`,extract:`Fideuà is a seafood dish originally from the coast of Valencia that is similar to paella, and even more so to arròs a banda, but with pasta noodles instead of rice. Its main ingredients are pasta noodles, fish, and shellfish. It is seasoned mainly with lemon.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Fideua_-_xurde.jpg/960px-Fideua_-_xurde.jpg`,page:`https://commons.wikimedia.org/wiki/File:Fideua_-_xurde.jpg`,artist:`Jorge Díaz from Madrid, Spain`,license:`CC BY-SA 2.0`}},"barcelona/Catalan cream":{wiki:{title:`Crema catalana`,url:`https://en.wikipedia.org/wiki/Crema_catalana`,extract:`Crema catalana, or crema cremada, is a Catalan dessert consisting of a custard topped with a layer of caramelized sugar. It is "virtually identical" to the French crème brûlée. It is made from milk, egg yolks, and sugar. Some modern recipes add cornflour. It is typically flavored with lemon zest, cinnamon, or vanilla, and a crisp caramel crust is made by caramelizing sugar placed on top of the custard.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/Creme_catalane.jpg/960px-Creme_catalane.jpg`,page:`https://commons.wikimedia.org/wiki/File:Creme_catalane.jpg`,artist:`Popo le Chien`,license:`CC0`}},"barcelona/Grilled vegetables":{wiki:{title:`Escalivada`,url:`https://en.wikipedia.org/wiki/Escalivada`,extract:`Escalivada, also sometimes transcribed in French as 'escalibade' and in Spanish as escalibada, is a traditional dish from Roussillon, Catalonia, València, Murcia and Aragón of smoky grilled vegetables. It typically consists of roasted eggplant and bell peppers with olive oil and sometimes onion, tomato, minced garlic, and salt.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Escalivada.jpg/960px-Escalivada.jpg`,page:`https://commons.wikimedia.org/wiki/File:Escalivada.jpg`,artist:`Emi Yañez`,license:`CC BY 2.0`}},"dish:Vermouth":{wiki:{title:`Vermouth`,url:`https://en.wikipedia.org/wiki/Vermouth`,extract:`Vermouth is an Italian aromatized, fortified wine, flavored with various botanicals and sometimes colored, produced mainly in Italy, France and Spain. The modern versions of the beverage were first produced in the mid- to late 18th century in Turin, Italy.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f3/Four_bottles_of_vermouth.jpg/960px-Four_bottles_of_vermouth.jpg`,page:`https://commons.wikimedia.org/wiki/File:Four_bottles_of_vermouth.jpg`,artist:`Kenneth C. Zirkel`,license:`CC BY-SA 4.0`}},"dish:Jamón ibérico":{wiki:{title:`Jamón ibérico`,url:`https://en.wikipedia.org/wiki/Jam%C3%B3n_ib%C3%A9rico`,extract:`Jamón ibérico, known in Portuguese as presunto ibérico, is a variety of jamón or presunto, a type of cured leg of pork produced in Spain and Portugal, in the Iberian Peninsula. It is considered a staple of both Portuguese cuisine and Spanish cuisine.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/Jamon_iberico_de_bellota_2_%28cinco_jotas%29.jpg/960px-Jamon_iberico_de_bellota_2_%28cinco_jotas%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Jamon_iberico_de_bellota_2_(cinco_jotas).jpg`,artist:`Cantabrucu`,license:`CC0`}},"dish:Huevos rotos":{wiki:{title:`Huevos rotos`,url:`https://en.wikipedia.org/wiki/Huevos_rotos`,extract:`Huevos rotos or huevos estrellados is any of a number of Spanish dishes involving eggs fried in a large amount of olive oil or any other oil. In Madrid, huevos estrellados is a dish based on a pan-fried egg with a liquid yolk, accompanied by French fries, some kind of meat. The dish is served hot, immediately after plating.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/Detalle-Huevos_Rotos.JPG/960px-Detalle-Huevos_Rotos.JPG`,page:`https://commons.wikimedia.org/wiki/File:Detalle-Huevos_Rotos.JPG`,artist:`Tamorlan`,license:`CC BY 3.0`}},"dish:Cocido madrileño":{wiki:{title:`Cocido madrileño`,url:`https://en.wikipedia.org/wiki/Cocido_madrile%C3%B1o`,extract:`Cocido madrileño is a traditional chickpea-based stew associated with the Madrid region. It is most popular during the winter. Long-cooking cocidos are thought to be derived from Sephardic adafina recipes.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/39/CocidoMadrile%C3%B1o.jpg/960px-CocidoMadrile%C3%B1o.jpg`,page:`https://commons.wikimedia.org/wiki/File:CocidoMadrile%C3%B1o.jpg`,artist:`Tnarik`,license:`CC BY-SA 2.0`}},"dish:Patatas bravas":{wiki:{title:`Patatas bravas`,url:`https://en.wikipedia.org/wiki/Patatas_bravas`,extract:`Patatas bravas, also called patatas a la brava or tortilla, all meaning "spicy potatoes") is a dish native to Spain. It typically consists of whitees tortilla that have been cut into two-centimeter-wide cubes, then fried in oil and served hot with a spicy "brava" sauce.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/Patatas_bravas_madrid.jpg/960px-Patatas_bravas_madrid.jpg`,page:`https://commons.wikimedia.org/wiki/File:Patatas_bravas_madrid.jpg`,artist:`Krista`,license:`CC BY 2.0`}},"madrid/Madrid chickpea stew":{wiki:{title:`Cocido madrileño`,url:`https://en.wikipedia.org/wiki/Cocido_madrile%C3%B1o`,extract:`Cocido madrileño is a traditional chickpea-based stew associated with the Madrid region. It is most popular during the winter. Long-cooking cocidos are thought to be derived from Sephardic adafina recipes.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/39/CocidoMadrile%C3%B1o.jpg/960px-CocidoMadrile%C3%B1o.jpg`,page:`https://commons.wikimedia.org/wiki/File:CocidoMadrile%C3%B1o.jpg`,artist:`Tnarik`,license:`CC BY-SA 2.0`}},"madrid/Fried squid sandwich":{wiki:{title:`Squid sandwich`,url:`https://en.wikipedia.org/wiki/Squid_sandwich`,extract:`Squid sandwich or bocadillo de calamares in Spanish, bocata calamares in Cheli, is a culinary specialty very common in Spain consisting of a bocadillo sandwich of squid battered in flour and fried in oil that is usually olive, or the more sophisticated version that is all of the above plus a spicy tomato sauce and mayonnaise with garlic similar to that of patatas bravas. It is usually served hot and freshly made.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/BocadilloCalamaresAtocha.JPG/960px-BocadilloCalamaresAtocha.JPG`,page:`https://commons.wikimedia.org/wiki/File:BocadilloCalamaresAtocha.JPG`,artist:`Tamorlan`,license:`CC BY-SA 3.0`}},"madrid/Churros with chocolate":{wiki:{title:`Churro`,url:`https://en.wikipedia.org/wiki/Churro`,extract:`A churro is a type of fried dough from Spanish and Portuguese cuisine, made with choux pastry dough piped into hot oil with a piping bag and large closed star tip or similar shape. They are also found in Latin American cuisine, Philippine cuisine and in other areas that have received immigration from Spanish- and Portuguese-speaking countries, especially in France and the Southwestern United States.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/Chocolate_con_churros_%2827343655726%29.jpg/960px-Chocolate_con_churros_%2827343655726%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Chocolate_con_churros_(27343655726).jpg`,artist:`Joy`,license:`CC BY 2.0`}},"madrid/Broken eggs":{wiki:{title:`Huevos rotos`,url:`https://en.wikipedia.org/wiki/Huevos_rotos`,extract:`Huevos rotos or huevos estrellados is any of a number of Spanish dishes involving eggs fried in a large amount of olive oil or any other oil. In Madrid, huevos estrellados is a dish based on a pan-fried egg with a liquid yolk, accompanied by French fries, some kind of meat. The dish is served hot, immediately after plating.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/Detalle-Huevos_Rotos.JPG/960px-Detalle-Huevos_Rotos.JPG`,page:`https://commons.wikimedia.org/wiki/File:Detalle-Huevos_Rotos.JPG`,artist:`Tamorlan`,license:`CC BY 3.0`}},"madrid/Spicy potatoes":{wiki:{title:`Patatas bravas`,url:`https://en.wikipedia.org/wiki/Patatas_bravas`,extract:`Patatas bravas, also called patatas a la brava or tortilla, all meaning "spicy potatoes") is a dish native to Spain. It typically consists of whitees tortilla that have been cut into two-centimeter-wide cubes, then fried in oil and served hot with a spicy "brava" sauce.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/Patatas_bravas_madrid.jpg/960px-Patatas_bravas_madrid.jpg`,page:`https://commons.wikimedia.org/wiki/File:Patatas_bravas_madrid.jpg`,artist:`Krista`,license:`CC BY 2.0`}},"madrid/Madrid-style tripe":{wiki:{title:`Callos`,url:`https://en.wikipedia.org/wiki/Callos`,extract:`Callos is a stew common across Spain, and is considered traditional to Madrid. It is also traditional dish in the Philippines, usually cooked during special occasions, with a slight variations in ingredients such as adding potatoes, and carrots in the stew. In Madrid, it is referred to as callos a la madrileña.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/Callos_cociendose.jpg/960px-Callos_cociendose.jpg`,page:`https://commons.wikimedia.org/wiki/File:Callos_cociendose.jpg`,artist:`Javier Lastras from España/Spain`,license:`CC BY 2.0`}},"dish:Ló͘-bah-pn̄g":{wiki:{title:`Ló͘-bah-pn̄g`,url:`https://en.wikipedia.org/wiki/L%C3%B3%CD%98-bah-pn%CC%84g`,extract:`Ló͘-bah-pn̄g, also called bah-sò-pn̄g or Lou-rou-fan in southern Taiwan, or translated to minced pork rice in English, is a rice dish that is commonly seen throughout Taiwan and Southern Fujian, China. The flavor may vary from one region to another, but the basic ingredients remain the same: lu rou pork marinated and boiled in soy sauce served on top of steamed rice. It is a type of gaifan dish.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/Lurou_fan%28Taiwanese_cuisine%29.jpg/960px-Lurou_fan%28Taiwanese_cuisine%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Lurou_fan(Taiwanese_cuisine).jpg`,artist:`Jzest`,license:`CC BY-SA 2.5`}},"dish:Milkfish congee":{wiki:{title:`Milkfish congee`,url:`https://en.wikipedia.org/wiki/Milkfish_congee`,extract:`Milkfish congee is a Taiwanese breakfast dish consisting of a congee with milkfish belly. The dish is typically served with pepper and chopped spring onions and is often eaten at breakfast. Originating from Tainan, the dish is considered one of the national dishes of Taiwan. Recently, the dish is starting to gain popularity in the United States.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/0/06/Milkfish_Congee_%E8%99%B1%E7%9B%AE%E9%AD%9A%E7%B2%A5.jpg/960px-Milkfish_Congee_%E8%99%B1%E7%9B%AE%E9%AD%9A%E7%B2%A5.jpg`,page:`https://commons.wikimedia.org/wiki/File:Milkfish_Congee_%E8%99%B1%E7%9B%AE%E9%AD%9A%E7%B2%A5.jpg`,artist:`姜 明雄`,license:`CC0`}},"dish:Youtiao":{wiki:{title:`Youtiao`,url:`https://en.wikipedia.org/wiki/Youtiao`,extract:`Youtiao, known in Southern China as yau char kway, is a long golden-brown deep-fried strip of wheat flour dough of Chinese origin and also popular in other East and Southeast Asian cuisines.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/78/Youtiao.jpg/960px-Youtiao.jpg`,page:`https://commons.wikimedia.org/wiki/File:Youtiao.jpg`,artist:`Popo le Chien`,license:`CC0`}},"dish:Tàⁿ-á-mī":{wiki:{title:`Tàⁿ-á-mī`,url:`https://en.wikipedia.org/wiki/T%C3%A0%E2%81%BF-%C3%A1-m%C4%AB`,extract:`Tàⁿ-á-mī, also known as ta-a noodles or danzai noodles, are a type of snack found in Tainan, Taiwan. Also known as "slack season ta-a noodles", they originated in Tainan about 130 years ago. While the general recipe is well known, some of the spices and the proportions of the various ingredients are closely guarded secrets by the different restaurants and stands that serve it.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8e/Du_Hsiao_Yueh%27s_Tan_Tsu_Mien_in_ECmall_%2820160514183239%29.jpg/960px-Du_Hsiao_Yueh%27s_Tan_Tsu_Mien_in_ECmall_%2820160514183239%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Du_Hsiao_Yueh%27s_Tan_Tsu_Mien_in_ECmall_(20160514183239).jpg`,artist:`N509FZ`,license:`CC BY-SA 4.0`}},"dish:Bottarga":{wiki:{title:`Bottarga`,url:`https://en.wikipedia.org/wiki/Bottarga`,extract:`Bottarga is salted, cured fish roe pouch, typically of the grey mullet or the bluefin tuna. It is a feature of Italian cuisine; forms of the dish from other parts of the world include Taiwanese wūyú zǐ, which is softer, and Korean eoran, from mullet or freshwater drum. It has many names and is prepared in various ways. Due to its scarcity and involved preparation it is expensive and regarded as a delicacy.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Bottarga_from_Preveza_Greece.jpg/960px-Bottarga_from_Preveza_Greece.jpg`,page:`https://commons.wikimedia.org/wiki/File:Bottarga_from_Preveza_Greece.jpg`,artist:`Φωτογραφία: Χαράλαμπος Γκούβας (Harry Gouvas) el:User:Harrygouvas`,license:`CC BY-SA 3.0`}},"tainan/Danzai noodles":{wiki:{title:`Tàⁿ-á-mī`,url:`https://en.wikipedia.org/wiki/T%C3%A0%E2%81%BF-%C3%A1-m%C4%AB`,extract:`Tàⁿ-á-mī, also known as ta-a noodles or danzai noodles, are a type of snack found in Tainan, Taiwan. Also known as "slack season ta-a noodles", they originated in Tainan about 130 years ago. While the general recipe is well known, some of the spices and the proportions of the various ingredients are closely guarded secrets by the different restaurants and stands that serve it.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8e/Du_Hsiao_Yueh%27s_Tan_Tsu_Mien_in_ECmall_%2820160514183239%29.jpg/960px-Du_Hsiao_Yueh%27s_Tan_Tsu_Mien_in_ECmall_%2820160514183239%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Du_Hsiao_Yueh%27s_Tan_Tsu_Mien_in_ECmall_(20160514183239).jpg`,artist:`N509FZ`,license:`CC BY-SA 4.0`}},"tainan/Milkfish congee":{wiki:{title:`Milkfish congee`,url:`https://en.wikipedia.org/wiki/Milkfish_congee`,extract:`Milkfish congee is a Taiwanese breakfast dish consisting of a congee with milkfish belly. The dish is typically served with pepper and chopped spring onions and is often eaten at breakfast. Originating from Tainan, the dish is considered one of the national dishes of Taiwan. Recently, the dish is starting to gain popularity in the United States.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/0/06/Milkfish_Congee_%E8%99%B1%E7%9B%AE%E9%AD%9A%E7%B2%A5.jpg/960px-Milkfish_Congee_%E8%99%B1%E7%9B%AE%E9%AD%9A%E7%B2%A5.jpg`,page:`https://commons.wikimedia.org/wiki/File:Milkfish_Congee_%E8%99%B1%E7%9B%AE%E9%AD%9A%E7%B2%A5.jpg`,artist:`姜 明雄`,license:`CC0`}},"tainan/Coffin bread":{wiki:{title:`Coffin bread`,url:`https://en.wikipedia.org/wiki/Coffin_bread`,extract:`Coffin bread, also known as coffin lid or coffin board, is a Taiwanese bread bowl which originated in Tainan.`}},"dish:Soy milk":{wiki:{title:`Soy milk`,url:`https://en.wikipedia.org/wiki/Soy_milk`,extract:`Soy milk, also known as soya milk, is a plant-based milk produced by soaking and grinding soybeans, boiling the mixture, and filtering out remaining particulates. It is a stable emulsion of oil, water, and protein. Its original form is an intermediate product of the manufacture of tofu.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/004-soymilk.jpg/960px-004-soymilk.jpg`,page:`https://commons.wikimedia.org/wiki/File:004-soymilk.jpg`,artist:`Kjokkenutstyr`,license:`CC BY-SA 2.0`}},"dish:Shaobing":{wiki:{title:`Shaobing`,url:`https://en.wikipedia.org/wiki/Shaobing`,extract:`Shaobing, also called huoshao, is a type of baked, unleavened, layered flatbread in northern Chinese cuisine. Shaobing can be made with or without stuffing, and with or without sesame on top. Shaobing contains a variety of stuffings that can be grouped into two main flavors: savory or sweet.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/2/2b/Shaobing5.jpg`,page:`https://commons.wikimedia.org/wiki/File:Shaobing5.jpg`,artist:`C C`,license:`CC BY 2.0`}},"dish:Beef noodle soup":{wiki:{title:`Beef noodle soup`,url:`https://en.wikipedia.org/wiki/Beef_noodle_soup`,extract:`Beef noodle soup is a noodle soup made of stewed or braised beef, beef broth, vegetables and noodles.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9e/Lanzhou_La_Mian.jpg/960px-Lanzhou_La_Mian.jpg`,page:`https://commons.wikimedia.org/wiki/File:Lanzhou_La_Mian.jpg`,artist:`MDRX`,license:`CC BY-SA 4.0`}},"dish:Xiaolongbao":{wiki:{title:`Xiaolongbao`,url:`https://en.wikipedia.org/wiki/Xiaolongbao`,extract:`Xiaolongbao is a type of Chinese tangbao, traditionally prepared in a xiaolong, a small bamboo steaming basket. Xiaolongbao is generally believed to have originated in Shanghai.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3a/A_Xiaolongbao_from_The_Modern_Shanghai.jpg/960px-A_Xiaolongbao_from_The_Modern_Shanghai.jpg`,page:`https://commons.wikimedia.org/wiki/File:A_Xiaolongbao_from_The_Modern_Shanghai.jpg`,artist:`Peachyeung316`,license:`CC BY-SA 4.0`}},"dish:Mango shaved ice":{wiki:{title:`Mango shaved ice`,url:`https://en.wikipedia.org/wiki/Mango_shaved_ice`,extract:`Mango shaved ice is a popular dessert in Taiwan, especially enjoyed during the hot summer months. Distinct from traditional shaved ice which typically includes toppings such as tapioca pearls, taro balls, and grass jelly, mango shaved ice features fresh mango chunks, condensed milk, and mango ice cream atop shaved or finely crushed ice.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Taipei_mangguobing.JPG/960px-Taipei_mangguobing.JPG`,page:`https://commons.wikimedia.org/wiki/File:Taipei_mangguobing.JPG`,artist:`(WT-en) SuperMidget at English Wikivoyage`,license:`Public domain`}},"dish:Donburi":{wiki:{title:`Donburi`,url:`https://en.wikipedia.org/wiki/Donburi`,extract:`Donburi is a Japanese "rice-bowl dish" consisting of fish, meat, vegetables or other ingredients simmered together and served over rice. Donburi meals are usually served in oversized rice bowls which are also called donburi. If one needs to distinguish, the bowl is called donburi-bachi and the food is called donburi-mono .`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/0/04/Gyudon_by_jetalone_in_Higashi-Ginza%2C_Tokyo.jpg`,page:`https://commons.wikimedia.org/wiki/File:Gyudon_by_jetalone_in_Higashi-Ginza,_Tokyo.jpg`,artist:`jetalone from Higashi-Ginza, Tokyo`,license:`CC BY 2.0`}},"taipei/Beef noodle soup":{wiki:{title:`Beef noodle soup`,url:`https://en.wikipedia.org/wiki/Beef_noodle_soup`,extract:`Beef noodle soup is a noodle soup made of stewed or braised beef, beef broth, vegetables and noodles.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9e/Lanzhou_La_Mian.jpg/960px-Lanzhou_La_Mian.jpg`,page:`https://commons.wikimedia.org/wiki/File:Lanzhou_La_Mian.jpg`,artist:`MDRX`,license:`CC BY-SA 4.0`}},"taipei/Xiaolongbao":{wiki:{title:`Xiaolongbao`,url:`https://en.wikipedia.org/wiki/Xiaolongbao`,extract:`Xiaolongbao is a type of Chinese tangbao, traditionally prepared in a xiaolong, a small bamboo steaming basket. Xiaolongbao is generally believed to have originated in Shanghai.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3a/A_Xiaolongbao_from_The_Modern_Shanghai.jpg/960px-A_Xiaolongbao_from_The_Modern_Shanghai.jpg`,page:`https://commons.wikimedia.org/wiki/File:A_Xiaolongbao_from_The_Modern_Shanghai.jpg`,artist:`Peachyeung316`,license:`CC BY-SA 4.0`}},"taipei/Braised pork rice":{wiki:{title:`Ló͘-bah-pn̄g`,url:`https://en.wikipedia.org/wiki/L%C3%B3%CD%98-bah-pn%CC%84g`,extract:`Ló͘-bah-pn̄g, also called bah-sò-pn̄g or Lou-rou-fan in southern Taiwan, or translated to minced pork rice in English, is a rice dish that is commonly seen throughout Taiwan and Southern Fujian, China. The flavor may vary from one region to another, but the basic ingredients remain the same: lu rou pork marinated and boiled in soy sauce served on top of steamed rice. It is a type of gaifan dish.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/Lurou_fan%28Taiwanese_cuisine%29.jpg/960px-Lurou_fan%28Taiwanese_cuisine%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Lurou_fan(Taiwanese_cuisine).jpg`,artist:`Jzest`,license:`CC BY-SA 2.5`}},"taipei/Oyster omelette":{wiki:{title:`Oyster omelette`,url:`https://en.wikipedia.org/wiki/Oyster_omelette`,extract:`The oyster omelette or oyster cake, also known as o-a-tsian, o-chien or orh luak, is a dish of Southern Min origin that is renowned for its savory flavor in its native Minnan region and Chaoshan, along with Taiwan and many parts of Southeast Asia, such as Indonesia, Philippines, Thailand, Malaysia or Singapore, due to the influence of the Hokkien and Teochew diaspora.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/Billyfoodoysteromelette.jpg/960px-Billyfoodoysteromelette.jpg`,page:`https://commons.wikimedia.org/wiki/File:Billyfoodoysteromelette.jpg`,artist:`Archon6812`,license:`CC BY-SA 3.0`}},"taipei/Bubble tea":{wiki:{title:`Bubble tea`,url:`https://en.wikipedia.org/wiki/Bubble_tea`,extract:`Bubble tea is a tea-based drink most often containing chewy tapioca balls, milk, and flavoring. It originated in Taiwan in the 1980s and spread to other countries where there is a large East Asian diaspora population.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/a/a2/Bubble_Tea.png`,page:`https://commons.wikimedia.org/wiki/File:Bubble_Tea.png`,artist:`Howief`,license:`CC BY-SA 3.0`}},"taipei/Mango shaved ice":{wiki:{title:`Mango shaved ice`,url:`https://en.wikipedia.org/wiki/Mango_shaved_ice`,extract:`Mango shaved ice is a popular dessert in Taiwan, especially enjoyed during the hot summer months. Distinct from traditional shaved ice which typically includes toppings such as tapioca pearls, taro balls, and grass jelly, mango shaved ice features fresh mango chunks, condensed milk, and mango ice cream atop shaved or finely crushed ice.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Taipei_mangguobing.JPG/960px-Taipei_mangguobing.JPG`,page:`https://commons.wikimedia.org/wiki/File:Taipei_mangguobing.JPG`,artist:`(WT-en) SuperMidget at English Wikivoyage`,license:`Public domain`}},"dish:Khanom chin":{wiki:{title:`Khanom chin`,url:`https://en.wikipedia.org/wiki/Khanom_chin`,extract:`Khanom chin or khanom jeen are fresh, thin white rice noodles in Thai cuisine which are made from rice fermented for three days, boiled, and extruded through into boiling water through a sieve. Khanom chin is served with stocks including coconut milk, fish curry, and chilli.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d9/Khanom_Chin_-_Thai_rice_noodles.JPG/960px-Khanom_Chin_-_Thai_rice_noodles.JPG`,page:`https://commons.wikimedia.org/wiki/File:Khanom_Chin_-_Thai_rice_noodles.JPG`,artist:`User:Mattes`,license:`Public domain`}},"dish:Pad thai":{wiki:{title:`Pad thai`,url:`https://en.wikipedia.org/wiki/Pad_thai`,extract:`Pad thai is a stir-fried rice noodle dish commonly served as a street food in Thailand as part of Thai cuisine. It is typically made with rice noodles, shrimp, peanuts, green onions, scrambled egg, sugar and bean sprouts. The ingredients are fried in a wok.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/39/Phat_Thai_kung_Chang_Khien_street_stall.jpg/960px-Phat_Thai_kung_Chang_Khien_street_stall.jpg`,page:`https://commons.wikimedia.org/wiki/File:Phat_Thai_kung_Chang_Khien_street_stall.jpg`,artist:`Takeaway`,license:`CC BY-SA 3.0`}},"dish:Green papaya salad":{wiki:{title:`Green papaya salad`,url:`https://en.wikipedia.org/wiki/Green_papaya_salad`,extract:`Green papaya salad is a spicy salad made from shredded unripe papaya. It is believed to have been created by Lao people and is considered one of the national dishes of Laos.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/2013_Tam_Lao.jpg/960px-2013_Tam_Lao.jpg`,page:`https://commons.wikimedia.org/wiki/File:2013_Tam_Lao.jpg`,artist:`Takeaway`,license:`CC BY-SA 3.0`}},"dish:Massaman curry":{wiki:{title:`Massaman curry`,url:`https://en.wikipedia.org/wiki/Massaman_curry`,extract:`Massaman curry is a rich, flavourful, and mildly spicy Thai curry. It is a fusion dish, combining foreign ingredients from three regions — Persia, India, and the Malay Archipelago — with ingredients more commonly used in native Thai cuisine to make massaman curry paste. The substance of the dish is usually based on chicken, potatoes, onions, and peanuts.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/Kaeng_matsaman_kai.JPG/960px-Kaeng_matsaman_kai.JPG`,page:`https://commons.wikimedia.org/wiki/File:Kaeng_matsaman_kai.JPG`,artist:`Takeaway`,license:`CC BY-SA 3.0`}},"dish:Tom yum":{wiki:{title:`Tom yum`,url:`https://en.wikipedia.org/wiki/Tom_yum`,extract:`Tom yum or tom yam is a family of hot and sour Thai soups. The name tom yam is composed of two words in the Thai language: tom refers to the boiling process, while yam means "mixed".`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Tom_yam_kung_maenam.jpg/960px-Tom_yam_kung_maenam.jpg`,page:`https://commons.wikimedia.org/wiki/File:Tom_yam_kung_maenam.jpg`,artist:`Takeaway`,license:`CC BY-SA 3.0`}},"dish:Kaeng som":{wiki:{title:`Kaeng som`,url:`https://en.wikipedia.org/wiki/Kaeng_som`,extract:`Kaeng som, gaeng som, Asam rebus, or Thai/Lao/Malaysian sour curry is a sour and spicy fish curry or soup with vegetables popular in Southeast Asia. The curry is characteristic for its sour taste, which comes from tamarind (makham). The recipe uses palm sugar to sweeten the curry.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/Kaeng_som-marum63.JPG/960px-Kaeng_som-marum63.JPG`,page:`https://commons.wikimedia.org/wiki/File:Kaeng_som-marum63.JPG`,artist:`Xufanc`,license:`CC BY-SA 3.0`}},"krabi/Gaeng Som Pla":{wiki:{title:`Kaeng som`,url:`https://en.wikipedia.org/wiki/Kaeng_som`,extract:`Kaeng som, gaeng som, Asam rebus, or Thai/Lao/Malaysian sour curry is a sour and spicy fish curry or soup with vegetables popular in Southeast Asia. The curry is characteristic for its sour taste, which comes from tamarind (makham). The recipe uses palm sugar to sweeten the curry.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/Kaeng_som-marum63.JPG/960px-Kaeng_som-marum63.JPG`,page:`https://commons.wikimedia.org/wiki/File:Kaeng_som-marum63.JPG`,artist:`Xufanc`,license:`CC BY-SA 3.0`}},"krabi/Khao Yam":{wiki:{title:`Nasi ulam`,url:`https://en.wikipedia.org/wiki/Nasi_ulam`,extract:`Nasi ulam is a traditional rice dish of Betawi, Malay and Peranakan cuisines that mixes various traditional herbs and vegetables (ulam) mostly the leaves of pegagan, kemangi, Vietnamese mint, and torch ginger among other things, accompanied with various side dishes.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/Nasi_Ulam_Betawi.jpg/960px-Nasi_Ulam_Betawi.jpg`,page:`https://commons.wikimedia.org/wiki/File:Nasi_Ulam_Betawi.jpg`,artist:`Gunawan Kartapranata`,license:`CC BY-SA 3.0`}},"krabi/Khua Kling":{wiki:{title:`Khua kling`,url:`https://en.wikipedia.org/wiki/Khua_kling`,extract:`Khua kling is a spicy, dry-fried curry from Thai cuisine originating from the Southern Region. The primary components are meat and Southern Thai style red curry paste. Unlike most curries that are cooked in a spicy sauce, the dry meat style directly seasons the meat. When dry-frying the meat its fat renders allowing the curry paste to adhere.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/Khua_kling.JPG/960px-Khua_kling.JPG`,page:`https://commons.wikimedia.org/wiki/File:Khua_kling.JPG`,artist:`Takeaway`,license:`CC BY-SA 3.0`}},"krabi/Gaeng Tai Pla":{wiki:{title:`Kaeng tai pla`,url:`https://en.wikipedia.org/wiki/Kaeng_tai_pla`,extract:`Kaeng tai pla is a curry of southern Thai cuisine. Its name is derived from tai pla, a salty sauce made from fermented fish entrails, which gives the curry a strong smell and flavor.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/c/c4/Kaeng_tai_pla34.JPG`,page:`https://commons.wikimedia.org/wiki/File:Kaeng_tai_pla34.JPG`,artist:`Xufanc`,license:`CC BY-SA 3.0`}},"krabi/Roti Gaeng":{wiki:{title:`Roti canai`,url:`https://en.wikipedia.org/wiki/Roti_canai`,extract:`Roti canai, or roti prata, also known as roti chanai and roti cane, is an unleavened flatbread of Indian origin found in the cuisines of Southeast Asia, especially those of Brunei, Indonesia, Malaysia, Singapore, and Thailand.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/YosriRotiCanai.jpg/960px-YosriRotiCanai.jpg`,page:`https://commons.wikimedia.org/wiki/File:YosriRotiCanai.jpg`,artist:`Yosri at ms.wikipedia`,license:`GFDL`}},"krabi/Khanom Jeen Nam Ya":{wiki:{title:`Khanom chin`,url:`https://en.wikipedia.org/wiki/Khanom_chin`,extract:`Khanom chin or khanom jeen are fresh, thin white rice noodles in Thai cuisine which are made from rice fermented for three days, boiled, and extruded through into boiling water through a sieve. Khanom chin is served with stocks including coconut milk, fish curry, and chilli.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d9/Khanom_Chin_-_Thai_rice_noodles.JPG/960px-Khanom_Chin_-_Thai_rice_noodles.JPG`,page:`https://commons.wikimedia.org/wiki/File:Khanom_Chin_-_Thai_rice_noodles.JPG`,artist:`User:Mattes`,license:`Public domain`}},"bangkok/Pad Thai":{wiki:{title:`Pad thai`,url:`https://en.wikipedia.org/wiki/Pad_thai`,extract:`Pad thai is a stir-fried rice noodle dish commonly served as a street food in Thailand as part of Thai cuisine. It is typically made with rice noodles, shrimp, peanuts, green onions, scrambled egg, sugar and bean sprouts. The ingredients are fried in a wok.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/39/Phat_Thai_kung_Chang_Khien_street_stall.jpg/960px-Phat_Thai_kung_Chang_Khien_street_stall.jpg`,page:`https://commons.wikimedia.org/wiki/File:Phat_Thai_kung_Chang_Khien_street_stall.jpg`,artist:`Takeaway`,license:`CC BY-SA 3.0`}},"bangkok/Tom Yum Goong":{wiki:{title:`Tom yum`,url:`https://en.wikipedia.org/wiki/Tom_yum`,extract:`Tom yum or tom yam is a family of hot and sour Thai soups. The name tom yam is composed of two words in the Thai language: tom refers to the boiling process, while yam means "mixed".`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Tom_yam_kung_maenam.jpg/960px-Tom_yam_kung_maenam.jpg`,page:`https://commons.wikimedia.org/wiki/File:Tom_yam_kung_maenam.jpg`,artist:`Takeaway`,license:`CC BY-SA 3.0`}},"bangkok/Boat Noodles":{wiki:{title:`Boat noodles`,url:`https://en.wikipedia.org/wiki/Boat_noodles`,extract:`Boat noodles is a Thai-style noodle dish with a strong flavor. It contains both pork and beef, as well as dark soy sauce, pickled bean curd, and some other spices, and it is normally served with meatballs and pig's liver. The soup is seasoned with pig or cow blood mixed with salt and spices. The colour is similar to that of beef noodle soup, but the soup is considerably thicker due to the added blood.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7c/Boat_noodles.jpg/960px-Boat_noodles.jpg`,page:`https://commons.wikimedia.org/wiki/File:Boat_noodles.jpg`,artist:`Flickr user Alpha`,license:`CC BY-SA 2.0`}},"bangkok/Mango Sticky Rice":{wiki:{title:`Mango sticky rice`,url:`https://en.wikipedia.org/wiki/Mango_sticky_rice`,extract:`Mango sticky rice is a traditional Southeast Asian and South Asian dessert made with glutinous rice, fresh mango and coconut milk.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Mango_sticy_rice_%283859549574%29.jpg/960px-Mango_sticy_rice_%283859549574%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Mango_sticy_rice_(3859549574).jpg`,artist:`Dennis Wong from Hong Kong, Hong Kong`,license:`CC BY 2.0`}},"bangkok/Som Tam":{wiki:{title:`Green papaya salad`,url:`https://en.wikipedia.org/wiki/Green_papaya_salad`,extract:`Green papaya salad is a spicy salad made from shredded unripe papaya. It is believed to have been created by Lao people and is considered one of the national dishes of Laos.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/2013_Tam_Lao.jpg/960px-2013_Tam_Lao.jpg`,page:`https://commons.wikimedia.org/wiki/File:2013_Tam_Lao.jpg`,artist:`Takeaway`,license:`CC BY-SA 3.0`}},"bangkok/Khao Man Gai":{wiki:{title:`Hainanese chicken rice`,url:`https://en.wikipedia.org/wiki/Hainanese_chicken_rice`,extract:`Hainanese chicken rice is a dish of poached or roasted chicken with seasoned rice, served with chilli sauce and usually with cucumbers, tomato slices or cilantro garnishes. It was created by immigrants from Hainan in southern China and adapted from the Hainanese dishes of Wenchang chicken and Wenchang chicken rice.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Hainanese_Chicken_Rice.jpg/960px-Hainanese_Chicken_Rice.jpg`,page:`https://commons.wikimedia.org/wiki/File:Hainanese_Chicken_Rice.jpg`,artist:`No machine-readable author provided. Terence assumed (based on copyright claims).`,license:`CC BY 2.5`}},"dish:Khao soi":{wiki:{title:`Khao soi`,url:`https://en.wikipedia.org/wiki/Khao_soi`,extract:`Khao soi or khao soy is a dish served in Northern Thailand. The dish is believed to have evolved from Chin Haw Muslim traders who plied the spice route when what is now modern-day northern Thailand was controlled by the Burmese. A comparable dish, ohn no khao swè, is widely served in Myanmar. In Myanmar, it is known as "khao swè", an adaptation of the original name.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/Khao_Soi_Northern_Thai_food_%E0%B8%82%E0%B9%89%E0%B8%B2%E0%B8%A7%E0%B8%8B%E0%B8%AD%E0%B8%A2_%E0%B8%9C%E0%B8%B1%E0%B8%81%E0%B8%94%E0%B8%AD%E0%B8%87.jpg/960px-Khao_Soi_Northern_Thai_food_%E0%B8%82%E0%B9%89%E0%B8%B2%E0%B8%A7%E0%B8%8B%E0%B8%AD%E0%B8%A2_%E0%B8%9C%E0%B8%B1%E0%B8%81%E0%B8%94%E0%B8%AD%E0%B8%87.jpg`,page:`https://commons.wikimedia.org/wiki/File:Khao_Soi_Northern_Thai_food_%E0%B8%82%E0%B9%89%E0%B8%B2%E0%B8%A7%E0%B8%8B%E0%B8%AD%E0%B8%A2_%E0%B8%9C%E0%B8%B1%E0%B8%81%E0%B8%94%E0%B8%AD%E0%B8%87.jpg`,artist:`Chainwit.`,license:`CC BY-SA 4.0`}},"dish:Kaeng hang le":{wiki:{title:`Kaeng hang le`,url:`https://en.wikipedia.org/wiki/Kaeng_hang_le`,extract:`Kaeng hang le is a rich Northern Thai pork curry. Hang le curry is very popular in Northern Thailand, well-known as a specialty of the region. It differs from traditional northern Thai curries in several respects: it is typically eaten with long-grained rice, not sticky rice, and uses dried spices, which are commonly used in Burmese, but not northern Thai curries.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fa/%E0%B9%81%E0%B8%81%E0%B8%87%E0%B8%AE%E0%B8%B1%E0%B8%87%E0%B9%80%E0%B8%A5_%E0%B8%97%E0%B8%B5%E0%B9%88_%E0%B8%AB%E0%B8%A5%E0%B8%B9%E0%B9%89%E0%B8%A5%E0%B8%B3.jpg/960px-%E0%B9%81%E0%B8%81%E0%B8%87%E0%B8%AE%E0%B8%B1%E0%B8%87%E0%B9%80%E0%B8%A5_%E0%B8%97%E0%B8%B5%E0%B9%88_%E0%B8%AB%E0%B8%A5%E0%B8%B9%E0%B9%89%E0%B8%A5%E0%B8%B3.jpg`,page:`https://commons.wikimedia.org/wiki/File:%E0%B9%81%E0%B8%81%E0%B8%87%E0%B8%AE%E0%B8%B1%E0%B8%87%E0%B9%80%E0%B8%A5_%E0%B8%97%E0%B8%B5%E0%B9%88_%E0%B8%AB%E0%B8%A5%E0%B8%B9%E0%B9%89%E0%B8%A5%E0%B8%B3.jpg`,artist:`Chainwit.`,license:`CC BY-SA 4.0`}},"dish:Nam ngiao":{wiki:{title:`Nam ngiao`,url:`https://en.wikipedia.org/wiki/Nam_ngiao`,extract:`Nam ngiao or nam ngio is a noodle soup or curry of the cuisine of the Tai Yai people who live in the northeast of Burma, the southwest of Yunnan province, China, and in northern Thailand, mainly in Mae Hong Son Province. The dish has become famous in the northern Thai cuisine. Nam ngiao has a characteristic spicy and tangy flavor.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/Khanom_chin_nam_ngiao_supoe.jpg/960px-Khanom_chin_nam_ngiao_supoe.jpg`,page:`https://commons.wikimedia.org/wiki/File:Khanom_chin_nam_ngiao_supoe.jpg`,artist:`Takeaway`,license:`CC BY-SA 3.0`}},"dish:Kai yang":{wiki:{title:`Kai yang`,url:`https://en.wikipedia.org/wiki/Kai_yang`,extract:`Kai yang or gai yang, also known as kai ping or gai ping, or pīng kai, is a dish of shared origin from Lao and Thai peoples commonly eaten throughout the regions of both Laos and Thailand. The dish is a standard staple of street markets and readily available at all times.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Gaiyangtaladdonwai06.jpg/960px-Gaiyangtaladdonwai06.jpg`,page:`https://commons.wikimedia.org/wiki/File:Gaiyangtaladdonwai06.jpg`,artist:`Heinrich Damm ( User:Hdamm , Hdamm at de.wikipedia.org )`,license:`CC BY 2.0`}},"dish:Glutinous rice":{wiki:{title:`Glutinous rice`,url:`https://en.wikipedia.org/wiki/Glutinous_rice`,extract:`Glutinous rice is a type of rice grown mainly in Southeast Asia and the northeastern regions of South Asia, which has opaque grains and very low amylose content and is especially sticky when cooked. It is widely consumed across Asia.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/aa/Chapssal_%28glutinous_rice%29.jpg/960px-Chapssal_%28glutinous_rice%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Chapssal_(glutinous_rice).jpg`,artist:`국립국어원`,license:`CC BY-SA 2.0 kr`}},"dish:Sai oua":{wiki:{title:`Sai oua`,url:`https://en.wikipedia.org/wiki/Sai_oua`,extract:`Sai oua, sometimes also known as Laotian sausage, is a popular type of sausage made in Laos, Myanmar, and Thailand, particularly in northern Thailand and northern Laos. It is prepared from coarsely chopped fatty pork seasoned with lemongrass, galangal, kaffir lime leaves, shallots, cilantro, chilies, garlic, salt, sticky rice, and fish sauce.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/c/cc/Lao_Sai_Oua.png`,page:`https://commons.wikimedia.org/wiki/File:Lao_Sai_Oua.png`,artist:`Isan1985`,license:`CC BY-SA 4.0`}},"dish:Nam phrik num":{wiki:{title:`Nam phrik num`,url:`https://en.wikipedia.org/wiki/Nam_phrik_num`,extract:`Nam Phrik Num is a kind of “Nam phrik” of Northern Thailand origin. It is commonly served in a small bowl or saucer placed by the main dish as a condiment or a dip, mostly for uncooked or boiled vegetables, sticky rice, or pork crackling.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/Nam_phrik_num.jpg/960px-Nam_phrik_num.jpg`,page:`https://commons.wikimedia.org/wiki/File:Nam_phrik_num.jpg`,artist:`Takeaway`,license:`CC BY-SA 3.0`}},"dish:Khao kha mu":{wiki:{title:`Khao kha mu`,url:`https://en.wikipedia.org/wiki/Khao_kha_mu`,extract:`Khao kha mu or khao kha moo, or sometimes simply called kha mu (ขาหมู), is a popular Thai food. It is influenced by Chinese cuisine, specifically Teochew cuisine.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Khao_kha_mu_thailand.jpg/960px-Khao_kha_mu_thailand.jpg`,page:`https://commons.wikimedia.org/wiki/File:Khao_kha_mu_thailand.jpg`,artist:`Amin`,license:`CC BY-SA 4.0`}},"dish:Congee":{wiki:{title:`Congee`,url:`https://en.wikipedia.org/wiki/Congee`,extract:`Congee is a form of savoury porridge, primarily made by boiling rice in a large amount of water until the rice softens, and commonly flavored with salt or mild broth. Depending on the rice–water ratio, the thickness of congee varies from a Western oatmeal porridge to a gruel. Congee is typically served with side dishes, or it can be topped with meat, fish, and pickled vegetables.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/Chinese_rice_congee.jpg/960px-Chinese_rice_congee.jpg`,page:`https://commons.wikimedia.org/wiki/File:Chinese_rice_congee.jpg`,artist:`Daiju Azuma`,license:`CC BY-SA 2.5`}},"chiang-mai/Khao Soi":{wiki:{title:`Khao soi`,url:`https://en.wikipedia.org/wiki/Khao_soi`,extract:`Khao soi or khao soy is a dish served in Northern Thailand. The dish is believed to have evolved from Chin Haw Muslim traders who plied the spice route when what is now modern-day northern Thailand was controlled by the Burmese. A comparable dish, ohn no khao swè, is widely served in Myanmar. In Myanmar, it is known as "khao swè", an adaptation of the original name.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/Khao_Soi_Northern_Thai_food_%E0%B8%82%E0%B9%89%E0%B8%B2%E0%B8%A7%E0%B8%8B%E0%B8%AD%E0%B8%A2_%E0%B8%9C%E0%B8%B1%E0%B8%81%E0%B8%94%E0%B8%AD%E0%B8%87.jpg/960px-Khao_Soi_Northern_Thai_food_%E0%B8%82%E0%B9%89%E0%B8%B2%E0%B8%A7%E0%B8%8B%E0%B8%AD%E0%B8%A2_%E0%B8%9C%E0%B8%B1%E0%B8%81%E0%B8%94%E0%B8%AD%E0%B8%87.jpg`,page:`https://commons.wikimedia.org/wiki/File:Khao_Soi_Northern_Thai_food_%E0%B8%82%E0%B9%89%E0%B8%B2%E0%B8%A7%E0%B8%8B%E0%B8%AD%E0%B8%A2_%E0%B8%9C%E0%B8%B1%E0%B8%81%E0%B8%94%E0%B8%AD%E0%B8%87.jpg`,artist:`Chainwit.`,license:`CC BY-SA 4.0`}},"chiang-mai/Sai Oua":{wiki:{title:`Sai oua`,url:`https://en.wikipedia.org/wiki/Sai_oua`,extract:`Sai oua, sometimes also known as Laotian sausage, is a popular type of sausage made in Laos, Myanmar, and Thailand, particularly in northern Thailand and northern Laos. It is prepared from coarsely chopped fatty pork seasoned with lemongrass, galangal, kaffir lime leaves, shallots, cilantro, chilies, garlic, salt, sticky rice, and fish sauce.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/c/cc/Lao_Sai_Oua.png`,page:`https://commons.wikimedia.org/wiki/File:Lao_Sai_Oua.png`,artist:`Isan1985`,license:`CC BY-SA 4.0`}},"chiang-mai/Nam Prik Noom":{wiki:{title:`Nam phrik num`,url:`https://en.wikipedia.org/wiki/Nam_phrik_num`,extract:`Nam Phrik Num is a kind of “Nam phrik” of Northern Thailand origin. It is commonly served in a small bowl or saucer placed by the main dish as a condiment or a dip, mostly for uncooked or boiled vegetables, sticky rice, or pork crackling.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/Nam_phrik_num.jpg/960px-Nam_phrik_num.jpg`,page:`https://commons.wikimedia.org/wiki/File:Nam_phrik_num.jpg`,artist:`Takeaway`,license:`CC BY-SA 3.0`}},"chiang-mai/Khanom Jeen Nam Ngiao":{wiki:{title:`Nam ngiao`,url:`https://en.wikipedia.org/wiki/Nam_ngiao`,extract:`Nam ngiao or nam ngio is a noodle soup or curry of the cuisine of the Tai Yai people who live in the northeast of Burma, the southwest of Yunnan province, China, and in northern Thailand, mainly in Mae Hong Son Province. The dish has become famous in the northern Thai cuisine. Nam ngiao has a characteristic spicy and tangy flavor.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/Khanom_chin_nam_ngiao_supoe.jpg/960px-Khanom_chin_nam_ngiao_supoe.jpg`,page:`https://commons.wikimedia.org/wiki/File:Khanom_chin_nam_ngiao_supoe.jpg`,artist:`Takeaway`,license:`CC BY-SA 3.0`}},"chiang-mai/Gaeng Hang Lay":{wiki:{title:`Kaeng hang le`,url:`https://en.wikipedia.org/wiki/Kaeng_hang_le`,extract:`Kaeng hang le is a rich Northern Thai pork curry. Hang le curry is very popular in Northern Thailand, well-known as a specialty of the region. It differs from traditional northern Thai curries in several respects: it is typically eaten with long-grained rice, not sticky rice, and uses dried spices, which are commonly used in Burmese, but not northern Thai curries.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fa/%E0%B9%81%E0%B8%81%E0%B8%87%E0%B8%AE%E0%B8%B1%E0%B8%87%E0%B9%80%E0%B8%A5_%E0%B8%97%E0%B8%B5%E0%B9%88_%E0%B8%AB%E0%B8%A5%E0%B8%B9%E0%B9%89%E0%B8%A5%E0%B8%B3.jpg/960px-%E0%B9%81%E0%B8%81%E0%B8%87%E0%B8%AE%E0%B8%B1%E0%B8%87%E0%B9%80%E0%B8%A5_%E0%B8%97%E0%B8%B5%E0%B9%88_%E0%B8%AB%E0%B8%A5%E0%B8%B9%E0%B9%89%E0%B8%A5%E0%B8%B3.jpg`,page:`https://commons.wikimedia.org/wiki/File:%E0%B9%81%E0%B8%81%E0%B8%87%E0%B8%AE%E0%B8%B1%E0%B8%87%E0%B9%80%E0%B8%A5_%E0%B8%97%E0%B8%B5%E0%B9%88_%E0%B8%AB%E0%B8%A5%E0%B8%B9%E0%B9%89%E0%B8%A5%E0%B8%B3.jpg`,artist:`Chainwit.`,license:`CC BY-SA 4.0`}},"chiang-mai/Larb Muang":{wiki:{title:`Larb`,url:`https://en.wikipedia.org/wiki/Larb`,extract:`Laab / Larb is a type of Lao meat salad that is the national dish of Laos, along with green papaya salad and sticky rice. Laab in the Lao language is a noun that refers to meat or other flesh that has been finely chopped and pounded. It is also considered a food of good luck in both Laos and Thailand because it has homonyms that mean 'lucky' in both languages, derived from लाभ in Sanskrit.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/LaoFood_LarbNeua.JPG/960px-LaoFood_LarbNeua.JPG`,page:`https://commons.wikimedia.org/wiki/File:LaoFood_LarbNeua.JPG`,artist:`Jpatokal`,license:`CC BY-SA 4.0`}},"dish:Khao tom":{wiki:{title:`Khao tom`,url:`https://en.wikipedia.org/wiki/Khao_tom`,extract:`Khao tom and khao tom mat are a popular Laotian and Thai dessert made of sticky rice, ripe banana, coconut milk, all wrapped and steamed-cooked in banana leaves. A similar dessert is enjoyed throughout Southeast Asian countries where it is known as num ansom in Khmer, lepet in Indonesian, suman in Filipino, and bánh tét and bánh chưng in Vietnamese.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/8/85/Lao_cuisine_khaotom.jpg`,page:`https://commons.wikimedia.org/wiki/File:Lao_cuisine_khaotom.jpg`,artist:`Picklish at English Wikipedia`,license:`Public domain`}},"phuket/Mee Hokkien":{wiki:{title:`Hokkien mee`,url:`https://en.wikipedia.org/wiki/Hokkien_mee`,extract:`Hokkien mee, meaning "Fujian noodles" in Southern Min, is a group of related Southeast Asian dishes that have their origins in the cuisine of China's Fujian (Hokkien) province.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/Newton_HokkienMee.JPG/960px-Newton_HokkienMee.JPG`,page:`https://commons.wikimedia.org/wiki/File:Newton_HokkienMee.JPG`,artist:`Jpatokal`,license:`CC BY-SA 4.0`}},"phuket/Kanom Jeen Phuket":{wiki:{title:`Khanom chin`,url:`https://en.wikipedia.org/wiki/Khanom_chin`,extract:`Khanom chin or khanom jeen are fresh, thin white rice noodles in Thai cuisine which are made from rice fermented for three days, boiled, and extruded through into boiling water through a sieve. Khanom chin is served with stocks including coconut milk, fish curry, and chilli.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d9/Khanom_Chin_-_Thai_rice_noodles.JPG/960px-Khanom_Chin_-_Thai_rice_noodles.JPG`,page:`https://commons.wikimedia.org/wiki/File:Khanom_Chin_-_Thai_rice_noodles.JPG`,artist:`User:Mattes`,license:`Public domain`}},"phuket/Gaeng Som Pla":{wiki:{title:`Kaeng som`,url:`https://en.wikipedia.org/wiki/Kaeng_som`,extract:`Kaeng som, gaeng som, Asam rebus, or Thai/Lao/Malaysian sour curry is a sour and spicy fish curry or soup with vegetables popular in Southeast Asia. The curry is characteristic for its sour taste, which comes from tamarind (makham). The recipe uses palm sugar to sweeten the curry.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/Kaeng_som-marum63.JPG/960px-Kaeng_som-marum63.JPG`,page:`https://commons.wikimedia.org/wiki/File:Kaeng_som-marum63.JPG`,artist:`Xufanc`,license:`CC BY-SA 3.0`}},"dish:Fat rascal":{wiki:{title:`Fat rascal`,url:`https://en.wikipedia.org/wiki/Fat_rascal`,extract:`A fat rascal, closely related to the historical turf cake, is a type of cake, similar to a scone or rock cake in both taste and ingredients. It originated in Yorkshire at least as early as the 19th century.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/0/06/Fat_Rascal_cookies_%28cropped%29.jpg/960px-Fat_Rascal_cookies_%28cropped%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Fat_Rascal_cookies_(cropped).jpg`,artist:`Wendy Slattery`,license:`CC BY 2.0`}},"dish:Tea (meal)":{wiki:{title:`Tea (meal)`,url:`https://en.wikipedia.org/wiki/Tea_(meal)`,extract:`Tea is an umbrella term for several different meals consisting of food sometimes accompanied by tea to drink. The English writer Isabella Beeton, whose books on home economics were widely read in the 19th century, describes meals of various kinds and provides menus for the "old-fashioned tea", the "at-home tea", the "family tea", and the "high tea".`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/Afternoon_meal_in_Tiffin.jpg/960px-Afternoon_meal_in_Tiffin.jpg`,page:`https://commons.wikimedia.org/wiki/File:Afternoon_meal_in_Tiffin.jpg`,artist:`Peachyeung316`,license:`CC BY-SA 4.0`}},"dish:Pancake":{wiki:{title:`Pancake`,url:`https://en.wikipedia.org/wiki/Pancake`,extract:`A pancake, also known as a hotcake, griddlecake, or flapjack, is a flat type of batter bread like cake, often thin and round, prepared from a starch-based batter that may contain eggs, milk, and butter, and then cooked on a hot surface such as a griddle or frying pan. Archaeological evidence suggests that pancakes were probably eaten in prehistoric societies.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Foodiesfeed.com_pouring-honey-on-pancakes-with-walnuts.jpg/960px-Foodiesfeed.com_pouring-honey-on-pancakes-with-walnuts.jpg`,page:`https://commons.wikimedia.org/wiki/File:Foodiesfeed.com_pouring-honey-on-pancakes-with-walnuts.jpg`,artist:`Mae Mu`,license:`CC0`}},"dish:Chocolate brownie":{wiki:{title:`Chocolate brownie`,url:`https://en.wikipedia.org/wiki/Chocolate_brownie`,extract:`A chocolate brownie, or simply a brownie, is a chocolate baked dessert bar. Brownies come in a variety of forms and may be either fudgy or cakey, depending on their density. Brownies often have a glossy "skin" on their upper crust and may include ingredients such as nuts, frosting, or chocolate chips.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/68/Chocolatebrownie.JPG/960px-Chocolatebrownie.JPG`,page:`https://commons.wikimedia.org/wiki/File:Chocolatebrownie.JPG`,artist:`Ɱ`,license:`CC BY-SA 3.0`}},"dish:Yorkshire pudding":{wiki:{title:`Yorkshire pudding`,url:`https://en.wikipedia.org/wiki/Yorkshire_pudding`,extract:`Yorkshire pudding is a baked pudding made from a batter of eggs, flour, and milk or water. A common British side dish, it is a versatile food that can be served in numerous ways depending on its ingredients, size, and the accompanying components of the meal. As a first course, it can be served with onion gravy.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/9/9a/Yorkshire_Puddings_on_plate.jpg`,page:`https://commons.wikimedia.org/wiki/File:Yorkshire_Puddings_on_plate.jpg`,artist:`Sam Greenhalgh`,license:`CC BY 2.0`}},"dish:Full breakfast":{wiki:{title:`Full breakfast`,url:`https://en.wikipedia.org/wiki/Full_breakfast`,extract:`A full breakfast or fry-up is a substantial cooked breakfast meal often made in Great Britain and Ireland. Depending on the region where it is served a full breakfast, or one of its variants, may also be referred to as a full English, full Scottish, full Welsh, full Irish fry up, or Ulster fry. Other variants of the full breakfast are made elsewhere.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Full_English_breakfast_%28cropped%29.jpg/960px-Full_English_breakfast_%28cropped%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Full_English_breakfast_(cropped).jpg`,artist:`Joadl`,license:`CC BY-SA 3.0 at`}},"dish:Bacon sandwich":{wiki:{title:`Bacon sandwich`,url:`https://en.wikipedia.org/wiki/Bacon_sandwich`,extract:`A bacon sandwich is a sandwich of cooked bacon. It may be spread with butter, and may be seasoned with brown sauce or tomato ketchup. It is generally served hot. In some establishments the sandwich will be made from bread toasted on only one side, while other establishments serve it on a similar roll as is used for hamburgers.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/Bacon_sandwich_%2814450831119%29.jpg/960px-Bacon_sandwich_%2814450831119%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Bacon_sandwich_(14450831119).jpg`,artist:`Bex Walton from London, England`,license:`CC BY 2.0`}},"dish:Mushy peas":{wiki:{title:`Mushy peas`,url:`https://en.wikipedia.org/wiki/Mushy_peas`,extract:`Mushy peas are dried marrowfat peas which are first soaked overnight in water with sodium bicarbonate, and then rinsed in fresh water, after which the peas are gathered in a saucepan, covered with water, and brought to a boil, and then simmered until the peas are softened. The mush is seasoned with salt and pepper.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/Fish%2C_chips_and_mushy_peas.jpg/960px-Fish%2C_chips_and_mushy_peas.jpg`,page:`https://commons.wikimedia.org/wiki/File:Fish,_chips_and_mushy_peas.jpg`,artist:`Charles Haynes from Bangalore, India`,license:`CC BY-SA 2.0`}},"york/Yorkshire Pudding":{wiki:{title:`Yorkshire pudding`,url:`https://en.wikipedia.org/wiki/Yorkshire_pudding`,extract:`Yorkshire pudding is a baked pudding made from a batter of eggs, flour, and milk or water. A common British side dish, it is a versatile food that can be served in numerous ways depending on its ingredients, size, and the accompanying components of the meal. As a first course, it can be served with onion gravy.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/9/9a/Yorkshire_Puddings_on_plate.jpg`,page:`https://commons.wikimedia.org/wiki/File:Yorkshire_Puddings_on_plate.jpg`,artist:`Sam Greenhalgh`,license:`CC BY 2.0`}},"york/Fish and Chips":{wiki:{title:`Fish and chips`,url:`https://en.wikipedia.org/wiki/Fish_and_chips`,extract:`Fish and chips is a hot dish consisting of battered and fried fish served with chips. Often considered the national dish of the United Kingdom, fish and chips originated in England in the 19th century. Today, the dish is a common takeaway food in numerous other countries, particularly English-speaking and Commonwealth nations.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/Fish_and_chips_blackpool.jpg/960px-Fish_and_chips_blackpool.jpg`,page:`https://commons.wikimedia.org/wiki/File:Fish_and_chips_blackpool.jpg`,artist:`Matthias Meckel`,license:`CC BY-SA 4.0`}},"york/Fat Rascal":{wiki:{title:`Fat rascal`,url:`https://en.wikipedia.org/wiki/Fat_rascal`,extract:`A fat rascal, closely related to the historical turf cake, is a type of cake, similar to a scone or rock cake in both taste and ingredients. It originated in Yorkshire at least as early as the 19th century.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/0/06/Fat_Rascal_cookies_%28cropped%29.jpg/960px-Fat_Rascal_cookies_%28cropped%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Fat_Rascal_cookies_(cropped).jpg`,artist:`Wendy Slattery`,license:`CC BY 2.0`}},"york/Parkin":{wiki:{title:`Parkin (cake)`,url:`https://en.wikipedia.org/wiki/Parkin_(cake)`,extract:`Parkin is a gingerbread cake traditionally made with oatmeal and black treacle, which originated in Northern England. Often associated with Yorkshire, it is widespread and popular elsewhere, notably in Lancashire. Parkin is baked to a hard cake but with resting becomes moist and even sometimes sticky.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/YorkShireParkin.jpg/960px-YorkShireParkin.jpg`,page:`https://commons.wikimedia.org/wiki/File:YorkShireParkin.jpg`,artist:`Spider.Dog`,license:`CC BY-SA 2.0`}},"york/Wensleydale Cheese with Fruit Cake":{wiki:{title:`Wensleydale cheese`,url:`https://en.wikipedia.org/wiki/Wensleydale_cheese`,extract:`Wensleydale is a style of cheese originally produced in Wensleydale, North Yorkshire, England, but now mostly made in large commercial creameries throughout the United Kingdom. The term "Yorkshire Wensleydale" can only be used for cheese that is made in Wensleydale.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Wensleydale_cheese_2.jpg/960px-Wensleydale_cheese_2.jpg`,page:`https://commons.wikimedia.org/wiki/File:Wensleydale_cheese_2.jpg`,artist:`Jon Sullivan`,license:`Public domain`}},"dish:Raclette":{wiki:{title:`Raclette`,url:`https://en.wikipedia.org/wiki/Raclette`,extract:`Raclette is a dish of Swiss origin, also popular in other countries, based on heating cheese and scraping off the melted part, then typically served with boiled potatoes. Raclette is historically a dish originating from the canton of Valais in Switzerland. This cheese from Valais benefits from an AOP. Raclette cheese is also a Swiss-type cheese marketed specifically to be used for this dish.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/Raclette_20040817_140816.jpg/960px-Raclette_20040817_140816.jpg`,page:`https://commons.wikimedia.org/wiki/File:Raclette_20040817_140816.jpg`,artist:`Ka23 13`,license:`CC BY-SA 4.0`}},"dish:Scotch egg":{wiki:{title:`Scotch egg`,url:`https://en.wikipedia.org/wiki/Scotch_egg`,extract:`A Scotch egg is a boiled egg wrapped in sausage meat, coated in breadcrumbs and baked or deep-fried.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/One_scotch_egg_%28No_jar_of_Marmite%29.jpg/960px-One_scotch_egg_%28No_jar_of_Marmite%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:One_scotch_egg_(No_jar_of_Marmite).jpg`,artist:`Unhindered by Talent`,license:`CC BY-SA 2.0`}},"dish:Pie and mash":{wiki:{title:`Pie and mash`,url:`https://en.wikipedia.org/wiki/Pie_and_mash`,extract:`Pie and mash is a British working-class food, originating in the docks of London, considered "a Cockney classic". It typically consists of a minced beef pie served with mashed potato and a parsley sauce known as liquor, with malt vinegar or non-brewed condiment as a condiment.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2c/Goddards_pie_mash_and_liquor.jpg/960px-Goddards_pie_mash_and_liquor.jpg`,page:`https://commons.wikimedia.org/wiki/File:Goddards_pie_mash_and_liquor.jpg`,artist:`Goddards Pies Limited`,license:`CC BY-SA 4.0`}},"dish:Jellied eels":{wiki:{title:`Jellied eels`,url:`https://en.wikipedia.org/wiki/Jellied_eels`,extract:`Jellied eels is a traditional English dish that originated in the 18th century, primarily in the East End of London. The dish consists of chopped eels boiled in a spiced stock that is allowed to cool and set, forming a jelly. It is usually served cold.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e3/Eels_1385.JPG/960px-Eels_1385.JPG`,page:`https://commons.wikimedia.org/wiki/File:Eels_1385.JPG`,artist:`JanesDaddy (Ensglish User)`,license:`CC BY-SA 3.0`}},"dish:Dal makhani":{wiki:{title:`Dal makhani`,url:`https://en.wikipedia.org/wiki/Dal_makhani`,extract:`Dal makhani is a dish originating in the Punjab region. A relatively modern variation of traditional lentil dishes, it is made with urad dal and other pulses, and includes butter and cream.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/Punjabi_style_Dal_Makhani.jpg/960px-Punjabi_style_Dal_Makhani.jpg`,page:`https://commons.wikimedia.org/wiki/File:Punjabi_style_Dal_Makhani.jpg`,artist:`Radhikamprabhu82`,license:`CC BY-SA 4.0`}},"dish:Bone marrow (food)":{wiki:{title:`Bone marrow as food`,url:`https://en.wikipedia.org/wiki/Bone_marrow_as_food`,extract:`Humans consume the bone marrow of animals as a food source. It is found in the long bones of animals and comes in two types: yellow and red marrow. Red marrow contains more nutrients than yellow marrow. Marrow can be found in bone-in cuts of meat from butchers or supermarkets.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Markkloesschensuppe.jpg/960px-Markkloesschensuppe.jpg`,page:`https://commons.wikimedia.org/wiki/File:Markkloesschensuppe.jpg`,artist:`No machine-readable author provided. AlexanderDreyer~commonswiki assumed (based on copyright…`,license:`Public domain`}},"dish:Eccles cake":{wiki:{title:`Eccles cake`,url:`https://en.wikipedia.org/wiki/Eccles_cake`,extract:`An Eccles cake is a small, round turnover, filled with currants and made from flaky pastry with butter, sometimes topped with brown sugar. It originated in Eccles, England.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Eccles_cake.jpg/960px-Eccles_cake.jpg`,page:`https://commons.wikimedia.org/wiki/File:Eccles_cake.jpg`,artist:`Sean Whitton ( User:Xyrael )`,license:`CC BY-SA 3.0`}},"dish:Madeleine (cake)":{wiki:{title:`Madeleine (cake)`,url:`https://en.wikipedia.org/wiki/Madeleine_(cake)`,extract:`The madeleine is a small traditional cake that originated in Commercy and Liverdun, two communes of the Lorraine region in northeastern France.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/1/10/Madeleines_pic.jpg`,page:`https://commons.wikimedia.org/wiki/File:Madeleines_pic.jpg`,artist:`Ruth`,license:`CC BY-SA 4.0`}},"dish:Viennoiserie":{wiki:{title:`Viennoiserie`,url:`https://en.wikipedia.org/wiki/Viennoiserie`,extract:`Viennoiserie is a yeast-leavened dough, as well as an overarching name for the products made with it, that are at a meeting point between bread and pastry, which was described by the Dictionnaire Petit Robert as neither a pastry nor a bread. The dough is sweetened with sugar and enriched with butter, eggs, milk or a combination of the three.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/Pain_au_chocolat_Luc_Viatour.jpg/960px-Pain_au_chocolat_Luc_Viatour.jpg`,page:`https://commons.wikimedia.org/wiki/File:Pain_au_chocolat_Luc_Viatour.jpg`,artist:`Luc Viatour`,license:`CC BY-SA 3.0`}},"london/Fish and Chips":{wiki:{title:`Fish and chips`,url:`https://en.wikipedia.org/wiki/Fish_and_chips`,extract:`Fish and chips is a hot dish consisting of battered and fried fish served with chips. Often considered the national dish of the United Kingdom, fish and chips originated in England in the 19th century. Today, the dish is a common takeaway food in numerous other countries, particularly English-speaking and Commonwealth nations.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/Fish_and_chips_blackpool.jpg/960px-Fish_and_chips_blackpool.jpg`,page:`https://commons.wikimedia.org/wiki/File:Fish_and_chips_blackpool.jpg`,artist:`Matthias Meckel`,license:`CC BY-SA 4.0`}},"london/Sunday Roast":{wiki:{title:`Sunday roast`,url:`https://en.wikipedia.org/wiki/Sunday_roast`,extract:`A Sunday roast or roast dinner is a British dish traditionally eaten on Sunday. It consists of roast meat, roast or mashed potatoes, and accompaniments such as Yorkshire pudding, gravy and stuffing, and may include condiments such as apple sauce, mint sauce, redcurrant sauce, mustard, cranberry sauce or horseradish sauce.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Sunday_roast_lamb_Cock_Inn_Henham_Essex_England_01.jpg/960px-Sunday_roast_lamb_Cock_Inn_Henham_Essex_England_01.jpg`,page:`https://commons.wikimedia.org/wiki/File:Sunday_roast_lamb_Cock_Inn_Henham_Essex_England_01.jpg`,artist:`Acabashi`,license:`CC BY-SA 4.0`}},"london/Full English Breakfast":{wiki:{title:`Full breakfast`,url:`https://en.wikipedia.org/wiki/Full_breakfast`,extract:`A full breakfast or fry-up is a substantial cooked breakfast meal often made in Great Britain and Ireland. Depending on the region where it is served a full breakfast, or one of its variants, may also be referred to as a full English, full Scottish, full Welsh, full Irish fry up, or Ulster fry. Other variants of the full breakfast are made elsewhere.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Full_English_breakfast_%28cropped%29.jpg/960px-Full_English_breakfast_%28cropped%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Full_English_breakfast_(cropped).jpg`,artist:`Joadl`,license:`CC BY-SA 3.0 at`}},"london/Pie and Mash":{wiki:{title:`Pie and mash`,url:`https://en.wikipedia.org/wiki/Pie_and_mash`,extract:`Pie and mash is a British working-class food, originating in the docks of London, considered "a Cockney classic". It typically consists of a minced beef pie served with mashed potato and a parsley sauce known as liquor, with malt vinegar or non-brewed condiment as a condiment.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2c/Goddards_pie_mash_and_liquor.jpg/960px-Goddards_pie_mash_and_liquor.jpg`,page:`https://commons.wikimedia.org/wiki/File:Goddards_pie_mash_and_liquor.jpg`,artist:`Goddards Pies Limited`,license:`CC BY-SA 4.0`}},"london/Afternoon Tea":{wiki:{title:`Tea (meal)`,url:`https://en.wikipedia.org/wiki/Tea_(meal)`,extract:`Tea is an umbrella term for several different meals consisting of food sometimes accompanied by tea to drink. The English writer Isabella Beeton, whose books on home economics were widely read in the 19th century, describes meals of various kinds and provides menus for the "old-fashioned tea", the "at-home tea", the "family tea", and the "high tea".`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/Afternoon_meal_in_Tiffin.jpg/960px-Afternoon_meal_in_Tiffin.jpg`,page:`https://commons.wikimedia.org/wiki/File:Afternoon_meal_in_Tiffin.jpg`,artist:`Peachyeung316`,license:`CC BY-SA 4.0`}},"london/Chicken Tikka Masala":{wiki:{title:`Chicken tikka masala`,url:`https://en.wikipedia.org/wiki/Chicken_tikka_masala`,extract:`Chicken tikka masala is a curry consisting of roasted marinated chicken pieces in a creamy spiced sauce (masala). It is thought to have been created in Britain, possibly by Ali Ahmed Aslam in Glasgow. It is offered at restaurants around the world and in some of its forms is similar to butter chicken.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/Chicken_tikka_masala_%28cropped%29.jpg/960px-Chicken_tikka_masala_%28cropped%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Chicken_tikka_masala_(cropped).jpg`,artist:`Michael Hays`,license:`CC BY 2.0`}},"dish:Hog roast":{wiki:{title:`Pig roast`,url:`https://en.wikipedia.org/wiki/Pig_roast`,extract:`A pig roast or hog roast is an event or gathering which involves the barbecuing of a whole pig. Pig roasts, under a variety of names, are a common traditional celebration event in many places including the United Kingdom, Philippines, Puerto Rico and Cuba. It is also popular in the United States, especially in the state of Hawaii and in the Southern United States.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/Pig_roasting_on_a_spit.jpg/960px-Pig_roasting_on_a_spit.jpg`,page:`https://commons.wikimedia.org/wiki/File:Pig_roasting_on_a_spit.jpg`,artist:`Jbarta`,license:`CC0`}},"dish:Bangers and mash":{wiki:{title:`Bangers and mash`,url:`https://en.wikipedia.org/wiki/Bangers_and_mash`,extract:`Bangers and mash or sausages and mash is a traditional British dish consisting of sausages and mashed potato. The dish is usually served with onion gravy, and may also include fried onions and peas.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9c/Sausage_and_mash_with_peas.jpg/960px-Sausage_and_mash_with_peas.jpg`,page:`https://commons.wikimedia.org/wiki/File:Sausage_and_mash_with_peas.jpg`,artist:`anokarina`,license:`CC BY-SA 2.0`}},"dish:Haggis":{wiki:{title:`Haggis`,url:`https://en.wikipedia.org/wiki/Haggis`,extract:`Haggis is a savoury pudding and sausage containing sheep's pluck, minced with chopped onion, oatmeal, suet, seasonings, and salt, mixed with stock, and cooked while traditionally encased in the animal's stomach though now an artificial casing is often used instead.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a5/Scotland_Haggis.jpg/960px-Scotland_Haggis.jpg`,page:`https://commons.wikimedia.org/wiki/File:Scotland_Haggis.jpg`,artist:`Chris Brown`,license:`CC BY 2.0`}},"dish:Steak pie":{wiki:{title:`Steak pie`,url:`https://en.wikipedia.org/wiki/Steak_pie`,extract:`A steak pie is a traditional meat pie served in Britain. It is made from stewing steak and beef gravy, enclosed in a pastry shell. Sometimes mixed vegetables are included in the filling. The dish is often served with "chunky chips".`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2e/Steak_and_onion_pie.jpg/960px-Steak_and_onion_pie.jpg`,page:`https://commons.wikimedia.org/wiki/File:Steak_and_onion_pie.jpg`,artist:`Alpha`,license:`CC BY-SA 2.0`}},"dish:Cranachan":{wiki:{title:`Cranachan`,url:`https://en.wikipedia.org/wiki/Cranachan`,extract:`Cranachan is a traditional Scottish dessert. It was originally a celebration of harvest, made following the raspberry harvest in August. The dessert of cream and fresh seasonal raspberries is bolstered by Scottish oats and whisky. It has been called "the uncontested king of Scottish desserts".`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Cranachan_%284332953688%29.jpg/960px-Cranachan_%284332953688%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Cranachan_(4332953688).jpg`,artist:`Saskia van de Nieuwenhof from Edinburgh, United Kingdom`,license:`CC BY-SA 2.0`}},"dish:Oyster":{wiki:{title:`Oyster`,url:`https://en.wikipedia.org/wiki/Oyster`,extract:`Oyster is the common name for a number of different families of salt-water bivalve molluscs that live in marine or brackish habitats. In some species, the valves are highly calcified, and many are somewhat irregular in shape. Many oysters are in the superfamily Ostreoidea.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/Crassostrea_gigas_p1040848.jpg/960px-Crassostrea_gigas_p1040848.jpg`,page:`https://commons.wikimedia.org/wiki/File:Crassostrea_gigas_p1040848.jpg`,artist:`David Monniaux`,license:`CC BY-SA 3.0`}},"edinburgh/Haggis, Neeps and Tatties":{wiki:{title:`Haggis`,url:`https://en.wikipedia.org/wiki/Haggis`,extract:`Haggis is a savoury pudding and sausage containing sheep's pluck, minced with chopped onion, oatmeal, suet, seasonings, and salt, mixed with stock, and cooked while traditionally encased in the animal's stomach though now an artificial casing is often used instead.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a5/Scotland_Haggis.jpg/960px-Scotland_Haggis.jpg`,page:`https://commons.wikimedia.org/wiki/File:Scotland_Haggis.jpg`,artist:`Chris Brown`,license:`CC BY 2.0`}},"edinburgh/Cullen Skink":{wiki:{title:`Cullen skink`,url:`https://en.wikipedia.org/wiki/Cullen_skink`,extract:`Cullen skink is a thick Scottish soup typically made of at least smoked haddock, potatoes, and onions. An authentic Cullen skink will use finnan haddie, but it may be prepared with any other undyed smoked haddock. Sometimes ocean perch or salmon are used in the soup. It is often served as a starter at formal Scottish dinners but is also widely served as a common dish across Scotland, especially in the northeast.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f6/Cullen_Skink.JPG/960px-Cullen_Skink.JPG`,page:`https://commons.wikimedia.org/wiki/File:Cullen_Skink.JPG`,artist:`Metukkalihis`,license:`CC BY-SA 3.0`}},"edinburgh/Cranachan":{wiki:{title:`Cranachan`,url:`https://en.wikipedia.org/wiki/Cranachan`,extract:`Cranachan is a traditional Scottish dessert. It was originally a celebration of harvest, made following the raspberry harvest in August. The dessert of cream and fresh seasonal raspberries is bolstered by Scottish oats and whisky. It has been called "the uncontested king of Scottish desserts".`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Cranachan_%284332953688%29.jpg/960px-Cranachan_%284332953688%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Cranachan_(4332953688).jpg`,artist:`Saskia van de Nieuwenhof from Edinburgh, United Kingdom`,license:`CC BY-SA 2.0`}},"edinburgh/Scotch Pie":{wiki:{title:`Scotch pie`,url:`https://en.wikipedia.org/wiki/Scotch_pie`,extract:`A Scotch pie is a meat pie, made with a hot water crust pastry, traditionally filled with minced mutton but now generally beef, sometimes lamb. It may also be known as a shell pie. The Scotch pie originated in Scotland, but can be found in other parts of the United Kingdom and abroad.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/Scotch_pie.jpg/960px-Scotch_pie.jpg`,page:`https://commons.wikimedia.org/wiki/File:Scotch_pie.jpg`,artist:`Delta-NC ( talk )`,license:`Public domain`}},"edinburgh/Full Scottish Breakfast":{wiki:{title:`Full breakfast`,url:`https://en.wikipedia.org/wiki/Full_breakfast`,extract:`A full breakfast or fry-up is a substantial cooked breakfast meal often made in Great Britain and Ireland. Depending on the region where it is served a full breakfast, or one of its variants, may also be referred to as a full English, full Scottish, full Welsh, full Irish fry up, or Ulster fry. Other variants of the full breakfast are made elsewhere.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Full_English_breakfast_%28cropped%29.jpg/960px-Full_English_breakfast_%28cropped%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Full_English_breakfast_(cropped).jpg`,artist:`Joadl`,license:`CC BY-SA 3.0 at`}},"edinburgh/Tablet":{wiki:{title:`Tablet (confectionery)`,url:`https://en.wikipedia.org/wiki/Tablet_(confectionery)`,extract:`Tablet is a medium-hard, sugary confection from Scotland. Tablet is usually made from sugar, condensed milk, and butter, which is boiled to a soft-ball stage and allowed to crystallise. It is often flavoured with vanilla and sometimes has nut pieces in it.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/Butter_tablet.JPG/960px-Butter_tablet.JPG`,page:`https://commons.wikimedia.org/wiki/File:Butter_tablet.JPG`,artist:`Seraphim Whipp at English Wikipedia`,license:`Public domain`}},"dish:French dip":{wiki:{title:`French dip`,url:`https://en.wikipedia.org/wiki/French_dip`,extract:`A French dip sandwich, also known as a beef dip, is a hot sandwich consisting of thinly sliced roast beef on a "French roll" or baguette.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/Roast_Beef_Dip_lunch.JPG/960px-Roast_Beef_Dip_lunch.JPG`,page:`https://commons.wikimedia.org/wiki/File:Roast_Beef_Dip_lunch.JPG`,artist:`Vranak`,license:`CC BY-SA 3.0`}},"dish:Pastrami on rye":{wiki:{title:`Pastrami on rye`,url:`https://en.wikipedia.org/wiki/Pastrami_on_rye`,extract:`Pastrami on rye is a sandwich comprising sliced pastrami on rye bread, often served with mustard and Kosher dill pickles. It was popularized in the Jewish delicatessens of New York City and has been described as New York's "signature sandwich". It was created in 1888 by the Lithuanian immigrant Sussman Volk, who served it at his deli on Delancey Street in Manhattan.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Pastrami-Sandwich.JPG/960px-Pastrami-Sandwich.JPG`,page:`https://commons.wikimedia.org/wiki/File:Pastrami-Sandwich.JPG`,artist:`Erika39`,license:`CC BY 3.0`}},"dish:Cochinita pibil":{wiki:{title:`Cochinita pibil`,url:`https://en.wikipedia.org/wiki/Cochinita_pibil`,extract:`Cochinita pibil is a traditional Yucatec Mayan slow-roasted pork dish from the Yucatán Peninsula of Mexico. Preparation of traditional cochinita involves marinating the meat in strongly acidic citrus juice, adding annatto seed, which imparts a vivid burnt orange color, and roasting the meat in a píib while it is wrapped in banana leaf.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/Cochinita_pibil_2.jpg/960px-Cochinita_pibil_2.jpg`,page:`https://commons.wikimedia.org/wiki/File:Cochinita_pibil_2.jpg`,artist:`Popo le Chien`,license:`CC BY-SA 3.0`}},"dish:Al pastor":{wiki:{title:`Al pastor`,url:`https://en.wikipedia.org/wiki/Al_pastor`,extract:`Al pastor, tacos al pastor, or tacos de trompo is a preparation of sliced, spit-grilled meat, usually pork, originating in the Central Mexican region of Puebla where they remain most prominent, though it is a common menu item found in taquerías throughout Mexico. The method of preparing and cooking al pastor is based on the lamb shawarma brought by Lebanese immigrants to the region.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/Tacos-al-Pastor.jpg/960px-Tacos-al-Pastor.jpg`,page:`https://commons.wikimedia.org/wiki/File:Tacos-al-Pastor.jpg`,artist:`Matt Saunders`,license:`CC BY-SA 3.0`}},"dish:Chili dog":{wiki:{title:`Chili dog`,url:`https://en.wikipedia.org/wiki/Chili_dog`,extract:`A chili dog is a savory hot dog served in a bun and topped with a meat sauce, usually chili con carne. Additional toppings may include cheese, onions, and mustard. The style has multiple regional variations in the United States, many calling for specific and unique sauce ingredients, types of hot dogs, or types of buns, and referred to regionally under region-specific names.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1a/Chili_dog_with_fries.jpg/960px-Chili_dog_with_fries.jpg`,page:`https://commons.wikimedia.org/wiki/File:Chili_dog_with_fries.jpg`,artist:`bryan... from Taipei, Taiwan`,license:`CC BY-SA 2.0`}},"dish:Kouign-amann":{wiki:{title:`Kouign-amann`,url:`https://en.wikipedia.org/wiki/Kouign-amann`,extract:`Kouign-amann is a sweet, round Breton laminated dough baked product, originally made with bread dough, but is also made with laminated viennoiserie dough, containing layers of butter and incorporated sugar. It is slowly baked until the sugar caramelizes and steam from the water in the butter expands the dough, resulting in its layered structure.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/8/85/Kouignamann.JPG/960px-Kouignamann.JPG`,page:`https://commons.wikimedia.org/wiki/File:Kouignamann.JPG`,artist:`Haltopub`,license:`Public domain`}},"dish:Shakshouka":{wiki:{title:`Shakshouka`,url:`https://en.wikipedia.org/wiki/Shakshouka`,extract:`Shakshouka is a Maghrebi dish of eggs poached in a sauce of tomatoes, olive oil, peppers, onion, and garlic, commonly spiced with cumin, paprika, and cayenne pepper. Shakshouka is a popular dish throughout North Africa and the Middle East.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/18/Shakshuka_by_Calliopejen1.jpg/960px-Shakshuka_by_Calliopejen1.jpg`,page:`https://commons.wikimedia.org/wiki/File:Shakshuka_by_Calliopejen1.jpg`,artist:`Calliopejen1`,license:`CC BY-SA 3.0`}},"dish:Galbi":{wiki:{title:`Galbi`,url:`https://en.wikipedia.org/wiki/Galbi`,extract:`Galbi, kalbi, galbi-gui (갈비구이), or grilled ribs is a type of gui in traditional Korean cuisine. "Galbi" is the Korean word for "rib", and the dish is usually made with beef short ribs. When pork spare ribs or another meat is used instead, the dish is named accordingly. Galbi is served raw, then cooked on tabletop grills usually by the diners themselves.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/Korean.food-Galbi-03.jpg/960px-Korean.food-Galbi-03.jpg`,page:`https://commons.wikimedia.org/wiki/File:Korean.food-Galbi-03.jpg`,artist:`ayustety (a flickr user)`,license:`CC BY-SA 2.0`}},"dish:Bibimbap":{wiki:{title:`Bibimbap`,url:`https://en.wikipedia.org/wiki/Bibimbap`,extract:`Bibimbap, sometimes romanised as bi bim bap or bi bim bop, is a Korean rice dish. It is served as a bowl of warm white rice topped with namul and gochujang. Egg and sliced meat are common additions, stirred together thoroughly just before eating. The term bibim means "mixing" and bap is cooked rice.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/44/Dolsot-bibimbap.jpg/960px-Dolsot-bibimbap.jpg`,page:`https://commons.wikimedia.org/wiki/File:Dolsot-bibimbap.jpg`,artist:`Sous Chef`,license:`CC BY 2.0`}},"los-angeles/Tacos al pastor":{wiki:{title:`Al pastor`,url:`https://en.wikipedia.org/wiki/Al_pastor`,extract:`Al pastor, tacos al pastor, or tacos de trompo is a preparation of sliced, spit-grilled meat, usually pork, originating in the Central Mexican region of Puebla where they remain most prominent, though it is a common menu item found in taquerías throughout Mexico. The method of preparing and cooking al pastor is based on the lamb shawarma brought by Lebanese immigrants to the region.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/Tacos-al-Pastor.jpg/960px-Tacos-al-Pastor.jpg`,page:`https://commons.wikimedia.org/wiki/File:Tacos-al-Pastor.jpg`,artist:`Matt Saunders`,license:`CC BY-SA 3.0`}},"los-angeles/French dip sandwich":{wiki:{title:`French dip`,url:`https://en.wikipedia.org/wiki/French_dip`,extract:`A French dip sandwich, also known as a beef dip, is a hot sandwich consisting of thinly sliced roast beef on a "French roll" or baguette.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/Roast_Beef_Dip_lunch.JPG/960px-Roast_Beef_Dip_lunch.JPG`,page:`https://commons.wikimedia.org/wiki/File:Roast_Beef_Dip_lunch.JPG`,artist:`Vranak`,license:`CC BY-SA 3.0`}},"los-angeles/Pastrami sandwich":{wiki:{title:`Pastrami`,url:`https://en.wikipedia.org/wiki/Pastrami`,extract:`Pastrami or pastromi is a type of cured meat in Jewish-American cuisine, originating in the Jewish community of Romania and surrounding regions, and usually made from beef brisket. The raw meat is brined, partially dried, seasoned with herbs and spices, then smoked and steamed.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/Ben%27s_Best_Deli_Rego_Park_pastrami_sandwich.jpg/960px-Ben%27s_Best_Deli_Rego_Park_pastrami_sandwich.jpg`,page:`https://commons.wikimedia.org/wiki/File:Ben%27s_Best_Deli_Rego_Park_pastrami_sandwich.jpg`,artist:`Jeff`,license:`CC BY-SA 2.0`}},"los-angeles/Korean barbecue":{wiki:{title:`Korean barbecue`,url:`https://en.wikipedia.org/wiki/Korean_barbecue`,extract:`Korean barbecue is a popular method in Korean cuisine of grilling meat, typically beef, pork or chicken. Such dishes are often prepared on gas or charcoal grills built into the dining table itself, though some restaurants provide customers with portable stoves for diners to use at their tables. Alternatively, a chef uses a centrally displayed grill to prepare dishes that are made to order.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/63/Korean_BBQ_Seoul.jpg/960px-Korean_BBQ_Seoul.jpg`,page:`https://commons.wikimedia.org/wiki/File:Korean_BBQ_Seoul.jpg`,artist:`kallerna`,license:`CC BY-SA 4.0`}},"los-angeles/Chili dog":{wiki:{title:`Chili dog`,url:`https://en.wikipedia.org/wiki/Chili_dog`,extract:`A chili dog is a savory hot dog served in a bun and topped with a meat sauce, usually chili con carne. Additional toppings may include cheese, onions, and mustard. The style has multiple regional variations in the United States, many calling for specific and unique sauce ingredients, types of hot dogs, or types of buns, and referred to regionally under region-specific names.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1a/Chili_dog_with_fries.jpg/960px-Chili_dog_with_fries.jpg`,page:`https://commons.wikimedia.org/wiki/File:Chili_dog_with_fries.jpg`,artist:`bryan... from Taipei, Taiwan`,license:`CC BY-SA 2.0`}},"los-angeles/California roll":{wiki:{title:`California roll`,url:`https://en.wikipedia.org/wiki/California_roll`,extract:`California roll , or California maki is a type of sushi that contains imitation crab, avocado, and cucumber. Sometimes crab salad is substituted for the crab stick. In America it comes as uramaki and often the outer layer of rice is sprinkled with toasted sesame seeds or roe. Outside America, California rolls may be closer to the traditional design or futomaki, with nori seaweed on the outside.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9f/California_Sushi_%2826571101885%29.jpg/960px-California_Sushi_%2826571101885%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:California_Sushi_(26571101885).jpg`,artist:`Tim Reckmann from Hamm, Deutschland`,license:`CC BY 2.0`}},"dish:Bagel and cream cheese":{wiki:{title:`Bagel and cream cheese`,url:`https://en.wikipedia.org/wiki/Bagel_and_cream_cheese`,extract:`A bagel and cream cheese is a food pairing that consists, in its basic form, of a sliced bagel spread with cream cheese. Bagels with cream cheese are most traditionally served open-faced and spread with cream cheese and other toppings.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/NCI_cream_cheese_bagel.jpg/960px-NCI_cream_cheese_bagel.jpg`,page:`https://commons.wikimedia.org/wiki/File:NCI_cream_cheese_bagel.jpg`,artist:`Renee Comet`,license:`Public domain`}},"dish:New York–style pizza":{wiki:{title:`New York–style pizza`,url:`https://en.wikipedia.org/wiki/New_York%E2%80%93style_pizza`,extract:`New York–style pizza is a pizza made with a large hand-tossed thin crust, often sold in wide slices to go. The crust is thick and crisp only along its edge, yet soft, thin, and pliable enough beneath its toppings to be folded to eat. Traditional toppings are simply tomato sauce and shredded mozzarella cheese. This was a popular meal among poor Italian Americans due to its low cost.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/NYPizzaPie.jpg/960px-NYPizzaPie.jpg`,page:`https://commons.wikimedia.org/wiki/File:NYPizzaPie.jpg`,artist:`Hungrydudes`,license:`CC BY 2.0`}},"dish:Cheesecake":{wiki:{title:`Cheesecake`,url:`https://en.wikipedia.org/wiki/Cheesecake`,extract:`Cheesecake is a dessert made with a soft fresh cheese, and sugar, with either eggs or cream depending if it is to be baked or not. It may have a crust or base made from crushed cookies, digestive biscuits, graham crackers, pastry, or sometimes sponge cake. Cheesecake is known for its rich, creamy flavor and smooth texture. It may be baked or unbaked and is usually served chilled.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/Baked_cheesecake_with_raspberries_and_blueberries.jpg/960px-Baked_cheesecake_with_raspberries_and_blueberries.jpg`,page:`https://commons.wikimedia.org/wiki/File:Baked_cheesecake_with_raspberries_and_blueberries.jpg`,artist:`zingyyellow`,license:`CC BY 2.0`}},"dish:Reuben sandwich":{wiki:{title:`Reuben sandwich`,url:`https://en.wikipedia.org/wiki/Reuben_sandwich`,extract:`The Reuben sandwich is an American grilled sandwich comprising corned beef, Swiss cheese, sauerkraut, and Russian dressing or Thousand Island dressing, grilled between slices of rye bread. The sandwich is traditionally grilled or toasted until the bread is crisp and the cheese has melted.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8c/Katz%27s_Deli_-_Lunch.jpg/960px-Katz%27s_Deli_-_Lunch.jpg`,page:`https://commons.wikimedia.org/wiki/File:Katz%27s_Deli_-_Lunch.jpg`,artist:`Ernesto Andrade`,license:`CC BY 2.0`}},"dish:Taco":{wiki:{title:`Taco`,url:`https://en.wikipedia.org/wiki/Taco`,extract:`A taco is a traditional Mexican dish consisting of a small hand-sized corn- or wheat-based tortilla topped with a filling. The tortilla is then folded around the filling and eaten by hand. A taco can be made with a variety of fillings, including beef, pork, chicken, seafood, beans, vegetables, and cheese, and garnished with various condiments, such as salsa, guacamole, or sour cream, and vegetables, such as lettuce,…`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/7/73/001_Tacos_de_carnitas%2C_carne_asada_y_al_pastor.jpg/960px-001_Tacos_de_carnitas%2C_carne_asada_y_al_pastor.jpg`,page:`https://commons.wikimedia.org/wiki/File:001_Tacos_de_carnitas,_carne_asada_y_al_pastor.jpg`,artist:`Larry Miller`,license:`CC BY-SA 2.0`}},"dish:Lobster roll":{wiki:{title:`Lobster roll`,url:`https://en.wikipedia.org/wiki/Lobster_roll`,extract:`A lobster roll is a North American dish comprising lobster meat served on a grilled hot dog–style bun, commonly credited to have been invented in Milford, Connecticut. The filling may also contain butter, lemon juice, salt, and black pepper, with variants made in some parts of New England replacing the butter with mayonnaise. Other versions may contain diced celery or scallion.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/63/Lobster_Roll.png/960px-Lobster_Roll.png`,page:`https://commons.wikimedia.org/wiki/File:Lobster_Roll.png`,artist:`Maguy23`,license:`CC BY-SA 4.0`}},"dish:Chocolate chip cookie":{wiki:{title:`Chocolate chip cookie`,url:`https://en.wikipedia.org/wiki/Chocolate_chip_cookie`,extract:`A chocolate chip cookie is a drop cookie that contains pieces of chocolate mixed into the dough before baking. Texture and appearance vary with ingredients and preparation, ranging from moist, chewy cookies to ones that are crispy.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/b/b4/Choco_chip_cookie.png`,page:`https://commons.wikimedia.org/wiki/File:Choco_chip_cookie.png`,artist:`brainloc on sxc.hu (Bob Smith)`,license:`CC BY 2.5`}},"new-york/New York-style pizza":{wiki:{title:`New York–style pizza`,url:`https://en.wikipedia.org/wiki/New_York%E2%80%93style_pizza`,extract:`New York–style pizza is a pizza made with a large hand-tossed thin crust, often sold in wide slices to go. The crust is thick and crisp only along its edge, yet soft, thin, and pliable enough beneath its toppings to be folded to eat. Traditional toppings are simply tomato sauce and shredded mozzarella cheese. This was a popular meal among poor Italian Americans due to its low cost.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/NYPizzaPie.jpg/960px-NYPizzaPie.jpg`,page:`https://commons.wikimedia.org/wiki/File:NYPizzaPie.jpg`,artist:`Hungrydudes`,license:`CC BY 2.0`}},"new-york/Bagel with lox and schmear":{wiki:{title:`Bagel and cream cheese`,url:`https://en.wikipedia.org/wiki/Bagel_and_cream_cheese`,extract:`A bagel and cream cheese is a food pairing that consists, in its basic form, of a sliced bagel spread with cream cheese. Bagels with cream cheese are most traditionally served open-faced and spread with cream cheese and other toppings.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/NCI_cream_cheese_bagel.jpg/960px-NCI_cream_cheese_bagel.jpg`,page:`https://commons.wikimedia.org/wiki/File:NCI_cream_cheese_bagel.jpg`,artist:`Renee Comet`,license:`Public domain`}},"new-york/Pastrami on rye":{wiki:{title:`Pastrami on rye`,url:`https://en.wikipedia.org/wiki/Pastrami_on_rye`,extract:`Pastrami on rye is a sandwich comprising sliced pastrami on rye bread, often served with mustard and Kosher dill pickles. It was popularized in the Jewish delicatessens of New York City and has been described as New York's "signature sandwich". It was created in 1888 by the Lithuanian immigrant Sussman Volk, who served it at his deli on Delancey Street in Manhattan.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Pastrami-Sandwich.JPG/960px-Pastrami-Sandwich.JPG`,page:`https://commons.wikimedia.org/wiki/File:Pastrami-Sandwich.JPG`,artist:`Erika39`,license:`CC BY 3.0`}},"new-york/New York cheesecake":{wiki:{title:`Cheesecake`,url:`https://en.wikipedia.org/wiki/Cheesecake`,extract:`Cheesecake is a dessert made with a soft fresh cheese, and sugar, with either eggs or cream depending if it is to be baked or not. It may have a crust or base made from crushed cookies, digestive biscuits, graham crackers, pastry, or sometimes sponge cake. Cheesecake is known for its rich, creamy flavor and smooth texture. It may be baked or unbaked and is usually served chilled.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/Baked_cheesecake_with_raspberries_and_blueberries.jpg/960px-Baked_cheesecake_with_raspberries_and_blueberries.jpg`,page:`https://commons.wikimedia.org/wiki/File:Baked_cheesecake_with_raspberries_and_blueberries.jpg`,artist:`zingyyellow`,license:`CC BY 2.0`}},"new-york/Halal cart chicken over rice":{wiki:{title:`Halal cart`,url:`https://en.wikipedia.org/wiki/Halal_cart`,extract:`A halal cart is a food cart which serves primarily halal food, particularly in New York City, but also in other metropolitan areas in the United States. A halal cart platter consists of chicken shawarma or lamb gyro, yellow rice, and salad, with optional red and/or white sauce on top. The red sauce is believed to derive from harissa, while the white sauce may come khyar bi Laban.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/Shah%27s_halal_food_cart_20181010_111456.jpg/960px-Shah%27s_halal_food_cart_20181010_111456.jpg`,page:`https://commons.wikimedia.org/wiki/File:Shah%27s_halal_food_cart_20181010_111456.jpg`,artist:`CaptJayRuffins`,license:`CC BY-SA 4.0`}},"new-york/Black-and-white cookie":{wiki:{title:`Black and white cookie`,url:`https://en.wikipedia.org/wiki/Black_and_white_cookie`,extract:`Black-and-white cookies, half-and-half cookies, and half-moon cookies are round cookies iced or frosted in two colors, with one half vanilla and the other chocolate. They are found in the Northeastern United States and Florida. Black-and-white cookies are flat, have fondant or sometimes royal icing on a dense cake base, and are common in the New York metropolitan area.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/7/73/BandW.jpg`,page:`https://commons.wikimedia.org/wiki/File:BandW.jpg`,artist:`Punkitra at English Wikipedia`,license:`Public domain`}},"dish:Mission burrito":{wiki:{title:`Mission burrito`,url:`https://en.wikipedia.org/wiki/Mission_burrito`,extract:`A Mission burrito is a type of burrito that first became popular during the 1960s in the Mission District of San Francisco, California. It is distinguished from other burritos by its large size and inclusion of rice and other ingredients.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/17/Shredded_pork_burrito.jpg/960px-Shredded_pork_burrito.jpg`,page:`https://commons.wikimedia.org/wiki/File:Shredded_pork_burrito.jpg`,artist:`Swift Benjamin from Campbell, ca, United States`,license:`CC BY 2.0`}},"dish:Dungeness crab":{wiki:{title:`Dungeness crab`,url:`https://en.wikipedia.org/wiki/Dungeness_crab`,extract:`The Dungeness crab is a species of crab in the family Cancridae. It makes up one of the most important seafood industries along the west coast of North America. Its typical range extends from Alaska's Aleutian Islands to Point Conception, near Santa Barbara, California. Dungeness typically grow 6–7 in (150–180 mm) at their widest point and inhabit eelgrass beds and sandy bottoms.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/DungenessCrab.jpg/960px-DungenessCrab.jpg`,page:`https://commons.wikimedia.org/wiki/File:DungenessCrab.jpg`,artist:`Dan Boone`,license:`Public domain`}},"dish:Clam chowder":{wiki:{title:`Clam chowder`,url:`https://en.wikipedia.org/wiki/Clam_chowder`,extract:`Clam chowder is any of several chowder soups in American cuisine containing clams. In addition to clams, common ingredients include diced potatoes, salt pork, and onions. It is believed that clams were used in chowder because of the relative ease of harvesting them. Clam chowder is usually served with saltine crackers or small, hexagonal oyster crackers.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/Quail_07_bg_041506.jpg/960px-Quail_07_bg_041506.jpg`,page:`https://commons.wikimedia.org/wiki/File:Quail_07_bg_041506.jpg`,artist:`Jon Sullivan The original uploader was Y6y6y6 at English Wikipedia .`,license:`Public domain`}},"dish:Cioppino":{wiki:{title:`Cioppino`,url:`https://en.wikipedia.org/wiki/Cioppino`,extract:`Cioppino is a fish stew originating in San Francisco, California, a dish in Italian-American cuisine related to various fish soups in Italian cuisine.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/7/73/Cioppino.jpg`,page:`https://commons.wikimedia.org/wiki/File:Cioppino.jpg`,artist:`Kelly Sue DeConnick`,license:`CC BY-SA 2.0`}},"dish:Char siu bao":{wiki:{title:`Cha siu bao`,url:`https://en.wikipedia.org/wiki/Cha_siu_bao`,extract:`Cha siu bao is a Cantonese baozi (bun) filled with barbecue-flavored cha siu pork. They are served as a type of dim sum during yum cha and are sometimes sold in Chinese bakeries.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6c/Char_siu_bao.jpg/960px-Char_siu_bao.jpg`,page:`https://commons.wikimedia.org/wiki/File:Char_siu_bao.jpg`,artist:`Takeaway`,license:`CC BY-SA 3.0`}},"dish:Har gow":{wiki:{title:`Har gow`,url:`https://en.wikipedia.org/wiki/Har_gow`,extract:`Har gow, also anglicized as ha gow, hau kau, or ha kao, is a traditional Cantonese dumpling served as dim sum. It is made of shrimp meat, and steamed in a flour wrapper. After cooking, the wrapper becomes somewhat translucent, and therefore ha gow is sometimes called crystal shrimp dumplings (水晶蝦餃).`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/9/94/Steamed_prawn_dumplings.jpg/960px-Steamed_prawn_dumplings.jpg`,page:`https://commons.wikimedia.org/wiki/File:Steamed_prawn_dumplings.jpg`,artist:`Maksym Kozlenko`,license:`CC BY-SA 4.0`}},"dish:Irish coffee":{wiki:{title:`Irish coffee`,url:`https://en.wikipedia.org/wiki/Irish_coffee`,extract:`Irish coffee is a caffeinated alcoholic drink consisting of Irish whiskey, hot coffee and sugar, which has been stirred and topped with cream. The coffee is drunk through the cream.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Irish_coffee_glass.jpg/960px-Irish_coffee_glass.jpg`,page:`https://commons.wikimedia.org/wiki/File:Irish_coffee_glass.jpg`,artist:`jules / stone soup`,license:`CC BY 2.0`}},"dish:Eggs Benedict":{wiki:{title:`Eggs Benedict`,url:`https://en.wikipedia.org/wiki/Eggs_Benedict`,extract:`Eggs Benedict is a common American breakfast or brunch dish, consisting of two halves of an English muffin, each topped with Canadian bacon or sliced ham, a poached egg, and hollandaise sauce. The dish is believed to have originated in New York City, although a number of different origin stories exist.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Traditional_Eggs_Benedict.jpg/960px-Traditional_Eggs_Benedict.jpg`,page:`https://commons.wikimedia.org/wiki/File:Traditional_Eggs_Benedict.jpg`,artist:`Mark Miller`,license:`CC BY-SA 4.0`}},"dish:Caesar salad":{wiki:{title:`Caesar salad`,url:`https://en.wikipedia.org/wiki/Caesar_salad`,extract:`A Caesar salad, also known as Caesar's salad, is a green salad of romaine lettuce and croutons commonly dressed with lemon juice, olive oil, eggs, Worcestershire sauce, anchovies, garlic, Dijon mustard, Parmesan and black pepper.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Caesar_salad_%282%29.jpg/960px-Caesar_salad_%282%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Caesar_salad_(2).jpg`,artist:`Geoff Peters from Vancouver, BC, Canada`,license:`CC BY 2.0`}},"dish:French fries":{wiki:{title:`French fries`,url:`https://en.wikipedia.org/wiki/French_fries`,extract:`French fries, or simply fries, also known as French fried potatoes, chips, and finger chips, are batonnet or julienne-cut deep-fried potatoes of disputed origin. They are prepared by cutting potatoes into even strips, drying them, and frying them, usually in a deep fryer. Pre-cut, blanched, and frozen russet potatoes are widely used, and sometimes baked in a regular or convection oven, such as an air fryer.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/8/83/French_Fries.JPG`,page:`https://commons.wikimedia.org/wiki/File:French_Fries.JPG`,artist:`StockSnap`,license:`CC0`}},"san-francisco/Sourdough bread":{wiki:{title:`Sourdough`,url:`https://en.wikipedia.org/wiki/Sourdough`,extract:`Sourdough is a leavening agent containing naturally occurring yeast and lactobacillus bacteria. The term is used to describe bread baked with sourdough, while the sourdough itself is referred to as a starter. In addition to leavening the bread, the fermentation process produces lactic acid, which gives the bread its distinctive sour taste and improves its keeping qualities.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/Home_made_sour_dough_bread.jpg/960px-Home_made_sour_dough_bread.jpg`,page:`https://commons.wikimedia.org/wiki/File:Home_made_sour_dough_bread.jpg`,artist:`Tomascastelazo`,license:`CC BY-SA 4.0`}},"san-francisco/Mission burrito":{wiki:{title:`Mission burrito`,url:`https://en.wikipedia.org/wiki/Mission_burrito`,extract:`A Mission burrito is a type of burrito that first became popular during the 1960s in the Mission District of San Francisco, California. It is distinguished from other burritos by its large size and inclusion of rice and other ingredients.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/17/Shredded_pork_burrito.jpg/960px-Shredded_pork_burrito.jpg`,page:`https://commons.wikimedia.org/wiki/File:Shredded_pork_burrito.jpg`,artist:`Swift Benjamin from Campbell, ca, United States`,license:`CC BY 2.0`}},"san-francisco/Dungeness crab":{wiki:{title:`Dungeness crab`,url:`https://en.wikipedia.org/wiki/Dungeness_crab`,extract:`The Dungeness crab is a species of crab in the family Cancridae. It makes up one of the most important seafood industries along the west coast of North America. Its typical range extends from Alaska's Aleutian Islands to Point Conception, near Santa Barbara, California. Dungeness typically grow 6–7 in (150–180 mm) at their widest point and inhabit eelgrass beds and sandy bottoms.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/DungenessCrab.jpg/960px-DungenessCrab.jpg`,page:`https://commons.wikimedia.org/wiki/File:DungenessCrab.jpg`,artist:`Dan Boone`,license:`Public domain`}},"san-francisco/Cioppino":{wiki:{title:`Cioppino`,url:`https://en.wikipedia.org/wiki/Cioppino`,extract:`Cioppino is a fish stew originating in San Francisco, California, a dish in Italian-American cuisine related to various fish soups in Italian cuisine.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/7/73/Cioppino.jpg`,page:`https://commons.wikimedia.org/wiki/File:Cioppino.jpg`,artist:`Kelly Sue DeConnick`,license:`CC BY-SA 2.0`}},"san-francisco/Dim sum":{wiki:{title:`Dim sum`,url:`https://en.wikipedia.org/wiki/Dim_sum`,extract:`Dim sum is a large range of small Chinese dishes that are traditionally eaten in restaurants for brunch. Most modern dim sum dishes are commonly associated with Cantonese cuisine, although dim sum dishes also exist in a few other Chinese cuisines.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/Chinese_DimSum_%289023590541%29.jpg/960px-Chinese_DimSum_%289023590541%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Chinese_DimSum_(9023590541).jpg`,artist:`LeonardKong`,license:`CC BY 2.0`}},"san-francisco/Irish coffee at the Buena Vista":{wiki:{title:`Irish coffee`,url:`https://en.wikipedia.org/wiki/Irish_coffee`,extract:`Irish coffee is a caffeinated alcoholic drink consisting of Irish whiskey, hot coffee and sugar, which has been stirred and topped with cream. The coffee is drunk through the cream.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Irish_coffee_glass.jpg/960px-Irish_coffee_glass.jpg`,page:`https://commons.wikimedia.org/wiki/File:Irish_coffee_glass.jpg`,artist:`jules / stone soup`,license:`CC BY 2.0`}},"dish:Mì Quảng":{wiki:{title:`Mì Quảng`,url:`https://en.wikipedia.org/wiki/M%C3%AC_Qu%E1%BA%A3ng`,extract:`Mì Quảng, literally "Quảng noodles", is a Vietnamese noodle dish that originated in Quảng Nam Province in central Vietnam. It is one of the region's most popular and well recognized food items, and is served on various occasions, like at family parties, death anniversaries, and Tết. It originated in the Ðà Nẵng and Quảng Nam area and has become available throughout the country, and is eaten at any time of the day.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/M%C3%AC_Qu%E1%BA%A3ng%2C_Da_Nang%2C_Vietnam.jpg/960px-M%C3%AC_Qu%E1%BA%A3ng%2C_Da_Nang%2C_Vietnam.jpg`,page:`https://commons.wikimedia.org/wiki/File:M%C3%AC_Qu%E1%BA%A3ng,_Da_Nang,_Vietnam.jpg`,artist:`Christopher Crouzet`,license:`CC BY-SA 4.0`}},"dish:Bánh xèo":{wiki:{title:`Bánh xèo`,url:`https://en.wikipedia.org/wiki/B%C3%A1nh_x%C3%A8o`,extract:`Bánh xèo is a crispy, stuffed rice crepe popular in Vietnam. The name refers to the sound a thin layer of rice batter makes when it is poured into the hot skillet. It is a savoury fried pancake made of rice flour, water, and turmeric powder. It can also be called a Vietnamese crêpe. Some common stuffings include pork, prawns, diced green onion, mung bean, and bean sprouts. Bánh xèo is often served with side dishes.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/5/59/Banh_Xeo_with_fish_sauce_and_vegetables.jpg`,page:`https://commons.wikimedia.org/wiki/File:Banh_Xeo_with_fish_sauce_and_vegetables.jpg`,artist:`HungryHuy`,license:`CC BY 2.0`}},"dish:Bánh mì":{wiki:{title:`Bánh mì`,url:`https://en.wikipedia.org/wiki/B%C3%A1nh_m%C3%AC`,extract:`In Vietnamese cuisine, bánh mì, bánh mỳ or banh mi, is a short baguette with thin, crisp crust and a soft, airy texture. Similar to a submarine sandwich, it is often split lengthwise and filled with meat and savory ingredients and served as a meal, called bánh mì thịt. Plain bánh mì is also eaten as a staple food.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/0/0c/B%C3%A1nh_m%C3%AC_th%E1%BB%8Bt_n%C6%B0%E1%BB%9Bng.png`,page:`https://commons.wikimedia.org/wiki/File:B%C3%A1nh_m%C3%AC_th%E1%BB%8Bt_n%C6%B0%E1%BB%9Bng.png`,artist:`nsaum75 ¡שיחת! ‎`,license:`CC BY-SA 3.0`}},"dish:Cao lầu":{wiki:{title:`Cao lầu`,url:`https://en.wikipedia.org/wiki/Cao_l%E1%BA%A7u`,extract:`Cao lầu is a regional Vietnamese noodle dish, from the city of Hội An, in the central Vietnamese municipality of Da Nang. It typically consists of pork and greens on a bed of rice noodles made from rice which has been soaked in lye water, giving them a characteristic texture and colour that sets the dish apart from other Vietnamese noodle dishes, including others from the same region, such as mì Quảng.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4e/Cao_l%E1%BA%A7u_H%E1%BB%99i_An_%282024%29.jpg/960px-Cao_l%E1%BA%A7u_H%E1%BB%99i_An_%282024%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Cao_l%E1%BA%A7u_H%E1%BB%99i_An_(2024).jpg`,artist:`Chainwit.`,license:`CC BY 4.0`}},"da-nang/Mi Quang":{wiki:{title:`Mì Quảng`,url:`https://en.wikipedia.org/wiki/M%C3%AC_Qu%E1%BA%A3ng`,extract:`Mì Quảng, literally "Quảng noodles", is a Vietnamese noodle dish that originated in Quảng Nam Province in central Vietnam. It is one of the region's most popular and well recognized food items, and is served on various occasions, like at family parties, death anniversaries, and Tết. It originated in the Ðà Nẵng and Quảng Nam area and has become available throughout the country, and is eaten at any time of the day.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/M%C3%AC_Qu%E1%BA%A3ng%2C_Da_Nang%2C_Vietnam.jpg/960px-M%C3%AC_Qu%E1%BA%A3ng%2C_Da_Nang%2C_Vietnam.jpg`,page:`https://commons.wikimedia.org/wiki/File:M%C3%AC_Qu%E1%BA%A3ng,_Da_Nang,_Vietnam.jpg`,artist:`Christopher Crouzet`,license:`CC BY-SA 4.0`}},"da-nang/Cao Lau":{wiki:{title:`Cao lầu`,url:`https://en.wikipedia.org/wiki/Cao_l%E1%BA%A7u`,extract:`Cao lầu is a regional Vietnamese noodle dish, from the city of Hội An, in the central Vietnamese municipality of Da Nang. It typically consists of pork and greens on a bed of rice noodles made from rice which has been soaked in lye water, giving them a characteristic texture and colour that sets the dish apart from other Vietnamese noodle dishes, including others from the same region, such as mì Quảng.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4e/Cao_l%E1%BA%A7u_H%E1%BB%99i_An_%282024%29.jpg/960px-Cao_l%E1%BA%A7u_H%E1%BB%99i_An_%282024%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Cao_l%E1%BA%A7u_H%E1%BB%99i_An_(2024).jpg`,artist:`Chainwit.`,license:`CC BY 4.0`}},"da-nang/Banh Xeo":{wiki:{title:`Bánh xèo`,url:`https://en.wikipedia.org/wiki/B%C3%A1nh_x%C3%A8o`,extract:`Bánh xèo is a crispy, stuffed rice crepe popular in Vietnam. The name refers to the sound a thin layer of rice batter makes when it is poured into the hot skillet. It is a savoury fried pancake made of rice flour, water, and turmeric powder. It can also be called a Vietnamese crêpe. Some common stuffings include pork, prawns, diced green onion, mung bean, and bean sprouts. Bánh xèo is often served with side dishes.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/5/59/Banh_Xeo_with_fish_sauce_and_vegetables.jpg`,page:`https://commons.wikimedia.org/wiki/File:Banh_Xeo_with_fish_sauce_and_vegetables.jpg`,artist:`HungryHuy`,license:`CC BY 2.0`}},"dish:Pho":{wiki:{title:`Pho`,url:`https://en.wikipedia.org/wiki/Pho`,extract:`Pho is a Vietnamese soup dish consisting of broth, rice noodles, herbs, and meat – usually beef, and sometimes chicken. Pho is a popular food in Vietnam where it is served in households, street-stalls, and restaurants nationwide. Residents of the city of Nam Định were the first to create Vietnamese traditional pho.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/52/Bowl_of_Meatball_pho.jpg/960px-Bowl_of_Meatball_pho.jpg`,page:`https://commons.wikimedia.org/wiki/File:Bowl_of_Meatball_pho.jpg`,artist:`SerraKnightz`,license:`CC BY 4.0`}},"dish:Bún chả":{wiki:{title:`Bun cha`,url:`https://en.wikipedia.org/wiki/Bun_cha`,extract:`Bún chả is a Vietnamese dish of grilled pork and noodles, which is thought to have originated from Hanoi, Vietnam. Bún chả is served with grilled fatty pork (chả) over a plate of white rice noodles (bún) and herbs with a side dish of dipping sauce. The dish was described in 1959 by Vietnamese food writer Vũ Bằng (1913–1984), who described Hanoi as a town "transfixed by bún chả".`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/B%C3%BAn_ch%E1%BA%A3_Vietnamese_food.jpg/960px-B%C3%BAn_ch%E1%BA%A3_Vietnamese_food.jpg`,page:`https://commons.wikimedia.org/wiki/File:B%C3%BAn_ch%E1%BA%A3_Vietnamese_food.jpg`,artist:`stuart_spivack`,license:`CC BY 2.0`}},"dish:Chả cá Lã Vọng":{wiki:{title:`Chả cá Lã Vọng`,url:`https://en.wikipedia.org/wiki/Ch%E1%BA%A3_c%C3%A1_L%C3%A3_V%E1%BB%8Dng`,extract:`Cha ca La Vong is a Vietnamese grilled fish dish originally from Hanoi. The dish is traditionally made with hemibagrus, which is a genus of catfish. The fish is cut into pieces and marinated with turmeric, galangal, fermented rice and other ingredients. It is then grilled over charcoal and served at the table in a hot pan coated with oil with scallion and dill.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8a/Ch%E1%BA%A3_c%C3%A1_L%C3%A3_V%E1%BB%8Dng_H%C3%A0_N%E1%BB%99i.jpg/960px-Ch%E1%BA%A3_c%C3%A1_L%C3%A3_V%E1%BB%8Dng_H%C3%A0_N%E1%BB%99i.jpg`,page:`https://commons.wikimedia.org/wiki/File:Ch%E1%BA%A3_c%C3%A1_L%C3%A3_V%E1%BB%8Dng_H%C3%A0_N%E1%BB%99i.jpg`,artist:`Phương Huy ( thảo luận )`,license:`Public domain`}},"dish:Egg coffee":{wiki:{title:`Egg coffee`,url:`https://en.wikipedia.org/wiki/Egg_coffee`,extract:`Egg coffee is a Vietnamese drink traditionally prepared with egg yolks, sugar, condensed milk and robusta coffee. The drink is made by filtering coffee beans in a phin, and beating egg yolks with sugar and condensed milk over heat to get egg-cream component.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/22/C%C3%A0_ph%C3%AA_tr%E1%BB%A9ng.jpg/960px-C%C3%A0_ph%C3%AA_tr%E1%BB%A9ng.jpg`,page:`https://commons.wikimedia.org/wiki/File:C%C3%A0_ph%C3%AA_tr%E1%BB%A9ng.jpg`,artist:`travel oriented`,license:`CC BY-SA 2.0`}},"dish:Bánh cuốn":{wiki:{title:`Bánh cuốn`,url:`https://en.wikipedia.org/wiki/B%C3%A1nh_cu%E1%BB%91n`,extract:`Bánh cuốn or bánh quấn is a Vietnamese dish originating from Northern Vietnam.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b2/B%C3%A1nh_cu%E1%BB%91n_Thanh_Tr%C3%AC.jpg/960px-B%C3%A1nh_cu%E1%BB%91n_Thanh_Tr%C3%AC.jpg`,page:`https://commons.wikimedia.org/wiki/File:B%C3%A1nh_cu%E1%BB%91n_Thanh_Tr%C3%AC.jpg`,artist:`Casablanca1911 at vi.wikipedia`,license:`Public domain`}},"hanoi/Pho Bo":{wiki:{title:`Pho`,url:`https://en.wikipedia.org/wiki/Pho`,extract:`Pho is a Vietnamese soup dish consisting of broth, rice noodles, herbs, and meat – usually beef, and sometimes chicken. Pho is a popular food in Vietnam where it is served in households, street-stalls, and restaurants nationwide. Residents of the city of Nam Định were the first to create Vietnamese traditional pho.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/5/52/Bowl_of_Meatball_pho.jpg/960px-Bowl_of_Meatball_pho.jpg`,page:`https://commons.wikimedia.org/wiki/File:Bowl_of_Meatball_pho.jpg`,artist:`SerraKnightz`,license:`CC BY 4.0`}},"hanoi/Bun Cha":{wiki:{title:`Bun cha`,url:`https://en.wikipedia.org/wiki/Bun_cha`,extract:`Bún chả is a Vietnamese dish of grilled pork and noodles, which is thought to have originated from Hanoi, Vietnam. Bún chả is served with grilled fatty pork (chả) over a plate of white rice noodles (bún) and herbs with a side dish of dipping sauce. The dish was described in 1959 by Vietnamese food writer Vũ Bằng (1913–1984), who described Hanoi as a town "transfixed by bún chả".`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/B%C3%BAn_ch%E1%BA%A3_Vietnamese_food.jpg/960px-B%C3%BAn_ch%E1%BA%A3_Vietnamese_food.jpg`,page:`https://commons.wikimedia.org/wiki/File:B%C3%BAn_ch%E1%BA%A3_Vietnamese_food.jpg`,artist:`stuart_spivack`,license:`CC BY 2.0`}},"hanoi/Cha Ca La Vong":{wiki:{title:`Chả cá Lã Vọng`,url:`https://en.wikipedia.org/wiki/Ch%E1%BA%A3_c%C3%A1_L%C3%A3_V%E1%BB%8Dng`,extract:`Cha ca La Vong is a Vietnamese grilled fish dish originally from Hanoi. The dish is traditionally made with hemibagrus, which is a genus of catfish. The fish is cut into pieces and marinated with turmeric, galangal, fermented rice and other ingredients. It is then grilled over charcoal and served at the table in a hot pan coated with oil with scallion and dill.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8a/Ch%E1%BA%A3_c%C3%A1_L%C3%A3_V%E1%BB%8Dng_H%C3%A0_N%E1%BB%99i.jpg/960px-Ch%E1%BA%A3_c%C3%A1_L%C3%A3_V%E1%BB%8Dng_H%C3%A0_N%E1%BB%99i.jpg`,page:`https://commons.wikimedia.org/wiki/File:Ch%E1%BA%A3_c%C3%A1_L%C3%A3_V%E1%BB%8Dng_H%C3%A0_N%E1%BB%99i.jpg`,artist:`Phương Huy ( thảo luận )`,license:`Public domain`}},"hanoi/Egg Coffee":{wiki:{title:`Egg coffee`,url:`https://en.wikipedia.org/wiki/Egg_coffee`,extract:`Egg coffee is a Vietnamese drink traditionally prepared with egg yolks, sugar, condensed milk and robusta coffee. The drink is made by filtering coffee beans in a phin, and beating egg yolks with sugar and condensed milk over heat to get egg-cream component.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/22/C%C3%A0_ph%C3%AA_tr%E1%BB%A9ng.jpg/960px-C%C3%A0_ph%C3%AA_tr%E1%BB%A9ng.jpg`,page:`https://commons.wikimedia.org/wiki/File:C%C3%A0_ph%C3%AA_tr%E1%BB%A9ng.jpg`,artist:`travel oriented`,license:`CC BY-SA 2.0`}},"hanoi/Banh Cuon":{wiki:{title:`Bánh cuốn`,url:`https://en.wikipedia.org/wiki/B%C3%A1nh_cu%E1%BB%91n`,extract:`Bánh cuốn or bánh quấn is a Vietnamese dish originating from Northern Vietnam.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b2/B%C3%A1nh_cu%E1%BB%91n_Thanh_Tr%C3%AC.jpg/960px-B%C3%A1nh_cu%E1%BB%91n_Thanh_Tr%C3%AC.jpg`,page:`https://commons.wikimedia.org/wiki/File:B%C3%A1nh_cu%E1%BB%91n_Thanh_Tr%C3%AC.jpg`,artist:`Casablanca1911 at vi.wikipedia`,license:`Public domain`}},"dish:Cơm tấm":{wiki:{title:`Cơm tấm`,url:`https://en.wikipedia.org/wiki/C%C6%A1m_t%E1%BA%A5m`,extract:`Cơm tấm, also referred as cơm sườn, is a Vietnamese dish made from broken rice, ribs, cucumbers, and pickled carrots, often served with sweet and sour fish sauce. Tấm refers to the broken rice grains, while cơm refers to cooked rice. Although there are varied names like cơm tấm Sài Gòn, particularly for Saigon, the main ingredients remain the same for most cases.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/C%C6%A1m_T%E1%BA%A5m%2C_Da_Nang%2C_Vietnam.jpg/960px-C%C6%A1m_T%E1%BA%A5m%2C_Da_Nang%2C_Vietnam.jpg`,page:`https://commons.wikimedia.org/wiki/File:C%C6%A1m_T%E1%BA%A5m,_Da_Nang,_Vietnam.jpg`,artist:`Christopher Crouzet`,license:`CC BY-SA 4.0`}},"dish:Gỏi cuốn":{wiki:{title:`Gỏi cuốn`,url:`https://en.wikipedia.org/wiki/G%E1%BB%8Fi_cu%E1%BB%91n`,extract:`Gỏi cuốn, nem cuốn, salad roll, summer roll, fresh spring roll, or rice paper roll is a Vietnamese dish traditionally consisting of pork, prawn, vegetables, bún, and other ingredients wrapped in bánh tráng.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1a/Homemade_spring_rolls_%287010969349%29.jpg/960px-Homemade_spring_rolls_%287010969349%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Homemade_spring_rolls_(7010969349).jpg`,artist:`pelican from Tokyo, Japan`,license:`CC BY-SA 2.0`}},"dish:Hủ tiếu":{wiki:{title:`Hủ tiếu`,url:`https://en.wikipedia.org/wiki/H%E1%BB%A7_ti%E1%BA%BFu`,extract:`Hủ tiếu or Hủ tíu is a Vietnamese dish eaten in Vietnam as breakfast. It may be served either as a soup or dry with no broth.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/Hu_Tieu_Nam_Vang.jpg/960px-Hu_Tieu_Nam_Vang.jpg`,page:`https://commons.wikimedia.org/wiki/File:Hu_Tieu_Nam_Vang.jpg`,artist:`Dianne Flor Reyno`,license:`CC BY 2.0`}},"dish:Vietnamese iced coffee":{wiki:{title:`Vietnamese iced coffee`,url:`https://en.wikipedia.org/wiki/Vietnamese_iced_coffee`,extract:`Vietnamese iced coffee is a Vietnamese beverage made by pouring hot water through a traditional metal filter, called a phin, containing dark-roast robusta coffee grounds, into a small cup with sweetened condensed milk already in it. The contents of the cup are then stirred together and poured into a tall glass full of ice.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/b/b7/Viet-coffee.jpg`,page:`https://commons.wikimedia.org/wiki/File:Viet-coffee.jpg`,artist:`Mike Verdone`,license:`Public domain`}},"ho-chi-minh-city/Com Tam":{wiki:{title:`Cơm tấm`,url:`https://en.wikipedia.org/wiki/C%C6%A1m_t%E1%BA%A5m`,extract:`Cơm tấm, also referred as cơm sườn, is a Vietnamese dish made from broken rice, ribs, cucumbers, and pickled carrots, often served with sweet and sour fish sauce. Tấm refers to the broken rice grains, while cơm refers to cooked rice. Although there are varied names like cơm tấm Sài Gòn, particularly for Saigon, the main ingredients remain the same for most cases.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/C%C6%A1m_T%E1%BA%A5m%2C_Da_Nang%2C_Vietnam.jpg/960px-C%C6%A1m_T%E1%BA%A5m%2C_Da_Nang%2C_Vietnam.jpg`,page:`https://commons.wikimedia.org/wiki/File:C%C6%A1m_T%E1%BA%A5m,_Da_Nang,_Vietnam.jpg`,artist:`Christopher Crouzet`,license:`CC BY-SA 4.0`}},"ho-chi-minh-city/Banh Mi":{wiki:{title:`Bánh mì`,url:`https://en.wikipedia.org/wiki/B%C3%A1nh_m%C3%AC`,extract:`In Vietnamese cuisine, bánh mì, bánh mỳ or banh mi, is a short baguette with thin, crisp crust and a soft, airy texture. Similar to a submarine sandwich, it is often split lengthwise and filled with meat and savory ingredients and served as a meal, called bánh mì thịt. Plain bánh mì is also eaten as a staple food.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/0/0c/B%C3%A1nh_m%C3%AC_th%E1%BB%8Bt_n%C6%B0%E1%BB%9Bng.png`,page:`https://commons.wikimedia.org/wiki/File:B%C3%A1nh_m%C3%AC_th%E1%BB%8Bt_n%C6%B0%E1%BB%9Bng.png`,artist:`nsaum75 ¡שיחת! ‎`,license:`CC BY-SA 3.0`}},"ho-chi-minh-city/Hu Tieu":{wiki:{title:`Hủ tiếu`,url:`https://en.wikipedia.org/wiki/H%E1%BB%A7_ti%E1%BA%BFu`,extract:`Hủ tiếu or Hủ tíu is a Vietnamese dish eaten in Vietnam as breakfast. It may be served either as a soup or dry with no broth.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/Hu_Tieu_Nam_Vang.jpg/960px-Hu_Tieu_Nam_Vang.jpg`,page:`https://commons.wikimedia.org/wiki/File:Hu_Tieu_Nam_Vang.jpg`,artist:`Dianne Flor Reyno`,license:`CC BY 2.0`}},"ho-chi-minh-city/Banh Xeo":{wiki:{title:`Bánh xèo`,url:`https://en.wikipedia.org/wiki/B%C3%A1nh_x%C3%A8o`,extract:`Bánh xèo is a crispy, stuffed rice crepe popular in Vietnam. The name refers to the sound a thin layer of rice batter makes when it is poured into the hot skillet. It is a savoury fried pancake made of rice flour, water, and turmeric powder. It can also be called a Vietnamese crêpe. Some common stuffings include pork, prawns, diced green onion, mung bean, and bean sprouts. Bánh xèo is often served with side dishes.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/5/59/Banh_Xeo_with_fish_sauce_and_vegetables.jpg`,page:`https://commons.wikimedia.org/wiki/File:Banh_Xeo_with_fish_sauce_and_vegetables.jpg`,artist:`HungryHuy`,license:`CC BY 2.0`}},"ho-chi-minh-city/Goi Cuon":{wiki:{title:`Gỏi cuốn`,url:`https://en.wikipedia.org/wiki/G%E1%BB%8Fi_cu%E1%BB%91n`,extract:`Gỏi cuốn, nem cuốn, salad roll, summer roll, fresh spring roll, or rice paper roll is a Vietnamese dish traditionally consisting of pork, prawn, vegetables, bún, and other ingredients wrapped in bánh tráng.`},image:{src:`https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1a/Homemade_spring_rolls_%287010969349%29.jpg/960px-Homemade_spring_rolls_%287010969349%29.jpg`,page:`https://commons.wikimedia.org/wiki/File:Homemade_spring_rolls_(7010969349).jpg`,artist:`pelican from Tokyo, Japan`,license:`CC BY-SA 2.0`}},"ho-chi-minh-city/Ca Phe Sua Da":{wiki:{title:`Vietnamese iced coffee`,url:`https://en.wikipedia.org/wiki/Vietnamese_iced_coffee`,extract:`Vietnamese iced coffee is a Vietnamese beverage made by pouring hot water through a traditional metal filter, called a phin, containing dark-roast robusta coffee grounds, into a small cup with sweetened condensed milk already in it. The contents of the cup are then stirred together and poured into a tall glass full of ice.`},image:{src:`https://upload.wikimedia.org/wikipedia/commons/b/b7/Viet-coffee.jpg`,page:`https://commons.wikimedia.org/wiki/File:Viet-coffee.jpg`,artist:`Mike Verdone`,license:`Public domain`}}};export{e as default};